/**
 * Configuration atoms for DataTable
 * Centralizes all configuration options in one place
 */
import { atom } from "jotai";
import { atomFamily } from "jotai-family";

import type { TableFormConfig } from "../config/form-config";

/**
 * Interface for column-specific configuration options
 */
export interface DataTableColumnsConfig {
  /**
   * Default column order
   */
  defaultColumnOrder: string[];

  /**
   * Default sort configuration
   */
  defaultSort: { desc: boolean; id: string }[];

  /**
   * Default visible columns
   */
  defaultVisibleColumns: string[];

  /**
   * Columns that cannot be hidden
   */
  mandatoryColumns: string[];
}

/**
 * Interface for general DataTable configuration options
 */
export interface DataTableConfig {
  /**
   * Default page size
   */
  defaultPageSize: number;

  /**
   * Enable column drag and drop
   */
  enableColumnDragDropByDefault: boolean;

  /**
   * Enable the column drag & drop feature and UI (gate)
   * When false, the interface and actions to reorder columns are hidden/disabled
   */
  enableColumnDnd?: boolean;

  /**
   * Enable column filters
   */
  enableColumnFilters: boolean;

  /**
   * Enable column pinning
   */
  enableColumnPinning?: boolean;

  /**
   * Enable multi-row selection
   */
  enableMultiRowSelection: boolean;

  /**
   * Enable pagination
   */
  enablePagination: boolean;

  /**
   * Enable row drag and drop
   */
  enableRowDragDrop: boolean;

  /**
   * Enable row selection
   */
  enableRowSelection: boolean;

  /**
   * Enable sorting
   */
  enableSorting: boolean;

  /**
   * Enable grouping
   */
  enableGrouping?: boolean;

  /**
   * Form configuration
   */
  form?: TableFormConfig;

  /**
   * Enable manual filtering (server-side)
   */
  manualFiltering: boolean;

  /**
   * Enable manual pagination (server-side)
   */
  manualPagination: boolean;

  /**
   * Enable manual sorting (server-side)
   */
  manualSorting: boolean;

  /**
   * Available page size options
   */
  pageSizeOptions: number[];

  /**
   * Translations for the table
   */
  translations?: {
    keys: Record<string, string>;
    namespace: string;
  };
}

/**
 * Default table configuration
 */
const defaultTableConfig: DataTableConfig = {
  defaultPageSize: 10,
  enableColumnDragDropByDefault: true,
  enableColumnDnd: true,
  enableColumnFilters: true,
  enableMultiRowSelection: true,
  enablePagination: true,
  enableRowDragDrop: false,
  enableRowSelection: true,
  enableSorting: true,
  enableGrouping: true,
  manualFiltering: false,
  manualPagination: false,
  manualSorting: false,
  pageSizeOptions: [5, 10, 20, 50, 100],
};

/**
 * Default columns configuration
 */
const defaultColumnsConfig: DataTableColumnsConfig = {
  defaultColumnOrder: [],
  defaultSort: [],
  defaultVisibleColumns: [],
  mandatoryColumns: [],
};

/**
 * Atom for the default table configuration
 */
export const tableConfigAtom = atom<DataTableConfig>(defaultTableConfig);

/**
 * Atom family for table-specific configurations
 * This allows different tables to have different configurations
 */
export const tableConfigFamilyAtom = atomFamily(
  (_tableId: string) => atom<DataTableConfig>(defaultTableConfig),
  (a, b) => a === b
);

/**
 * Atom for the default columns configuration
 */
export const tableColumnsConfigAtom =
  atom<DataTableColumnsConfig>(defaultColumnsConfig);

/**
 * Atom family for table-specific column configurations
 * This allows different tables to have different column configurations
 */
export const tableColumnsConfigFamilyAtom = atomFamily(
  (_tableId: string) => atom<DataTableColumnsConfig>(defaultColumnsConfig),
  (a, b) => a === b
);

/**
 * Filter atoms for DataTable component
 * These atoms manage filter-related state
 */
import type { ColumnFiltersState } from "@tanstack/react-table";
import { atom } from "jotai";
import { atomFamily } from "jotai-family";

import { columnFiltersAtom } from "./table-atoms";

// Regex patterns for column ID extraction - moved to top-level for performance
const ACCESSOR_KEY_PATTERNS = [
  /accessorKey:\s*["']([^"']+)["']/i,
  /accessorKey=\{["']([^"']+)["']\}/i,
  /accessorKey=["']([^"']+)["']/i,
] as const;

// Translation patterns for column ID extraction - moved to top-level for performance
const TRANSLATION_PATTERNS = [
  /title:\s*t\(["']([^"']+)["']\)/i,
  /title=\{t\(["']([^"']+)["']\)\}/i,
  /header:\s*t\(["']([^"']+)["']\)/i,
  /header=\{t\(["']([^"']+)["']\)\}/i,
  /t\(["']([^"']+)["']\)/i, // Generic t() call
  /\{t\(["']([^"']+)["']\)\}/i, // Generic {t()} call
] as const;

// ID patterns for column ID extraction - moved to top-level for performance
const ID_PATTERNS = [
  /id:\s*["']([^"']+)["']/i,
  /id=\{["']([^"']+)["']\}/i,
  /id=["']([^"']+)["']/i,
] as const;

// Header component pattern - moved to top-level for performance
const HEADER_COMPONENT_PATTERN = /header:\s*\(\{[^}]*\}\)\s*=>\s*<([^>]+)/;

/**
 * Interface for a filter preset
 * Represents a saved filter configuration
 */
export interface FilterPreset {
  filters: ColumnFiltersState;
  id: string;
  isDefault?: boolean;
  name: string;
  tableId: string;
}

// Helper function to check if columnId needs cleaning
const needsCleaning = (columnId: string): boolean => {
  return (
    columnId.includes("__TURBOPACK_") ||
    columnId.includes("(") ||
    columnId.includes(")")
  );
};

// Helper function to extract accessor key
const extractAccessorKey = (columnId: string): string | null => {
  for (const pattern of ACCESSOR_KEY_PATTERNS) {
    const match = columnId.match(pattern);
    if (match?.[1]) {
      return match[1];
    }
  }
  return null;
};

// Helper function to extract translation key
const extractTranslationKey = (columnId: string): string | null => {
  for (const pattern of TRANSLATION_PATTERNS) {
    const match = columnId.match(pattern);
    if (match?.[1]) {
      return match[1];
    }
  }
  return null;
};

// Helper function to extract ID
const extractId = (columnId: string): string | null => {
  for (const pattern of ID_PATTERNS) {
    const match = columnId.match(pattern);
    if (match?.[1]) {
      return match[1];
    }
  }
  return null;
};

// Helper function to extract header component name
const extractHeaderComponent = (columnId: string): string | null => {
  const match = columnId.match(HEADER_COMPONENT_PATTERN);
  if (match?.[1]) {
    return match[1].split(" ")[0];
  }
  return null;
};

// Helper function to clean path and remove special characters
const cleanPath = (columnId: string): string => {
  const parts = columnId.split("/");
  const lastPart = parts.at(-1);

  return (lastPart || columnId)
    .replace(/\[.*?\]/g, "")
    .replace(/\(.*?\)/g, "")
    .replace(/\{.*?\}/g, "")
    .replace(/".*?"/g, "")
    .replace(/__TURBOPACK__.*?__/g, "")
    .replace(/[^a-zA-Z0-9]/g, "")
    .trim();
};

/**
 * Helper function to clean Turbopack references from column IDs
 * @param columnId Column ID that might contain Turbopack references
 * @returns Cleaned column ID
 */
export function cleanColumnId(columnId: string): string {
  if (typeof columnId !== "string") {
    return String(columnId);
  }

  // If it doesn't need cleaning, return as is
  if (!needsCleaning(columnId)) {
    return columnId;
  }

  // Try different extraction methods in order of preference
  const accessorKey = extractAccessorKey(columnId);
  if (accessorKey) {
    return accessorKey;
  }

  const translationKey = extractTranslationKey(columnId);
  if (translationKey) {
    return translationKey;
  }

  const id = extractId(columnId);
  if (id) {
    return id;
  }

  const headerComponent = extractHeaderComponent(columnId);
  if (headerComponent) {
    return headerComponent;
  }

  // If all else fails, clean the path
  const cleaned = cleanPath(columnId);
  return cleaned || "column";
}

/**
 * Atom family for storing filter presets for a specific table
 * Keyed by tableId
 */
export const filterPresetsAtom = atomFamily((_tableId: string) =>
  atom<FilterPreset[]>([])
);

/**
 * Atom family for storing the active filter preset ID
 * Keyed by tableId
 */
export const activeFilterPresetIdAtom = atomFamily((_tableId: string) =>
  atom<null | string>(null)
);

/**
 * Atom family for storing whether the filter panel is open
 * Keyed by tableId
 */
export const isFilterPanelOpenAtom = atomFamily((_tableId: string) =>
  atom<boolean>(false)
);

/**
 * Derived atom family that returns the active filter preset
 * Keyed by tableId
 */
export const activeFilterPresetAtom = atomFamily((tableId: string) =>
  atom((get) => {
    const presetId = get(activeFilterPresetIdAtom(tableId));
    const presets = get(filterPresetsAtom(tableId));

    if (!presetId) {
      return null;
    }
    return presets.find((preset) => preset.id === presetId) || null;
  })
);

/**
 * Atom family for tracking whether filters have been modified
 * Compares current filters with the active preset
 * Keyed by tableId
 */
export const hasFilterChangesAtom = atomFamily((tableId: string) =>
  atom((get) => {
    const activePreset = get(activeFilterPresetAtom(tableId));
    const currentFilters = get(columnFiltersAtom(tableId));

    if (!activePreset) {
      return currentFilters.length > 0;
    }

    // Simple comparison - in a real app you might want a deeper comparison
    return (
      JSON.stringify(activePreset.filters) !== JSON.stringify(currentFilters)
    );
  })
);

/**
 * Atom family that provides normalized column filters with cleaned IDs
 * This helps prevent issues with Turbopack references in column IDs
 * Keyed by tableId
 */
export const normalizedColumnFiltersAtom = atomFamily((tableId: string) =>
  atom((get) => {
    const columnFilters = get(columnFiltersAtom(tableId));

    // Normalize column filters by cleaning their IDs
    return columnFilters.map((filter) => ({
      ...filter,
      id: cleanColumnId(filter.id as string),
    }));
  })
);

/**
 * Atom family for storing a mapping between original column IDs and their cleaned versions
 * This helps maintain consistency when applying filters
 * Keyed by tableId
 */
export const columnIdMappingAtom = atomFamily((tableId: string) =>
  atom((get) => {
    const columnFilters = get(columnFiltersAtom(tableId));

    // Create a mapping of original IDs to cleaned IDs
    const mapping = new Map<string, string>();

    for (const filter of columnFilters) {
      const originalId = filter.id as string;
      const cleanedId = cleanColumnId(originalId);

      if (originalId !== cleanedId) {
        mapping.set(originalId, cleanedId);
        mapping.set(cleanedId, originalId); // Bidirectional mapping
      }
    }

    return mapping;
  })
);

/**
 * Translation atoms for DataTable component
 * These atoms provide centralized translation management
 */
import { atom } from "jotai";
import { atomFamily } from "jotai-family";

/**
 * Interface defining all translation keys used in the DataTable
 * This acts as a "translation API" for the component
 */
export interface DataTableUiStrings {
  // Filters
  activeFilters: string;
  addFilter: string;
  addView: string;
  applyFilters: string;
  cancel: string;

  clearFilters: string;
  close: string;
  // Column menu
  columnEditProperty: string;
  columnFilter: string;
  columnHide: string;
  columnReorder: string;
  columnSortAsc: string;

  columnSortDesc: string;
  columnsTitle: string;
  confirm: string;
  confirmDeleteView: string;
  create: string;
  customView: string;
  // Views
  defaultView: string;
  delete: string;
  deleteView: string;
  dragColumn: string;
  edit: string;
  error: string;
  // Messages
  errorDescription: string;
  false: string;

  filterBetween: string;
  filterColumn: string;
  filterContains: string;
  filterEmpty: string;
  filterError: string;
  filterNotEmpty: string;
  filterOperator: string;
  filterTitle: string;
  filterValue: string;
  filterValueTo: string;
  firstPage: string;
  hideAll: string;
  hideColumn: string;

  // History
  historyNothingToRedo: string;
  historyNothingToUndo: string;
  isDefaultView: string;
  lastPage: string;
  loading: string;
  manageViews: string;
  nextPage: string;
  noFilters: string;
  // General
  noResults: string;
  noResultsDescription: string;
  of: string;

  page: string;
  pageXofY: string;
  // Pagination
  previousPage: string;
  redo: string;
  renameView: string;
  reset: string;
  resetColumns: string;

  rowsPerPage: string;
  // Actions
  save: string;

  saveView: string;
  saveViewDefaultLabel: string;
  saveViewDescription: string;
  saveViewNameLabel: string;
  saveViewNamePlaceholder: string;
  // Dialogs
  saveViewTitle: string;
  search: string;
  searchPlaceholder: string;
  selectedRows: string;
  showAll: string;
  showColumn: string;

  showingPage: string;
  showingRows: string;
  sortAscending: string;
  sortDescending: string;
  success: string;
  systemView: string;
  // Table controls
  toggleColumns: string;
  true: string;
  undo: string;
  updateView: string;
  viewCantDeleteSystem: string;
  viewCantUpdateSystem: string;
  viewCreated: string;
  viewDeleted: string;
  viewDeleteError: string;
  viewDeleteSuccess: string;
  viewError: string;
  viewLoadError: string;
  viewName: string;
  viewOptions: string;
  viewSaveError: string;
  viewSaveSuccess: string;
  viewTemporary: string;
  viewUpdated: string;
  viewUpdateError: string;
  viewUpdateSuccess: string;
}

/**
 * Atom to store the actual translated values
 * This is populated by the translation provider
 */
export const translationsAtom = atom<
  Partial<Record<keyof DataTableUiStrings, string>>
>({});

/**
 * Atom to check if translations have been initialized
 */
export const translationsInitializedAtom = atom<boolean>(false);

/**
 * Atom family for storing table-specific translation overrides
 * Allows customizing translations for specific tables
 */
export const tableTranslationOverridesAtom = atomFamily((_tableId: string) =>
  atom<Partial<Record<keyof DataTableUiStrings, string>>>({})
);

/**
 * Derived atom family that combines global translations with table-specific overrides
 * Keyed by tableId
 */
export const tableTranslationsAtom = atomFamily((tableId: string) =>
  atom((get) => {
    const globalTranslations = get(translationsAtom);
    const tableOverrides = get(tableTranslationOverridesAtom(tableId));

    // Merge global translations with table-specific overrides
    return { ...globalTranslations, ...tableOverrides };
  })
);

/**
 * Default translation keys mapping
 * Maps each UI string to its corresponding translation key in the translations file
 */
export const translationKeysMap: DataTableUiStrings = {
  // Filters
  activeFilters: "filters.active_count",
  addFilter: "filters.add",
  addView: "views.add_view",
  applyFilters: "filters.apply",
  cancel: "actions.cancel",

  clearFilters: "filters.clear",
  close: "actions.close",
  // Column menu
  columnEditProperty: "columns.edit_property",
  columnFilter: "columns.filter",
  columnHide: "columns.hide_in_view",
  columnReorder: "columns.reorder",
  columnSortAsc: "columns.sort_ascending",

  columnSortDesc: "columns.sort_descending",
  columnsTitle: "columns.title",
  confirm: "actions.confirm",
  confirmDeleteView: "views.confirmDelete",
  create: "actions.create",
  customView: "views.custom_view",
  // Views
  defaultView: "views.default_system_view",
  delete: "actions.delete",
  deleteView: "views.delete",
  dragColumn: "table.drag_column",
  edit: "actions.edit",
  error: "common.error",
  // Messages
  errorDescription: "state.error_description",
  false: "common.false",

  filterBetween: "filters.operators.between",
  filterColumn: "filters.column",
  filterContains: "filters.operators.contains",
  filterEmpty: "filters.operators.empty",
  filterError: "filters.error",
  filterNotEmpty: "filters.operators.not_empty",
  filterOperator: "filters.select_operator",
  filterTitle: "filters.title",
  filterValue: "filters.value",
  filterValueTo: "filters.value_to",
  firstPage: "pagination.first",
  hideAll: "columns.hideAll",

  hideColumn: "table.hide_column",
  // History
  historyNothingToRedo: "views.history.nothing_to_redo",
  historyNothingToUndo: "views.history.nothing_to_undo",
  isDefaultView: "views.setDefault",
  lastPage: "pagination.last",
  loading: "common.loading",
  manageViews: "views.manage",
  nextPage: "pagination.next",
  noFilters: "filters.noFilters",
  // General
  noResults: "table.no_results",
  noResultsDescription: "table.no_results_description",

  of: "pagination.of",
  page: "pagination.page",
  pageXofY: "pagination.showing",
  // Pagination
  previousPage: "pagination.previous",
  redo: "views.history.redo",
  renameView: "views.rename",

  reset: "common.reset",
  resetColumns: "columns.resetOrder",

  rowsPerPage: "pagination.rowsPerPage",
  // Actions
  save: "actions.save",
  saveView: "views.save",
  saveViewDefaultLabel: "views.dialog.save.default",
  saveViewDescription: "views.dialog.save.description",
  saveViewNameLabel: "views.dialog.save.name",
  saveViewNamePlaceholder: "views.dialog.save.namePlaceholder",
  // Dialogs
  saveViewTitle: "views.dialog.save.title",
  search: "common.search",
  searchPlaceholder: "search.placeholder",

  selectedRows: "table.selected_rows",
  showAll: "columns.showAll",
  showColumn: "table.show_column",
  showingPage: "pagination.showing",
  showingRows: "pagination.selectedCount",
  sortAscending: "table.sort_ascending",
  sortDescending: "table.sort_descending",
  success: "common.success",
  systemView: "views.systemView",
  // Table controls
  toggleColumns: "table.toggle_columns",
