/**
 * Atom for translation keys (injection point)
 * Allows complete replacement of translation keys if needed
 */
export const dataTableTranslationKeysAtom =
  atom<DataTableUiStrings>(translationKeysMap);

/**
 * Atom for resolved translations
 * Components use this atom directly, without knowing how translations are resolved
 */
export const resolvedTranslationsAtom = atom<DataTableUiStrings>(
  {} as DataTableUiStrings
);

/**
 * Index file for all DataTable atoms
 * Re-exports atoms from other files for easier imports
 */

// Export all atoms from their respective files
export * from "./filter-atoms";
export * from "./i18n-atoms";
export * from "./table-atoms";
export * from "./view-atoms";

// Optimized atoms were removed as they weren't being used

import type {
  ColumnFiltersState,
  ExpandedState,
  GroupingState,
  PaginationState,
  RowSelectionState,
  SortingState,
  VisibilityState,
} from "@tanstack/react-table";
/**
 * Base atoms for DataTable component
 * These atoms provide core functionality used across the DataTable
 */
import { atom } from "jotai";
import { atomWithStorage } from "jotai/utils";
import { atomFamily } from "jotai-family";

import type { DataTableColumnDef } from "../types/column-types";

/**
 * Atom to store the current table ID
 * This is used to identify the table across the application
 */
export const tableIdAtom = atom<string>("");

/**
 * Atom family to store column definitions for a specific table
 * Keyed by tableId
 */
export const columnsAtom = atomFamily((_tableId: string) =>
  atom<DataTableColumnDef<Record<string, unknown>>[]>([])
);

/**
 * Store column translations by table ID
 * Maps column IDs to their translated headers
 */
export const columnTranslationsAtom = atomFamily((_tableId: string) =>
  atom<Record<string, string>>({})
);

// Note: columnIdMappingAtom is defined in filter-atoms.ts

/**
 * Derived atom that combines column definitions with their translations
 * This provides a complete view of columns with translated headers
 */
export const translatedColumnsAtom = atomFamily((tableId: string) =>
  atom((get) => {
    const columns = get(columnsAtom(tableId));
    const translations = get(columnTranslationsAtom(tableId));

    return columns.map(
      (column: DataTableColumnDef<Record<string, unknown>>) => ({
        ...column,
        translatedHeader: translations[column.id] || column.header,
      })
    );
  })
);

/**
 * Atom family to store sorting state for a specific table
 * Keyed by tableId
 */
export const sortingAtom = atomFamily((_tableId: string) =>
  atom<SortingState>([])
);

/**
 * Atom family to store column filters state for a specific table
 * Keyed by tableId
 */
export const columnFiltersAtom = atomFamily((_tableId: string) =>
  atom<ColumnFiltersState>([])
);

/**
 * Atom family to store global filter state for a specific table
 * Used for filtering across all columns
 * Keyed by tableId
 */
export const globalFilterAtom = atomFamily((_tableId: string) =>
  atom<string>("")
);

/**
 * Atom family to store column visibility state for a specific table
 * Keyed by tableId
 */
export const columnVisibilityAtom = atomFamily((_tableId: string) =>
  atom<VisibilityState>({})
);

/**
 * Atom family to store column order state for a specific table
 * Keyed by tableId
 */
export const columnOrderAtom = atomFamily((_tableId: string) =>
  atom<string[]>([])
);

/**
 * Atom family to store pagination state for a specific table
 * Keyed by tableId
 */
export const paginationAtom = atomFamily((_tableId: string) =>
  atom<PaginationState>({
    pageIndex: 0,
    pageSize: 10,
  })
);

/**
 * Atom family to store row selection state for a specific table
 * Not persisted in views as it's a transient state
 * Keyed by tableId
 */
export const rowSelectionAtom = atomFamily((_tableId: string) =>
  atom<RowSelectionState>({})
);

/**
 * Atom family to store expanded state for a specific table
 * Used for expandable rows or tree-like structures
 * Keyed by tableId
 */
export const expandedAtom = atomFamily((_tableId: string) =>
  atom<ExpandedState>({})
);

/**
 * Atom family to store grouping state for a specific table
 * Used for row grouping functionality
 * Keyed by tableId
 */
export const groupingAtom = atomFamily((_tableId: string) =>
  atom<GroupingState>([])
);

/**
 * Atom family for row ordering
 * Used for drag and drop reordering of rows
 * Persisted to localStorage to maintain order between sessions
 */
export const rowOrderAtom = atomFamily((tableId: string) =>
  atomWithStorage<string[]>(`${tableId}-row-order`, [])
);

/**
 * Atom family for tracking active row drag
 * Used to highlight the currently dragged row
 */
export const activeRowDragAtom = atomFamily((_tableId: string) =>
  atom<null | string>(null)
);

/**
 * Atom family for tracking active column drag
 * Used to highlight the currently dragged column
 */
export const activeColumnDragAtom = atomFamily((_tableId: string) =>
  atom<null | string>(null)
);

/**
 * Atom family for tracking if row drag is enabled
 * This can be toggled by the user or disabled for certain tables
 */
export const rowDragEnabledAtom = atomFamily((tableId: string) =>
  atomWithStorage<boolean>(`${tableId}-row-drag-enabled`, true)
);

/**
 * Atom family for tracking if column drag is enabled
 * This can be toggled by the user or disabled for certain tables
 */
export const columnDragEnabledAtom = atomFamily((tableId: string) =>
  atomWithStorage<boolean>(`${tableId}-column-drag-enabled`, true)
);

/**
 * Atom family for "open Options stack menu to this view" (e.g. "filters" when clicking Filter in column header menu)
 * When set, the toolbar TableMenu opens and navigates to that view; cleared when the menu closes.
 */
export const tableMenuOpenToViewAtom = atomFamily((_tableId: string) =>
  atom<null | string>(null)
);

/**
 * When opening the filters view from a column header Filter click, open the filter for this column id.
 * Cleared when the filter panel has consumed it or when the menu closes.
 */
export const tableMenuOpenFilterColumnIdAtom = atomFamily((_tableId: string) =>
  atom<null | string>(null)
);

/**
 * Atom to store whether the table is in a loading state
 * Used for showing loading indicators
 */
export const isLoadingAtom = atom<boolean>(false);

/**
 * Atom to store any error that occurred during table operations
 * Used for showing error messages
 */
export const errorAtom = atom<null | string>(null);

/**
 * Atom to store whether the table is in debug mode
 * When in debug mode, additional logging and UI elements may be displayed
 */
export const isDebugModeAtom = atom<boolean>(
  process.env.NODE_ENV === "development"
);

/**
 * Atom family to store table features configuration
 * Controls which features are enabled for a specific table
 * Keyed by tableId
 */
export const featuresAtom = atomFamily((_tableId: string) =>
  atom({
    enableColumnFilters: true,
    enableColumnResizing: false,
    enableColumnVisibility: true,
    enableExpanding: true,
    enableGrouping: true,
    enablePagination: true,
    enablePinning: true,
    enableRowSelection: true,
    enableServerSide: true,
    enableSorting: true,
  })
);

"use client";

import { atom } from "jotai";
import { atomFamily } from "jotai-family";

import type { TableView } from "../types/view-types";

/**
 * Atom family for storing the active view ID for each table
 */
export const activeViewIdAtom = atomFamily(
  (_tableId: string) => atom<null | string>(null),
  (a, b) => a === b
);

/**
 * Atom family for storing system-defined views for each table
 */
export const systemViewsAtom = atomFamily(
  (_tableId: string) => atom<TableView[]>([]),
  (a, b) => a === b
);

/**
 * Atom family for storing user-defined views for each table
 */
export const tableViewsAtom = atomFamily(
  (_tableId: string) => atom<TableView[]>([]),
  (a, b) => a === b
);

/**
 * Bulk Actions Menu Component
 * An overlay menu that appears when rows are selected, using expandable tabs design
 */
"use client";

import type { Row } from "@tanstack/react-table";
import { AnimatePresence, motion } from "framer-motion";
import { Copy, Edit, Trash2, X } from "lucide-react";
import { useRef, useState } from "react";
import { useOnClickOutside } from "usehooks-ts";
import { cn } from "@/lib/utils";
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from "@/components/ui/alert-dialog";
import { Button } from "@/components/ui/button";
import { useTranslations } from "../../providers/table-provider";

/**
 * Props for the BulkActionsMenu component
 */
export interface BulkActionsMenuProps<TData> {
  /**
   * Array of selected rows
   */
  selectedRows: Row<TData>[];

  /**
   * Callback when bulk edit is triggered
   */
  onBulkEdit?: (rows: Row<TData>[]) => void;

  /**
   * Callback when bulk delete is triggered
   */
  onBulkDelete?: (rows: Row<TData>[]) => void;

  /**
   * Callback when bulk copy is triggered
   */
  onBulkCopy?: (rows: Row<TData>[]) => void;

  /**
   * Callback when menu is closed
   */
  onClose?: () => void;

  /**
   * Optional CSS class name
   */
  className?: string;
}

// Configuration pour les tabs d'actions
interface ActionTab {
  id: string;
  icon: React.ComponentType<{ size?: number }>;
  translationKey: string;
  variant: "default" | "destructive";
}

// Variants pour les animations
const buttonVariants = {
  initial: {
    gap: 0,
    paddingLeft: ".5rem",
    paddingRight: ".5rem",
  },
  animate: (isExpanded: boolean) => ({
    gap: isExpanded ? ".5rem" : 0,
    paddingLeft: isExpanded ? "1rem" : ".5rem",
    paddingRight: isExpanded ? "1rem" : ".5rem",
  }),
};

const spanVariants = {
  initial: { width: 0, opacity: 0 },
  animate: { width: "auto", opacity: 1 },
  exit: { width: 0, opacity: 0 },
};

const transition = {
  delay: 0.1,
  type: "spring" as const,
  bounce: 0,
  duration: 0.6,
};

/**
 * BulkActionsMenu Component
 *
 * Displays an overlay menu with expandable tabs for bulk actions
 * when multiple rows are selected in the data table
 */
export function BulkActionsMenu<TData>({
  selectedRows,
  onBulkEdit,
  onBulkDelete,
  onBulkCopy,
  onClose,
  className,
}: BulkActionsMenuProps<TData>) {
  const [selectedAction, setSelectedAction] = useState<string | null>(null);
  const [hoveredAction, setHoveredAction] = useState<string | null>(null);
  const [showConfirmation, setShowConfirmation] = useState(false);
  const outsideClickRef = useRef<HTMLDivElement>(null);
  const { t } = useTranslations();

  // Only show actions that have handlers. Edit is shown when onBulkEdit is provided.
  const actionTabs: ActionTab[] = [
    ...(onBulkEdit
      ? [
          {
            id: "edit",
            icon: Edit,
            translationKey: "actions.edit",
            variant: "default" as const,
          },
        ]
      : []),
    {
      id: "copy",
      icon: Copy,
      translationKey: "actions.copy",
      variant: "default",
    },
    {
      id: "delete",
      icon: Trash2,
      translationKey: "actions.delete",
      variant: "destructive",
    },
  ];

  useOnClickOutside(outsideClickRef as React.RefObject<HTMLElement>, () => {
    setSelectedAction(null);
    setHoveredAction(null);
    setShowConfirmation(false);
  });

  // Don't render if no rows are selected
  if (!selectedRows || selectedRows.length === 0) {
    return null;
  }

  const selectedCount = selectedRows.length;

  const handleTabClick = (actionId: string) => {
    // Pour l'édition, ouvrir directement le formulaire sans confirmation
    if (actionId === "edit") {
      onBulkEdit?.(selectedRows);
      onClose?.();
      return;
    }

    // Pour les autres actions, afficher la confirmation
    setSelectedAction(actionId);
    setShowConfirmation(true);
  };

  const handleConfirmAction = () => {
    if (!selectedAction) {
      return;
    }

    // Execute action based on ID
    switch (selectedAction) {
      case "copy":
        onBulkCopy?.(selectedRows);
        break;
      case "delete":
        onBulkDelete?.(selectedRows);
        break;
      default:
        break;
    }

    // Close after action
    setSelectedAction(null);
    setShowConfirmation(false);
    onClose?.();
  };

  const handleCancel = () => {
    setSelectedAction(null);
    setShowConfirmation(false);
  };

  const handleClose = () => {
    setSelectedAction(null);
    setHoveredAction(null);
    setShowConfirmation(false);
    onClose?.();
  };

  const getSelectedAction = () => {
    return actionTabs.find((tab) => tab.id === selectedAction);
  };

  // deprecated: button variant now handled by AlertDialogAction styling

  return (
    <div
      className={cn(
        "fixed bottom-10 left-1/2 z-50 -translate-x-1/2 transform",
        "fade-in-0 slide-in-from-bottom-2 animate-in",
        "duration-300 ease-out",
        className
      )}
    >
      <div className="flex flex-col items-center space-y-4">
        {/* Confirmation dialog (consistent AlertDialog for copy/delete) */}
        <AlertDialog
          onOpenChange={(open) => {
            if (!open) {
              handleCancel();
            }
          }}
          open={showConfirmation && !!selectedAction}
        >
          <AlertDialogContent>
            <AlertDialogHeader>
              <AlertDialogTitle>
                {t("bulk.confirm_title", {
                  action: t(getSelectedAction()?.translationKey || ""),
                  count: selectedCount,
                })}
              </AlertDialogTitle>
              {selectedAction === "delete" ? (
                <AlertDialogDescription>
                  {t("bulk.confirm_delete_description")}
                </AlertDialogDescription>
              ) : (
                <AlertDialogDescription>
                  {t("bulk.confirm_copy_description", {
                    count: selectedCount,
                  })}
                </AlertDialogDescription>
              )}
            </AlertDialogHeader>
            <AlertDialogFooter>
              <AlertDialogCancel onClick={handleCancel}>
                {t("actions.cancel")}
              </AlertDialogCancel>
              <AlertDialogAction
                className={
                  selectedAction === "delete"
                    ? "bg-destructive text-destructive-foreground hover:bg-destructive/90"
                    : undefined
                }
                onClick={handleConfirmAction}
              >
                {t("actions.confirm")}
              </AlertDialogAction>
            </AlertDialogFooter>
          </AlertDialogContent>
        </AlertDialog>

        {/* Main menu with custom expandable tabs */}
        <div
          className="flex flex-wrap items-center gap-2 rounded-2xl border bg-background/95 p-1 shadow-lg backdrop-blur-sm"
          ref={outsideClickRef}
        >
          {/* Count indicator */}
          <div className="flex items-center gap-2 px-3">
            <div className="h-2 w-2 animate-pulse rounded-full bg-primary" />
            <span className="font-medium text-foreground text-sm">
              {t("selection.rows", { count: selectedCount })}
            </span>
          </div>

          {/* Action tabs */}
          {actionTabs.map((tab) => {
            const Icon = tab.icon;
            const isExpanded =
              hoveredAction === tab.id || selectedAction === tab.id;

            return (
              <motion.button
                animate="animate"
                className={cn(
                  "relative flex items-center rounded-xl px-4 py-2 font-medium text-sm transition-colors duration-300",
                  tab.variant === "destructive"
                    ? "text-destructive hover:bg-destructive/10 hover:text-destructive"
                    : "text-muted-foreground hover:bg-muted hover:text-foreground"
                )}
                custom={isExpanded}
                initial={false}
                key={tab.id}
                onClick={() => handleTabClick(tab.id)}
                onMouseEnter={() => setHoveredAction(tab.id)}
                onMouseLeave={() => setHoveredAction(null)}
                transition={transition}
                variants={buttonVariants}
              >
                <Icon size={20} />
                <AnimatePresence initial={false}>
                  {isExpanded && (
                    <motion.span
                      animate="animate"
                      className="overflow-hidden whitespace-nowrap"
                      exit="exit"
                      initial="initial"
                      transition={transition}
                      variants={spanVariants}
                    >
                      {t(tab.translationKey)}
                    </motion.span>
                  )}
                </AnimatePresence>
              </motion.button>
            );
          })}

          {/* Separator */}
          <div
            aria-hidden="true"
            className="mx-1 h-[24px] w-[1.2px] bg-border"
          />

          {/* Close button */}
          <Button
            aria-label={t("bulk.close_menu")}
            className="h-8 w-8 p-0 hover:bg-muted"
            onClick={handleClose}
            size="sm"
            variant="ghost"
          >
            <X className="h-3 w-3" />
          </Button>
        </div>
      </div>
    </div>
  );
}

