      return <span className="text-muted-foreground">Invalid date</span>;
    }

    const formatString = showTime ? `${dateFormat} HH:mm` : dateFormat;
    return <span className={className}>{format(date, formatString)}</span>;
  } catch (_error) {
    return <span className="text-muted-foreground">Invalid date</span>;
  }
}

