/**
 * Hook for managing column actions
 * Provides utilities for column visibility, ordering, and other UI actions
 * Uses URL state for shareable states (order, visibility) and atoms for local states (translations, definitions)
 */
"use client";

import { useQuery } from "@tanstack/react-query";
import type { AccessorFn, ColumnDef, ColumnMeta } from "@tanstack/react-table";
import { useAtom } from "jotai";
import { useCallback, useMemo, useRef } from "react";
import {
  cleanColumnId,
  columnIdMappingAtom,
} from "../../../atoms/filter-atoms";
import {
  columnsAtom,
  columnTranslationsAtom,
} from "../../../atoms/table-atoms";
import { useTableUrlState } from "../../../hooks/use-table-url-state";
import type { DataTableColumnDef } from "../../../types/column-types";

interface UseColumnActionsOptions<
  TData extends Record<string, unknown> = Record<string, unknown>,
> {
  columns?: Array<ColumnDef<TData> | DataTableColumnDef<TData>>;
  tableId: string;
}

/**
 * Hook for managing column actions like visibility, ordering, etc.
 * @param options - Configuration options
 * @returns Object with column action utilities
 */
export function useColumnActions<
  TData extends Record<string, unknown> = Record<string, unknown>,
>({ columns: externalColumns, tableId }: UseColumnActionsOptions<TData>) {
  // Use refs to prevent infinite loops
  const initialized = useRef(false);
  const processingColumns = useRef(false);

  // **URL STATE** - for shareable states (order, visibility)
  const { orderParam, setOrderFromUI, visibilityParam, setVisibilityFromUI } =
    useTableUrlState({
      tableId,
    });

  // **ATOMS** - only for local states (translations, definitions)
  const [columns, setColumns] = useAtom(columnsAtom(tableId));
  const [columnTranslations, setColumnTranslations] = useAtom(
    columnTranslationsAtom(tableId)
  );
  const [columnIdMapping, _setColumnIdMapping] = useAtom(
    columnIdMappingAtom(tableId)
  );

  // Get current state from URL state
  const columnOrder = (orderParam as string[]) || [];
  const columnVisibility = (visibilityParam as Record<string, boolean>) || {};

  // Using cleanColumnId from filter-atoms.ts

  // Get a consistent column ID
  const getColumnId = useCallback(
    (
      column:
        | ColumnDef<TData>
        | DataTableColumnDef<TData>
        | DataTableColumnDef<Record<string, unknown>>,
      index?: number
    ): string => {
      // Use id if it's a string
      if (typeof column.id === "string") {
        // Check mapping first
        if (columnIdMapping.has(column.id)) {
          return columnIdMapping.get(column.id) || column.id;
        }

        // Clean Turbopack references
        if (column.id.includes("__TURBOPACK__")) {
          return cleanColumnId(column.id);
        }

        return column.id;
      }

      // Try accessorKey
      const accessorKey =
        (column as DataTableColumnDef<TData>).accessorKey ||
        (column as ColumnDef<TData> & { accessorKey?: string }).accessorKey;
      if (accessorKey !== undefined) {
        return String(accessorKey);
      }

      // Try header
      if (typeof column.header === "string") {
        return `col-${column.header.toLowerCase().replace(/\s+/g, "-")}`;
      }

      // Fallback to index
      return `col-${tableId}-${index || 0}`;
    },
    [tableId, columnIdMapping]
  );

  // Use a stable reference for the query function to prevent unnecessary re-renders
  // This function will only run once when the component mounts
  const processColumnsFn = useCallback(() => {
    // Double-check to prevent multiple executions
    if (
      !externalColumns?.length ||
      initialized.current ||
      processingColumns.current
    ) {
      return null;
    }

    // Set processing flag to prevent concurrent executions
    processingColumns.current = true;

    // Process external columns

    // Helper function to get column ID
    const getColumnIdFromDef = (
      columnDef: ColumnDef<TData>,
      index: number
    ): string => {
      if (columnDef.id) {
        return columnDef.id;
      }

      const columnWithAccessor = columnDef as ColumnDef<TData> & {
        accessorKey?: string;
      };
      if (columnWithAccessor.accessorKey) {
        return String(columnWithAccessor.accessorKey);
      }

      return getColumnId(columnDef, index);
    };

    // Helper function to get header text
    const getHeaderText = (columnDef: ColumnDef<TData>): string => {
      if (typeof columnDef.header === "string") {
        return columnDef.header;
      }

      const columnWithAccessor = columnDef as ColumnDef<TData> & {
        accessorKey?: string;
      };
      if (columnWithAccessor.accessorKey) {
        const accessorKey = String(columnWithAccessor.accessorKey);
        return (
          accessorKey.charAt(0).toUpperCase() +
          accessorKey
            .slice(1)
            .replace(/([A-Z])/g, " $1")
            .trim()
        );
      }

      return "";
    };

    // Helper function to process single column
    const processColumn = (
      col: ColumnDef<TData> | DataTableColumnDef<TData>,
      index: number
    ): DataTableColumnDef<TData> => {
      // Already a DataTableColumnDef
      if ((col as DataTableColumnDef<TData>).type !== undefined) {
        return col as DataTableColumnDef<TData>;
      }

      const columnDef = col as ColumnDef<TData>;
      const id = getColumnIdFromDef(columnDef, index);
      let headerText = getHeaderText(columnDef);

      // If no header text found, use ID as fallback
      if (!headerText) {
        headerText =
          id.charAt(0).toUpperCase() +
          id
            .slice(1)
            .replace(/([A-Z])/g, " $1")
            .trim();
      }

      const columnWithAccessor = columnDef as ColumnDef<TData> & {
        accessorKey?: string;
      };

      return {
        accessorFn: (
          columnDef as ColumnDef<TData> & {
            accessorFn?: (row: TData) => unknown;
          }
        ).accessorFn,
        accessorKey: columnWithAccessor.accessorKey,
        cell: columnDef.cell,
        enableFiltering: columnDef.enableColumnFilter,
        enableHiding: columnDef.enableHiding,
        enableResizing: columnDef.enableResizing,
        enableSorting: columnDef.enableSorting,
        header: headerText,
        id,
        meta: columnDef.meta,
        type: "text",
      } as DataTableColumnDef<TData>;
    };

    // Convert columns to DataTableColumnDef format
    const processedColumns = externalColumns.map(processColumn);

    // Create ID mappings
    const idMappings: Record<string, string> = {};
    const translations: Record<string, string> = {};

    for (const col of processedColumns) {
      // Preserve original column ID when possible
      const id = col.id || getColumnId(col, 0);
      idMappings[col.id] = id;
      translations[id] = col.header;
    }

    // Update atoms
    setColumns(
      processedColumns as DataTableColumnDef<Record<string, unknown>>[]
    );
    // Note: We can't update columnIdMapping directly as it's a derived atom in filter-atoms.ts
    // The mapping will be updated automatically when filters change
    setColumnTranslations((prev) => ({ ...prev, ...translations }));

    // Set initialization flag to prevent future executions
    initialized.current = true;
    // Reset processing flag
    processingColumns.current = false;
    return processedColumns;
  }, [externalColumns, getColumnId, setColumnTranslations, setColumns]);

  // Stabilize the external columns reference to prevent unnecessary query reruns
  const columnsLength = externalColumns?.length || 0;

  // Use a stable reference for the query key that only depends on tableId and columns length
  const queryKey = useMemo(
    () => ["table-columns", tableId, columnsLength],
    [tableId, columnsLength]
  );

  // Execute the query with stable references to prevent unnecessary re-renders
  // Properties ordered alphabetically to satisfy ESLint
  // The query will only run once when the component mounts and the conditions are met
  useQuery({
    enabled:
      !!columnsLength && !initialized.current && !processingColumns.current,
    gcTime: Number.POSITIVE_INFINITY, // Never garbage collect
    queryFn: processColumnsFn,
    queryKey,
    staleTime: Number.POSITIVE_INFINITY, // Never refetch automatically
  });

  // Extract column IDs
  const columnIds = useMemo(() => {
    return columns.map((col, idx) => getColumnId(col, idx));
  }, [columns, getColumnId]);

  // Initialize column order if not set
  const initialColumnOrder = useMemo(() => {
    return columnOrder.length > 0 ? columnOrder : columnIds;
  }, [columnIds, columnOrder]);

  // Get visible and hidden columns
  const { hiddenColumns, visibleColumns } = useMemo(() => {
    const visible = columns.filter((col) => {
      const id = getColumnId(col);
      return columnVisibility[id] !== false;
    });

    const hidden = columns.filter((col) => {
      const id = getColumnId(col);
      return columnVisibility[id] === false;
    });

    return { hiddenColumns: hidden, visibleColumns: visible };
  }, [columns, columnVisibility, getColumnId]);

  // Column visibility actions
  const toggleColumnVisibility = useCallback(
    (columnId: string) => {
      const newVisibility = {
        ...columnVisibility,
        [columnId]: !columnVisibility[columnId],
      };
      setVisibilityFromUI(newVisibility);
    },
    [columnVisibility, setVisibilityFromUI]
  );

  const resetColumnVisibility = useCallback(() => {
    setVisibilityFromUI({});
  }, [setVisibilityFromUI]);

  const hideAllColumns = useCallback(() => {
    const newVisibility: Record<string, boolean> = {};
    for (const id of columnIds) {
      newVisibility[id] = false;
    }
    setVisibilityFromUI(newVisibility);
  }, [columnIds, setVisibilityFromUI]);

  const showAllColumns = useCallback(() => {
    const newVisibility: Record<string, boolean> = {};
    for (const id of columnIds) {
      newVisibility[id] = true;
    }
    setVisibilityFromUI(newVisibility);
  }, [columnIds, setVisibilityFromUI]);

  // Column order actions
  const resetColumnOrder = useCallback(() => {
    setOrderFromUI(columnIds);
  }, [columnIds, setOrderFromUI]);

  const moveColumn = useCallback(
    (fromIndex: number, toIndex: number) => {
      const newOrder = [...columnOrder];
      const item = newOrder.splice(fromIndex, 1)[0];
      newOrder.splice(toIndex, 0, item);
      setOrderFromUI(newOrder);
    },
    [columnOrder, setOrderFromUI]
  );

  // Convert to TanStack Table column definitions
  const tanStackColumns = useMemo<ColumnDef<TData>[]>(() => {
    return columns.map((col) => {
      // Create a properly typed column definition
      const columnDef: ColumnDef<TData> = {
        accessorFn: col.accessorFn as AccessorFn<TData, unknown>,
        accessorKey: col.accessorKey as keyof TData,
        cell: col.cell as ColumnDef<TData>["cell"],
        enableColumnFilter:
          col.enableFiltering !== undefined ? col.enableFiltering : true,
        enableHiding: col.enableHiding,
        enableResizing: col.enableResizing,
        enableSorting: col.enableSorting,
        header: columnTranslations[col.id] || col.header,
        id: col.id,
        meta: col.meta as ColumnMeta<TData, unknown>,
      };

      return columnDef;
    });
  }, [columns, columnTranslations]);

  // Get column name by ID
  const getColumnName = useCallback(
    (columnId: string) => {
      const cleanedId = columnId.includes("__TURBOPACK__")
        ? cleanColumnId(columnId)
        : columnId;

      // Try translations
      if (columnTranslations[cleanedId]) {
        return columnTranslations[cleanedId];
      }

      // Try ID mapping
      const mappedId = columnIdMapping.get(columnId);
      if (mappedId && columnTranslations[mappedId]) {
        return columnTranslations[mappedId];
      }

      // Try case-insensitive match
      const similarKey = Object.keys(columnTranslations).find(
        (key) => key.toLowerCase() === cleanedId.toLowerCase()
      );

      if (similarKey) {
        return columnTranslations[similarKey];
      }

      // Fallback to formatted ID
      return (
        cleanedId.charAt(0).toUpperCase() +
        cleanedId
          .slice(1)
          .replace(/([A-Z])/g, " $1")
          .trim()
      );
    },
    [columnTranslations, columnIdMapping]
  );

  return {
    cleanColumnId,
    columnIds,
    columnOrder: columnOrder.length ? columnOrder : initialColumnOrder,
    columns,
    columnTranslations,
    columnVisibility,
    getColumnId,
    getColumnName,
    hiddenColumns,
    hideAllColumns,
    moveColumn,
    resetColumnOrder,
    resetColumnVisibility,
    setOrderFromUI,
    setVisibilityFromUI,
    showAllColumns,
    tanStackColumns,
    toggleColumnVisibility,
    visibleColumns,
  };
}

/**
 * Hook for handling column drag and drop functionality
 * Uses dnd-kit for drag and drop operations
 * Uses URL state as source of truth for column order (shareable URLs)
 */
"use client";

import {
  closestCenter,
  DndContext,
  type DragEndEvent,
  type DragStartEvent,
  KeyboardSensor,
  MouseSensor,
  TouchSensor,
  useSensor,
  useSensors,
} from "@dnd-kit/core";
import { restrictToHorizontalAxis } from "@dnd-kit/modifiers";
import {
  horizontalListSortingStrategy,
  SortableContext,
  sortableKeyboardCoordinates,
} from "@dnd-kit/sortable";
import { useAtom } from "jotai";
import { useCallback, useEffect } from "react";

import {
  activeColumnDragAtom,
  columnDragEnabledAtom,
} from "../../../atoms/table-atoms";
import { useTableUrlState } from "../../../hooks/use-table-url-state";

// Utility function to move array items
function arrayMove<T>(array: T[], from: number, to: number): T[] {
  const newArray = [...array];
  const [removed] = newArray.splice(from, 1);
  newArray.splice(to, 0, removed);
  return newArray;
}

/**
 * Hook for managing column drag and drop
 * @param tableId - ID of the table
 * @param onColumnOrderChange - Optional callback for when column order changes
 * @param enableByDefault - Whether to enable drag & drop by default (from configuration)
 * @returns Object with column drag and drop utilities
 */
export function useColumnDnd(
  tableId: string,
  onColumnOrderChange?: (newOrder: string[]) => void,
  enableByDefault?: boolean
) {
  // **URL STATE** - source of truth for column order (shareable)
  const { orderParam, setOrderFromUI } = useTableUrlState({ tableId });

  // Helper function to enforce fixed positions
  const enforceFixedPositions = useCallback((order: string[]): string[] => {
    const selectCol = order.find((id) => id === "select");
    const actionsCol = order.find((id) => id === "actions");
    const otherCols = order.filter((id) => id !== "select" && id !== "actions");

    const finalOrder: string[] = [];
    if (selectCol) {
      finalOrder.push(selectCol);
    }
    finalOrder.push(...otherCols);
    if (actionsCol) {
      finalOrder.push(actionsCol);
    }

    return finalOrder;
  }, []);

  // **ATOMS** - only for temporary UI state (not shareable)
  const [activeDragId, setActiveDragId] = useAtom(
    activeColumnDragAtom(tableId)
  );
  const [isDragEnabled, setIsDragEnabled] = useAtom(
    columnDragEnabledAtom(tableId)
  );

  // Initialize drag enabled state based on configuration
  useEffect(() => {
    if (enableByDefault !== undefined) {
      // Check if this is the first time or if localStorage doesn't have a value
      const storageKey = `${tableId}-column-drag-enabled`;
      const currentValue = localStorage.getItem(storageKey);

      if (currentValue === null) {
        // First time - use the configuration value
        setIsDragEnabled(enableByDefault);
      } else if (enableByDefault && currentValue === "false") {
        // Configuration says true but localStorage has false - prefer configuration for new setup
        setIsDragEnabled(enableByDefault);
      }
    }
  }, [tableId, enableByDefault, setIsDragEnabled]);

  // Get current column order from URL state
  const columnOrder = (orderParam as string[]) || [];

  // Configure sensors for drag and drop
  const mouseSensor = useSensor(MouseSensor, {
    activationConstraint: { distance: 8 }, // Require a minimum drag distance
  });

  const touchSensor = useSensor(TouchSensor, {
    activationConstraint: { delay: 250, tolerance: 5 }, // Add a small delay for touch
  });

  const keyboardSensor = useSensor(KeyboardSensor, {
    coordinateGetter: sortableKeyboardCoordinates,
  });

  const sensors = useSensors(mouseSensor, touchSensor, keyboardSensor);

  // Handle drag start event
  const handleDragStart = useCallback(
    (event: DragStartEvent) => {
      const { active } = event;
      if (active) {
        setActiveDragId(active.id.toString());
      }
    },
    [setActiveDragId]
  );

  // Helper function to check if a column ID is fixed (non-draggable)
  const isFixedColumn = useCallback((columnId: string): boolean => {
    return columnId === "select" || columnId === "actions";
  }, []);

  // Helper function to validate drag operation
  const validateDragOperation = useCallback(
    (activeId: string, overId: string): boolean => {
      return !(isFixedColumn(activeId) || isFixedColumn(overId));
    },
    [isFixedColumn]
  );

  // Helper function to get column order from DOM
  const getColumnOrderFromDOM = useCallback((): string[] | null => {
    const headerElements = document.querySelectorAll("[data-column-id]");
    const idsFromDOM = Array.from(headerElements).map((el) =>
      el.getAttribute("data-column-id")
    );

    if (idsFromDOM.length > 0) {
      return idsFromDOM.filter(Boolean) as string[];
    }
    return null;
  }, []);

  // Helper function to process column reorder
  const processColumnReorder = useCallback(
    (newOrder: string[]) => {
      // Ensure fixed positions: select first, actions last
      const finalOrder = enforceFixedPositions(newOrder);

      // Update URL state
      setOrderFromUI(finalOrder);

      // Call the callback if provided
      if (onColumnOrderChange) {
        onColumnOrderChange(finalOrder);
      }
    },
    [enforceFixedPositions, setOrderFromUI, onColumnOrderChange]
  );

  // Helper function to handle the actual drag operation
  const handleValidDragOperation = useCallback(
    (activeId: string, overId: string) => {
      // Process the drag and drop event
      // If column order is empty, we need to get the columns from the DOM
      if (columnOrder.length === 0) {
        const newOrderFromDOM = getColumnOrderFromDOM();
        if (newOrderFromDOM) {
          processColumnReorder(newOrderFromDOM);
          return;
        }
      }

      // Get the current column order
      const oldIndex = columnOrder.indexOf(activeId);
      const newIndex = columnOrder.indexOf(overId);

      if (oldIndex !== -1 && newIndex !== -1) {
        // Calculate the new order by moving the item
        const newOrder = arrayMove(columnOrder, oldIndex, newIndex);
        processColumnReorder(newOrder);
      }
    },
    [columnOrder, getColumnOrderFromDOM, processColumnReorder]
  );

  // Handle drag end event
  const handleDragEnd = useCallback(
    (event: DragEndEvent) => {
      const { active, over } = event;

      // Only update if we have a valid over target and it's different from the active item
      if (over && active.id !== over.id) {
        // Don't allow dragging fixed columns (select, actions)
        const activeId = active.id.toString();
        const overId = over.id.toString();

        if (validateDragOperation(activeId, overId)) {
          handleValidDragOperation(activeId, overId);
        }
      }

      // Reset active drag ID
      setActiveDragId(null);
    },
    [setActiveDragId, validateDragOperation, handleValidDragOperation]
  );

  // Toggle drag enabled
  const toggleDragEnabled = useCallback(() => {
    setIsDragEnabled((prev) => !prev);
  }, [setIsDragEnabled]);

  return {
    // State
    activeDragId,
    // DnD Kit utilities
    closestCenter,
    columnOrder,

    DndContext,
    // Event handlers
    handleDragEnd,
    handleDragStart,
    horizontalListSortingStrategy,
    isDragEnabled,
    // Modifiers
    modifiers: [restrictToHorizontalAxis],
    restrictToHorizontalAxis,

    sensors,
    SortableContext,

    // Actions
    toggleDragEnabled,
  };
}

"use client";

import type { DragEndEvent, DragStartEvent } from "@dnd-kit/core";
import type { Table } from "@tanstack/react-table";
import { useCallback, useState } from "react";

interface UseColumnDragOverlayProps<TData> {
  /**
   * Original drag end handler from useColumnDnd
   */
  onDragEnd?: (event: DragEndEvent) => void;

  /**
   * Original drag start handler from useColumnDnd
   */
  onDragStart?: (event: DragStartEvent) => void;

  /**
   * Table instance from TanStack Table
   */
  table: Table<TData>;
}

interface UseColumnDragOverlayReturn {
  /**
   * Active column information (id and title)
   */
  activeColumn: null | { id: string; title: string };

  /**
   * Enhanced drag end handler that clears the active column
   */
  handleDragEnd: (event: DragEndEvent) => void;

  /**
   * Enhanced drag start handler that tracks the active column
   */
  handleDragStart: (event: DragStartEvent) => void;
}

/**
 * Hook for managing column drag overlay state and handlers
 * Enhances the existing drag handlers to track the active column
 */
export function useColumnDragOverlay<TData>({
  onDragEnd,
  onDragStart,
  table,
}: UseColumnDragOverlayProps<TData>): UseColumnDragOverlayReturn {
  // State to track the active column being dragged
  const [activeColumn, setActiveColumn] = useState<null | {
    id: string;
    title: string;
  }>(null);

  // Enhanced drag start handler
  const handleDragStart = useCallback(
    (event: DragStartEvent) => {
      // Call the original handler if provided
      if (onDragStart) {
        onDragStart(event);
      }

      // Get column information for the overlay
      const { active } = event;
      const columnId = active.id.toString();
      const column = table.getAllColumns().find((col) => col.id === columnId);

      if (column) {
        // Get the column title, fallback to ID if not available
        const columnTitle =
          typeof column.columnDef.header === "string"
            ? column.columnDef.header
            : columnId;

        // Update active column state
        setActiveColumn({ id: columnId, title: columnTitle });
      }
    },
    [onDragStart, table]
  );

  // Enhanced drag end handler
  const handleDragEnd = useCallback(
    (event: DragEndEvent) => {
      // Call the original handler if provided
      if (onDragEnd) {
        onDragEnd(event);
      }

      // Clear the active column state
      setActiveColumn(null);
    },
    [onDragEnd]
  );

  return {
    activeColumn,
    handleDragEnd,
    handleDragStart,
  };
}

/**
 * Hook for creating and managing column definitions
 * Provides a standardized way to define columns for any data type
 */
"use client";

import type { ColumnDef } from "@tanstack/react-table";
import { useAtomValue } from "jotai";
import { useMemo } from "react";
import { tableConfigFamilyAtom } from "../../../atoms/config-atoms";
import type { DataTableColumnDef } from "../../../types/column-types";
import {
  createActionsColumn,
  createBooleanColumn,
  createCodeColumn,
  createDateColumn,
  createJsonColumn,
  createSelectionColumn,
  createTagColumn,
  createTextColumn,
} from "..";
import { createDynamicTypeColumn } from "../dynamic-type-column";
import { createNumberColumn } from "../number-column";
import { createStringColumn } from "../string-column";

export interface UseColumnsOptions<
  _TData extends Record<string, unknown> = Record<string, unknown>,
> {
  /**
   * Whether to include a selection column
   * If not specified, uses the enableRowSelection value from the table config
   */
  enableSelection?: boolean;

  /**
   * Table identifier - used to scope configurations
   */
  tableId: string;
}

/**
 * Hook for creating and managing column definitions
 * @param options - Configuration options
 * @returns Object with column creation utilities
 */
export function useColumns<
  TData extends Record<string, unknown> = Record<string, unknown>,
>({ enableSelection, tableId }: UseColumnsOptions<TData>) {
  // Get table configuration
  const tableConfig = useAtomValue(tableConfigFamilyAtom(tableId));

  // Determine if selection is enabled
  const isSelectionEnabled = useMemo(() => {
    return enableSelection !== undefined
      ? enableSelection
      : tableConfig.enableRowSelection;
  }, [enableSelection, tableConfig.enableRowSelection]);

  // Create a selection column if enabled
  const selectionColumn = useMemo(() => {
    if (!isSelectionEnabled) {
      return null;
    }
    return createSelectionColumn<TData>();
  }, [isSelectionEnabled]);

  // Create a tag column with the given options
  const createTag = useMemo(() => {
    return <K extends keyof TData>(
      accessorKey: K,
      options?: Omit<
        Parameters<typeof createTagColumn<TData>>[0],
        "header" | "id"
      > & {
        header?: string;
      }
    ) => {
      return createTagColumn<TData>({
        header: options?.header || String(accessorKey),
        id: accessorKey as string,
        ...options,
      });
    };
  }, []);

  // Create a text column with the given options
  const createText = useMemo(() => {
    return <K extends keyof TData>(
      accessorKey: K,
      options?: Omit<
        Parameters<typeof createTextColumn<TData>>[0],
        "accessorKey"
      >
    ) => {
      return createTextColumn<TData>({
        accessorKey: accessorKey as string,
        ...options,
      });
    };
  }, []);

  // Create a boolean column with the given options
  const createBoolean = useMemo(() => {
    return <K extends keyof TData>(
      accessorKey: K,
      options?: Omit<
        Parameters<typeof createBooleanColumn<TData>>[0],
        "accessorKey"
      >
    ) => {
      return createBooleanColumn<TData>({
        accessorKey: accessorKey as string,
        ...options,
      });
    };
  }, []);

  // Create a code column with the given options
  const createCode = useMemo(() => {
    return <K extends keyof TData>(
      accessorKey: K,
      options?: Omit<
        Parameters<typeof createCodeColumn<TData>>[0],
        "header" | "id"
      > & {
        header?: string;
      }
    ) => {
      return createCodeColumn<TData>({
        header: options?.header || String(accessorKey),
        id: accessorKey as string,
        ...options,
      });
    };
  }, []);

  // Create a date column with the given options
  const createDate = useMemo(() => {
    return <K extends keyof TData>(
      accessorKey: K,
      options?: Omit<
        Parameters<typeof createDateColumn<TData>>[0],
        "accessorKey"
      >
    ) => {
      return createDateColumn<TData>({
        accessorKey: accessorKey as string,
        ...options,
      });
    };
  }, []);

  // Create a JSON column with the given options
  const createJson = useMemo(() => {
    return <K extends keyof TData>(
      accessorKey: K,
      options?: Omit<
        Parameters<typeof createJsonColumn<TData>>[0],
        "accessorKey"
      >
    ) => {
      return createJsonColumn<TData>({
        accessorKey: accessorKey as string,
        ...options,
      });
    };
  }, []);

  // Create an actions column with the given options
  const createActions = useMemo(() => {
    return (
      options: Omit<Parameters<typeof createActionsColumn<TData>>[0], "tableId">
    ) => {
      // Automatically pass the tableId from the hook parameters
      return createActionsColumn<TData>({
        ...options,
        tableId, // Pass the tableId from the hook parameters
      });
    };
  }, [tableId]);

  // Create a dynamic type column with the given options
  const createDynamicType = useMemo(() => {
    return <V extends keyof TData, T extends keyof TData>(
      valueKey: V,
      typeKey: T,
      options?: Omit<
        Parameters<typeof createDynamicTypeColumn<TData>>[0],
        "typeKey" | "valueKey"
      >
    ) => {
      return createDynamicTypeColumn<TData>({
        typeKey: typeKey as string,
        valueKey: valueKey as string,
        ...options,
      });
    };
  }, []);

  // Create a number column with the given options
  const createNumber = useMemo(() => {
    return <K extends keyof TData>(
      accessorKey: K,
      options?: Omit<
        Parameters<typeof createNumberColumn<TData>>[0],
        "accessorKey"
      >
    ) => {
      return createNumberColumn<TData>({
        accessorKey: accessorKey as string,
        ...options,
      });
    };
  }, []);

  // Create a string column with the given options
  const createString = useMemo(() => {
    return <K extends keyof TData>(
      accessorKey: K,
      options?: Omit<
        Parameters<typeof createStringColumn<TData>>[0],
        "accessorKey"
      >
    ) => {
      return createStringColumn<TData>({
        accessorKey: accessorKey as string,
        ...options,
      });
    };
  }, []);

  // Create a selection column
  const createSelection = useMemo(() => {
    return () => createSelectionColumn<TData>();
  }, []);

  // Combine columns into a final array
  const createColumnHelper = useMemo(() => {
    return {
      actions: createActions,
      boolean: createBoolean,
      code: createCode,
      date: createDate,
      dynamicType: createDynamicType,
      json: createJson,
      number: createNumber,
      selection: createSelection,
      string: createString,
      tag: createTag,
      text: createText,
    };
  }, [
    createActions,
    createBoolean,
    createCode,
    createDate,
    createDynamicType,
    createJson,
    createNumber,
    createSelection,
    createString,
    createTag,
    createText,
  ]);

  // Function to combine columns with the selection column if enabled
  const createColumns = useMemo(() => {
    return (columns: Array<ColumnDef<TData> | DataTableColumnDef<TData>>) => {
      // Check if selection column already exists in input columns
      const hasSelectionColumn = columns.some((col) => {
        const colWithId = col as ColumnDef<TData> & { id?: string };
        const colWithMeta = col as DataTableColumnDef<TData> & {
          meta?: { isSelectionColumn?: boolean };
        };
        return colWithId.id === "select" || colWithMeta.meta?.isSelectionColumn;
      });

      if (selectionColumn && !hasSelectionColumn) {
        return [selectionColumn, ...columns];
      }

      return columns;
    };
  }, [selectionColumn]);

  return {
    column: createColumnHelper,
    createColumns,
    selectionColumn,
  };
}

