/**
 * JSON column component for data tables
 * Provides standardized display of JSON/array values
 */
"use client";

import type { CellContext, ColumnDef } from "@tanstack/react-table";
import { Braces, type LucideIcon } from "lucide-react";

import { JsonCell } from "../cells/json-cell";

/**
 * Custom properties for our column definitions
 */
interface CustomColumnProps {
  icon?: LucideIcon;
  type?: string;
}

/**
 * Combined type for our column definition
 */
type ExtendedColumnDef<TData> = ColumnDef<TData> & CustomColumnProps;

interface JsonColumnProps {
  /**
   * Key to access the JSON value from the row data
   */
  accessorKey: string;

  /**
   * Optional CSS class name for the cell
   */
  className?: string;

  /**
   * Whether the column can be hidden
   * @default true
   */
  enableHiding?: boolean;

  /**
   * Whether the column can be sorted
   * @default true
   */
  enableSorting?: boolean;

  /**
   * Optional custom header text
   */
  header?: string;

  /**
   * Maximum number of items to display before truncating
   * @default 3
   */
  maxItems?: number;
}

/**
 * Creates a JSON column definition
 * @returns Column definition for displaying JSON or array values
 */
export function createJsonColumn<TData>({
  accessorKey,
  className,
  enableHiding = true,
  enableSorting = true,
  header,
  maxItems = 3,
}: JsonColumnProps): ExtendedColumnDef<TData> {
  return {
    accessorKey,
    cell: (info: CellContext<TData, unknown>) => {
      const value = info.getValue();
      return (
        <JsonCell className={className} maxItems={maxItems} value={value} />
      );
    },
    enableHiding,
    enableSorting,
    header: header || accessorKey,
    icon: Braces,
    id: accessorKey,
    type: "json",
  };
}

/**
 * Number column component for data tables
 * Provides standardized display of numeric values
 */
"use client";

import type { CellContext, ColumnDef } from "@tanstack/react-table";
import { Hash, type LucideIcon } from "lucide-react";
import { Button } from "@/components/ui/button";
import { NumberCell } from "../cells/number-cell";

/**
 * Custom properties for our column definitions
 */
interface CustomColumnProps {
  icon?: LucideIcon;
  type?: string;
}

/**
 * Combined type for our column definition
 */
type ExtendedColumnDef<TData> = ColumnDef<TData> & CustomColumnProps;

interface NumberColumnProps {
  /**
   * Key to access the numeric value from the row data
   */
  accessorKey: string;

  /**
   * Optional CSS class name for the cell
   */
  className?: string;

  /**
   * Whether the column can be filtered
   * @default true
   */
  enableColumnFilter?: boolean;

  /**
   * Whether the column can be hidden
   * @default true
   */
  enableHiding?: boolean;

  /**
   * Whether the column can be sorted
   * @default true
   */
  enableSorting?: boolean;

  /**
   * Optional formatter function to format the number
   */
  formatter?: (value: number) => string;

  /**
   * Optional custom header text
   */
  header?: string;
}

/**
 * Creates a number column definition
 * @returns Column definition for displaying numeric values
 */
export function createNumberColumn<TData>({
  accessorKey,
  className,
  enableColumnFilter = true,
  enableHiding = true,
  enableSorting = true,
  formatter,
  header,
}: NumberColumnProps): ExtendedColumnDef<TData> {
  return {
    accessorKey,
    enableGrouping: true,
    // Enable aggregation for grouped rows
    aggregationFn: "sum",
    cell: (info: CellContext<TData, unknown>) => {
      // Group header: toggle + label + count
      if (info.cell.getIsGrouped?.()) {
        const toggle = info.row.getToggleExpandedHandler();
        const expanded = info.row.getIsExpanded();
        const count = info.row.subRows?.length ?? 0;
        const label = String(info.getValue() ?? "");
        return (
          <div className="flex items-center gap-2">
            <Button
              aria-expanded={expanded}
              aria-label={expanded ? "Collapse group" : "Expand group"}
              className="h-6 w-6 p-0 text-muted-foreground hover:text-foreground"
              onClick={(e) => {
                e.stopPropagation();
                toggle();
              }}
              size="icon"
              type="button"
              variant="ghost"
            >
              <span aria-hidden>{expanded ? "▾" : "▸"}</span>
            </Button>
            <span className="font-medium">{label}</span>
            <span className="rounded-full bg-muted px-2 py-0.5 text-muted-foreground text-xs">
              {count}
            </span>
          </div>
        );
      }
      // Aggregated cells: keep minimal. For placeholder cells (leaf rows under a grouped column),
      // render the actual numeric value to avoid shifted columns in subgroups.
      if (info.cell.getIsAggregated?.()) {
        return <span className="text-muted-foreground"> </span>;
      }
      const value = info.getValue();
      const numValue = value as number | string;
      return (
        <NumberCell
          className={className}
          formatter={formatter}
          value={numValue}
        />
      );
    },
    // Render subtotal values on grouped rows
    aggregatedCell: ({ getValue }) => {
      const sum = Number(getValue() as number);
      let formatted = "—";
      if (Number.isFinite(sum)) {
        formatted =
          typeof formatter === "function"
            ? formatter(sum)
            : sum.toLocaleString();
      }
      return <span className="font-medium">{formatted}</span>;
    },
    enableColumnFilter,
    enableHiding,
    enableSorting,
    header: header || accessorKey,
    icon: Hash,
    id: accessorKey,
    type: "number",
  };
}

/**
 * Selection column component for data tables
 * Provides checkbox for row selection with proper accessibility
 */
"use client";

import type { ColumnDef, Row, Table } from "@tanstack/react-table";
import { useState } from "react";
import { Checkbox } from "@/components/ui/checkbox";
import { SelectionCell } from "../cells/selection-cell";

/**
 * Options for selection column
 */
export interface SelectionColumnOptions {
  /**
   * Custom CSS class name for the column
   */
  className?: string;

  /**
   * Whether the column can be hidden
   */
  enableHiding?: boolean;
}

/**
 * Props for the selection header component
 */
interface SelectionHeaderProps<TData> {
  /**
   * Optional CSS class name
   */
  className?: string;

  /**
   * The table instance from TanStack Table
   */
  table: Table<TData>;
}

// Selection header component with proper UI refresh
function SelectionHeaderBase<TData>({ table }: SelectionHeaderProps<TData>) {
  // Force re-render when selection changes - this is the key fix!
  const [, forceUpdate] = useState({});

  if (!table) {
    return <div className="flex h-4 w-4 items-center justify-center" />;
  }

  const rowSelection = table.getState().rowSelection;
  const allRows = table.getRowModel().rows;
  const coreRows = table.getCoreRowModel().rows;
  const selectedCount = coreRows.filter((row) => rowSelection[row.id]).length;
  // With grouping, allRows can be group rows only; count visible leaf rows by recursing
  const visibleLeafIds = allRows.flatMap((row) => getLeafRowIds(row));
  const totalCount = visibleLeafIds.length;

  const isAllSelected = selectedCount === totalCount && totalCount > 0;
  const isSomeSelected =
    selectedCount > 0 && (totalCount === 0 || selectedCount < totalCount);

  const handleToggle = (value: boolean) => {
    if (value) {
      const newSelection: Record<string, boolean> = {
        ...rowSelection,
        ...Object.fromEntries(visibleLeafIds.map((id) => [id, true])),
      };
      table.setRowSelection(newSelection);
    } else {
      table.setRowSelection({});
    }

    // Critical: Force re-render after state change
    forceUpdate({});
  };

  return (
    <div className="flex items-center justify-center">
      <Checkbox
        aria-label="Select all rows"
        checked={isAllSelected}
        className="translate-y-[2px] cursor-pointer data-[state=checked]:bg-primary data-[state=checked]:text-primary-foreground"
        onCheckedChange={handleToggle}
        ref={(el: HTMLButtonElement & { indeterminate?: boolean }) => {
          if (el) {
            el.indeterminate = isSomeSelected;
          }
        }}
      />
    </div>
  );
}

/** Collect all leaf row IDs under a row (for group rows, recurse into subRows) */
function getLeafRowIds<TData>(row: Row<TData>): string[] {
  if (!row.getIsGrouped?.()) {
    return [row.id];
  }
  const sub = (row.subRows ?? []) as Row<TData>[];
  return sub.flatMap((r) => getLeafRowIds(r));
}

/** Group row selection control: checkbox to select/deselect whole group (exported for use in custom table body) */
export function GroupRowSelectionCell<TData>({
  row,
  table,
}: {
  row: Row<TData>;
  table: Table<TData>;
}) {
  const leafIds = getLeafRowIds(row);
  const rowSelection = table.getState().rowSelection || {};
  const selectedInGroup = leafIds.filter((id) => rowSelection[id]).length;
  const allSelected = selectedInGroup === leafIds.length && leafIds.length > 0;
  const someSelected = selectedInGroup > 0;

  const handleGroupToggle = (value: boolean) => {
    const leafSet = new Set(leafIds);
    const next: Record<string, boolean> = value
      ? {
          ...rowSelection,
          ...Object.fromEntries(leafIds.map((id) => [id, true])),
        }
      : Object.fromEntries(
          Object.entries(rowSelection).filter(([id]) => !leafSet.has(id))
        );
    table.setRowSelection(next);
  };

  return (
    <div className="flex items-center justify-center">
      <Checkbox
        aria-label="Select group"
        checked={allSelected}
        className="translate-y-[2px] cursor-pointer data-[state=checked]:bg-primary data-[state=checked]:text-primary-foreground"
        onCheckedChange={handleGroupToggle}
        ref={(el: HTMLButtonElement & { indeterminate?: boolean }) => {
          if (el) {
            el.indeterminate = someSelected && !allSelected;
          }
        }}
      />
    </div>
  );
}

/**
 * Creates a selection column definition
 * @param options - Options for customizing the selection column
 * @returns Column definition for row selection with checkboxes
 */
export function createSelectionColumn<TData>(
  options: SelectionColumnOptions = {}
): ColumnDef<TData, unknown> {
  const { className = "", enableHiding = false } = options;

  return {
    accessorKey: "select",
    enableGrouping: true,
    // Custom grouping value: selected vs unselected
    getGroupingValue: (_row: TData) => {
      // This will be handled dynamically by the table
      return "unselected"; // Default fallback
    },
    cell: (info) => {
      const isGrouped = info.cell.getIsGrouped?.() ?? false;

      if (isGrouped) {
        return <GroupRowSelectionCell row={info.row} table={info.table} />;
      }

      return <SelectionCell className={className} row={info.row} />;
    },
    enableHiding,
    enablePinning: false,
    enableSorting: false,
    header: ({ table }: { table: Table<TData> }) => (
      <SelectionHeaderBase className={className} table={table} />
    ),
    id: "select",
    meta: {
      disableDrag: true,
      disableDrop: true,
      fixedPosition: "start",
      isSelectionColumn: true,
    },
  };
}

/**
 * String column component for data tables
 * Provides standardized display of string values
 */
"use client";

import type { CellContext, ColumnDef } from "@tanstack/react-table";
import { Asterisk, type LucideIcon } from "lucide-react";
import { Button } from "@/components/ui/button";
import { StringCell } from "../cells/string-cell";

/**
 * Custom properties for our column definitions
 */
interface CustomColumnProps {
  icon?: LucideIcon;
  type?: string;
}

/**
 * Combined type for our column definition
 */
type ExtendedColumnDef<TData> = ColumnDef<TData> & CustomColumnProps;

interface StringColumnProps {
  /**
   * Key to access the string value from the row data
   */
  accessorKey: string;

  /**
   * Optional CSS class name for the cell
   */
  className?: string;

  /**
   * Whether the column can be hidden
   * @default true
   */
  enableHiding?: boolean;

  /**
   * Whether the column can be sorted
   * @default true
   */
  enableSorting?: boolean;

  /**
   * Optional custom header text
   */
  header?: string;

  /**
   * Whether to show quotes around the string
   * @default false
   */
  showQuotes?: boolean;
}

/**
 * Creates a string column definition
 * @returns Column definition for displaying string values
 */
export function createStringColumn<TData>({
  accessorKey,
  className,
  enableHiding = true,
  enableSorting = true,
  header,
  showQuotes = false,
}: StringColumnProps): ExtendedColumnDef<TData> {
  return {
    accessorKey,
    enableGrouping: true,
    cell: (info: CellContext<TData, unknown>) => {
      // Debug removed to stop spam

      // Fast path: grouped header with toggle
      if (info.cell.getIsGrouped?.()) {
        const toggle = info.row.getToggleExpandedHandler();
        const expanded = info.row.getIsExpanded();
        const count = info.row.subRows?.length ?? 0;
        const label = String(info.getValue() ?? "");
        return (
          <Button
            className="flex w-full cursor-pointer items-center gap-2 border-0 bg-transparent p-0 text-left"
            onClick={(e) => {
              e.stopPropagation();
              const _result = toggle();
            }}
            type="button"
            variant="ghost"
          >
            <span aria-hidden className="text-muted-foreground">
              {expanded ? "▾" : "▸"}
            </span>
            <span className="font-medium">{label}</span>
            <span className="rounded-full bg-muted px-2 py-0.5 text-muted-foreground text-xs">
              {count}
            </span>
          </Button>
        );
      }

      // Minimal output for aggregate cells. For placeholder cells (grouped column on leaf rows),
      // render the actual value so grouped layouts keep their visible data and alignment.
      if (info.cell.getIsAggregated?.()) {
        return <span className="text-muted-foreground"> </span>;
      }

      const value = info.getValue();
      return (
        <StringCell
          className={className}
          showQuotes={showQuotes}
          value={value}
        />
      );
    },
    enableHiding,
    enableSorting,
    header: header || accessorKey,
    icon: Asterisk,
    id: accessorKey,
    type: "string",
  };
}

/**
 * Tag column component for data tables
 * Displays tag values with colored backgrounds
 */
"use client";

import type { ColumnDef } from "@tanstack/react-table";
import { type LucideIcon, Tag } from "lucide-react";
import { Button } from "@/components/ui/button";
import { TagCell } from "../cells/tag-cell";

/**
 * Options for creating a tag column
 */
export interface TagColumnOptions {
  /**
   * Optional CSS class name
   */
  className?: string;

  /**
   * Whether the column can be filtered
   * @default true
   */
  enableColumnFilter?: boolean;

  /**
   * Whether the column can be hidden
   * @default true
   */
  enableHiding?: boolean;

  /**
   * Whether the column can be sorted
   * @default true
   */
  enableSorting?: boolean;

  /**
   * Header text for the column
   */
  header: string;

  /**
   * Unique identifier for the column
   */
  id: string;

  /**
   * Optional map of tag value → Tailwind color class (e.g. "bg-red-500/80 text-white dark:bg-red-600/90").
   * When provided, matching values use this class; others use the deterministic hash.
   */
  tagColorMap?: Record<string, string>;
}

/**
 * Custom properties for our column definitions
 */
interface CustomColumnProps {
  icon?: LucideIcon;
  type?: string;
}

/**
 * Combined type for our column definition
 */
type ExtendedColumnDef<TData> = ColumnDef<TData> & CustomColumnProps;

/**
 * Creates a column definition for displaying tag values with colored backgrounds
 */
export function createTagColumn<TData>({
  className = "",
  enableColumnFilter = true,
  enableHiding = true,
  enableSorting = true,
  header,
  id,
  tagColorMap,
}: TagColumnOptions): ExtendedColumnDef<TData> {
  return {
    accessorFn: (row: TData) => (row as Record<string, unknown>)[id],
    enableGrouping: true,
    cell: (info) => {
      // Group header: toggle + label (pill) + count
      if (info.cell.getIsGrouped?.()) {
        const toggle = info.row.getToggleExpandedHandler();
        const expanded = info.row.getIsExpanded();
        const count = info.row.subRows?.length ?? 0;
        const label = String(info.getValue() ?? "");
        return (
          <div className="flex items-center gap-2">
            <Button
              aria-expanded={expanded}
              aria-label={expanded ? "Collapse group" : "Expand group"}
              className="h-6 w-6 p-0 text-muted-foreground hover:text-foreground"
              onClick={(e) => {
                e.stopPropagation();
                toggle();
              }}
              size="icon"
              type="button"
              variant="ghost"
            >
              <span aria-hidden>{expanded ? "▾" : "▸"}</span>
            </Button>
            <span className="rounded-full bg-muted px-2 py-0.5 font-medium text-foreground text-xs">
              {label}
            </span>
            <span className="text-muted-foreground text-xs">{count}</span>
          </div>
        );
      }

      // Aggregated cells: keep minimal. For placeholder cells on leaf rows,
      // render the actual value to preserve alignment and visibility in subgroups.
      if (info.cell.getIsAggregated?.()) {
        return <span className="text-muted-foreground"> </span>;
      }

      return (
        <TagCell
          className={className}
          tagColorMap={tagColorMap}
          value={info.getValue()}
        />
      );
    },
    enableColumnFilter,
    enableHiding,
    enableSorting,
    header,
    icon: Tag,
    id,
    type: "tag",
  };
}

/**
 * Text column component for data tables
 * Provides standardized display of text values
 */
"use client";

import type { CellContext, ColumnDef } from "@tanstack/react-table";
import { type LucideIcon, Text } from "lucide-react";
import { useState } from "react";
import { Button } from "@/components/ui/button";
import { StringCell } from "../cells/string-cell";

/**
 * Custom properties for our column definitions
 */
interface CustomColumnProps {
  icon?: LucideIcon;
  type?: string;
}

/**
 * Combined type for our column definition
 */
type ExtendedColumnDef<TData> = ColumnDef<TData> & CustomColumnProps;

interface TextColumnProps {
  /**
   * Key to access the text value from the row data
   */
  accessorKey: string;

  /**
   * Optional CSS class for the cell
   */
  className?: string;

  /**
   * Whether the column can be filtered
   * @default true
   */
  enableColumnFilter?: boolean;

  /**
   * Whether the column can be hidden
   * @default true
   */
  enableHiding?: boolean;

  /**
   * Whether the column can be sorted
   * @default true
   */
  enableSorting?: boolean;

  /**
   * Optional custom header text
   */
  header?: string;
}

/**
 * Creates a text column definition
 * @returns Column definition for displaying text values
 */
export function createTextColumn<TData>({
  accessorKey,
  className = "",
  enableColumnFilter = true,
  enableHiding = true,
  enableSorting = true,
  header,
}: TextColumnProps): ExtendedColumnDef<TData> {
  return {
    accessorKey,
    // Enable grouping by default for textual columns
    enableGrouping: true,
    // When grouped, use the raw value for grouping label
    getGroupingValue: (row: unknown) => {
      const value = (row as Record<string, unknown>)[accessorKey];
      return typeof value === "string" ? value : String(value ?? "");
    },
    // Show plain label in aggregated cell
    aggregatedCell: ({ getValue }) => {
      const label = String(getValue() ?? "");
      return <span className="font-medium">{label}</span>;
    },
    cell: (info: CellContext<TData, unknown>) => {
      const isGrouped = info.cell.getIsGrouped();
      const isAggregated = info.cell.getIsAggregated();
      const _isPlaceholder = info.cell.getIsPlaceholder();

      // Debug removed to stop spam

      // FORCE group header display for ANY row that has subRows (bypass TanStack detection)
      const hasSubRows = (info.row.subRows?.length ?? 0) > 0;
      if (isGrouped || hasSubRows) {
        const GroupHeader = () => {
          const [localExpanded, setLocalExpanded] = useState(true); // Start expanded
          const count = info.row.subRows?.length ?? 0;
          const label = String(info.getValue() ?? "");

          return (
            <Button
              className="flex w-full cursor-pointer items-center gap-2 border-0 bg-red-100 p-2 text-left hover:bg-red-200"
              onClick={(e) => {
                e.stopPropagation();
                setLocalExpanded(!localExpanded);
              }}
              type="button"
              variant="ghost"
            >
              <span aria-hidden className="text-lg text-muted-foreground">
                {localExpanded ? "▾" : "▸"}
              </span>
              <span className="font-medium">{label}</span>
              <span className="rounded-full bg-muted px-2 py-0.5 text-muted-foreground text-xs">
                {count}
              </span>
            </Button>
          );
        };

        return <GroupHeader />;
      }

      // Aggregated cells: keep minimal. For placeholder cells (e.g., grouped column on leaf rows),
      // render the actual value so columns stay aligned and data remains visible.
      if (isAggregated) {
        return <span className="text-muted-foreground"> </span>;
      }

      // Regular cell
      const value = info.getValue();
      return <StringCell className={className} value={value} />;
    },
    enableColumnFilter,
    enableHiding,
    enableSorting,
    header: header || accessorKey,
    icon: Text,
    id: accessorKey,
    type: "text",
  };
}

/**
 * Pagination component for DataTable
 * Provides controls for navigating between pages
 */
"use client";

import type { Table } from "@tanstack/react-table";
import {
  ChevronLeft,
  ChevronRight,
  ChevronsLeft,
  ChevronsRight,
} from "lucide-react";
import { useCallback, useEffect, useState } from "react";
import { Button } from "@/components/ui/button";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";

// Use static Select import; SSR-safe usage is handled by mounted state

import { cn } from "@/lib/utils";

import { useTableTranslations } from "../hooks";

interface DataTablePaginationProps<TData> {
  /**
   * Additional CSS classes for the pagination container
   */
  className?: string;

  /**
   * Total number of rows in the dataset
   */
  rowCount?: number;

  /**
   * Table instance from TanStack Table
   */
  table: Table<TData>;

  /**
   * Unique identifier for the table
   */
  tableId: string;
}

/**
 * Pagination component for DataTable
 * Provides controls for navigating between pages
 */
export function DataTablePagination<TData>({
  className,
  rowCount,
  table,
  tableId: _tableId,
}: DataTablePaginationProps<TData>) {
  // Get translations
  const translations = useTableTranslations();
  // Avoid hydration/compose-ref loops from Radix Select on first render
  const [mounted, setMounted] = useState(false);
  useEffect(() => {
    setMounted(true);
  }, []);

  // Get pagination state directly from table
  const { pageIndex, pageSize } = table.getState().pagination;
  const pageCount = table.getPageCount();

  // Calculate start and end row numbers for display
  const startRow = pageIndex * pageSize + 1;
  const endRow = Math.min(
    (pageIndex + 1) * pageSize,
    rowCount || table.getRowModel().rows.length
  );

  // Handle page size change
  const handlePageSizeChange = useCallback(
    (value: string) => {
      const next = Number(value);
      if (Number.isNaN(next)) {
        return;
      }
      // Guard to avoid update loops if Radix re-fires onValueChange with same value
      const current = table.getState().pagination.pageSize;
      if (next === current) {
        return;
      }
      table.setPageSize(next);
    },
    [table]
  );

  // During SSR/first paint, render a simple static pagination to avoid Radix hydration refs
  if (!mounted) {
    return (
      <div
        className={cn(
          "flex flex-col items-center justify-between gap-4 py-4 sm:flex-row",
          className
        )}
      >
        <div className="flex-1 text-muted-foreground text-sm">
          {startRow}-{endRow} {translations.of}{" "}
          {rowCount || table.getRowModel().rows.length}
        </div>
        <div className="flex items-center gap-2">
          <p className="font-medium text-sm">{translations.rowsPerPage}</p>
          <div className="h-8 w-[70px] rounded border px-2 py-1 text-center text-sm">
            {pageSize}
          </div>
        </div>
        <div className="flex items-center gap-2 opacity-60">
          <span className="text-sm">
            {translations.format("pageXofY", {
              page: pageIndex + 1,
              total: pageCount || 1,
            })}
          </span>
        </div>
      </div>
    );
  }

  return (
    <div
      className={cn(
        "flex flex-col items-center justify-between gap-4 py-4 sm:flex-row",
        className
      )}
    >
      {/* Row range display */}
      <div className="flex-1 text-muted-foreground text-sm">
        {startRow}-{endRow} {translations.of}{" "}
        {rowCount || table.getRowModel().rows.length}
      </div>

      {/* Page size selector */}
      <div className="flex items-center gap-2">
        <p className="font-medium text-sm">{translations.rowsPerPage}</p>
        {mounted ? (
          <Select
            defaultValue={pageSize.toString()}
            key={`ps-${pageSize}-mounted`}
            onValueChange={(value) =>
              value != null && handlePageSizeChange(value)
            }
          >
            <SelectTrigger className="h-8 w-[70px]">
              <SelectValue placeholder={pageSize} />
            </SelectTrigger>
            <SelectContent>
              {[10, 20, 30, 40, 50].map((size) => (
                <SelectItem key={size} value={size.toString()}>
                  {size}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
        ) : (
          <div className="h-8 w-[70px] animate-pulse rounded bg-muted" />
        )}
      </div>

      {/* Page navigation */}
      <div className="flex items-center gap-2">
        <Button
          aria-label={translations.firstPage}
          className="h-8 w-8"
          disabled={!table.getCanPreviousPage()}
          onClick={() => table.setPageIndex(0)}
          size="icon"
          type="button"
          variant="outline"
        >
          <ChevronsLeft className="h-4 w-4" />
        </Button>
        <Button
          aria-label={translations.previousPage}
          className="h-8 w-8"
          disabled={!table.getCanPreviousPage()}
          onClick={() => table.previousPage()}
          size="icon"
          type="button"
          variant="outline"
        >
          <ChevronLeft className="h-4 w-4" />
        </Button>

        <span className="text-sm">
          {translations.format("pageXofY", {
            page: pageIndex + 1,
            total: pageCount || 1,
          })}
        </span>

        <Button
          aria-label={translations.nextPage}
          className="h-8 w-8"
          disabled={!table.getCanNextPage()}
          onClick={() => table.nextPage()}
          size="icon"
          type="button"
          variant="outline"
        >
          <ChevronRight className="h-4 w-4" />
        </Button>
        <Button
          aria-label={translations.lastPage}
          className="h-8 w-8"
          disabled={!table.getCanNextPage()}
          onClick={() => table.setPageIndex(table.getPageCount() - 1)}
          size="icon"
          type="button"
          variant="outline"
        >
          <ChevronsRight className="h-4 w-4" />
        </Button>
      </div>
    </div>
  );
}

