type SortBy = "label" | "count" | "value" | "trending";
type SortOrder = "asc" | "desc";

/**
 * Individual faceted option component
 */
function FacetedOption({
  option,
  isSelected,
  isDisabled,
  showCount = true,
  showPercentage = false,
  onToggle,
  multiSelect = true,
  level = 0,
}: {
  option: FacetedData;
  isSelected: boolean;
  isDisabled: boolean;
  showCount?: boolean;
  showPercentage?: boolean;
  onToggle: (value: unknown, selected: boolean) => void;
  multiSelect?: boolean;
  level?: number;
}) {
  const [isExpanded, setIsExpanded] = useState(false);
  const hasChildren = option.children && option.children.length > 0;

  const handleToggle = useCallback(() => {
    if (isDisabled) {
      return;
    }
    onToggle(option.value, !isSelected);
  }, [option.value, isSelected, isDisabled, onToggle]);

  const handleChildToggle = useCallback(
    (childValue: unknown, selected: boolean) => {
      onToggle(childValue, selected);
    },
    [onToggle]
  );

  return (
    <div className="space-y-1">
      <div
        className={cn(
          "flex items-center gap-2 rounded-md px-2 py-1 transition-colors hover:bg-accent/50",
          level > 0 && "ml-4",
          isDisabled && "cursor-not-allowed opacity-50"
        )}
        style={{ paddingLeft: `${8 + level * 16}px` }}
      >
        {/* Expand/collapse for hierarchical options */}
        {hasChildren && (
          <Button
            className="h-4 w-4 p-0"
            onClick={() => setIsExpanded(!isExpanded)}
            size="sm"
            type="button"
            variant="ghost"
          >
            {isExpanded ? (
              <ChevronDown className="h-3 w-3" />
            ) : (
              <ChevronRight className="h-3 w-3" />
            )}
          </Button>
        )}

        {/* Selection control */}
        <div className="flex items-center">
          {multiSelect ? (
            <Checkbox
              checked={isSelected}
              className="h-4 w-4"
              disabled={isDisabled}
              onCheckedChange={handleToggle}
            />
          ) : (
            <input
              checked={isSelected}
              className="h-4 w-4"
              disabled={isDisabled}
              onChange={handleToggle}
              type="radio"
            />
          )}
        </div>

        {/* Option content */}
        <div className="flex min-w-0 flex-1 items-center justify-between">
          <div className="flex min-w-0 flex-1 items-center gap-2">
            <span className="truncate text-sm">{option.label}</span>

            {/* Metadata indicators */}
            <div className="flex items-center gap-1">
              {option.metadata?.trending && (
                <TrendingUp className="h-3 w-3 text-emerald-500" />
              )}
              {option.metadata?.new && (
                <Sparkles className="h-3 w-3 text-blue-500" />
              )}
              {option.metadata?.priority === 1 && (
                <Star className="h-3 w-3 text-amber-500" />
              )}
            </div>
          </div>

          {/* Count and percentage */}
          <div className="flex items-center gap-2 text-muted-foreground text-xs">
            {showCount && (
              <Badge className="text-xs" variant="secondary">
                {option.count.toLocaleString()}
              </Badge>
            )}
            {showPercentage && option.percentage > 0 && (
              <span className="text-xs">{option.percentage.toFixed(1)}%</span>
            )}
          </div>
        </div>
      </div>

      {/* Children */}
      {hasChildren && isExpanded && (
        <Collapsible open={isExpanded}>
          <CollapsibleContent className="space-y-1">
            {option.children?.map((child) => (
              <FacetedOption
                isDisabled={isDisabled}
                isSelected={isSelected}
                key={String(child.value)}
                level={level + 1}
                multiSelect={multiSelect}
                onToggle={handleChildToggle}
                option={child}
                showCount={showCount}
                showPercentage={showPercentage}
              />
            ))}
          </CollapsibleContent>
        </Collapsible>
      )}
    </div>
  );
}

