/**
 * Helper function to filter options based on search query
 */
function filterOptions(
  options: FacetedData[],
  searchQuery: string
): FacetedData[] {
  if (!searchQuery.trim()) {
    return options;
  }
  const query = searchQuery.toLowerCase();
  return options.filter(
    (option) =>
      option.label.toLowerCase().includes(query) ||
      String(option.value).toLowerCase().includes(query)
  );
}

/**
 * Helper function to sort options
 */
function sortOptions(
  options: FacetedData[],
  sortBy: SortBy,
  sortOrder: SortOrder
): FacetedData[] {
  return [...options].sort((a, b) => {
    let comparison = 0;

    switch (sortBy) {
      case "label":
        comparison = a.label.localeCompare(b.label);
        break;
      case "count":
        comparison = a.count - b.count;
        break;
      case "value":
        comparison = String(a.value).localeCompare(String(b.value));
        break;
      case "trending": {
        const aTrending = a.metadata?.trending ? 1 : 0;
        const bTrending = b.metadata?.trending ? 1 : 0;
        comparison = aTrending - bTrending;
        break;
      }
      default:
        comparison = 0;
        break;
    }

    return sortOrder === "asc" ? comparison : -comparison;
  });
}

