/**
 * Main advanced faceted filter component
 */
export function AdvancedFacetedFilter({
  columnId,
  config,
  facetedData,
  selectedValues = [],
  onSelectionChange,
  disabled = false,
  maxHeight = 300,
  searchable = true,
  showCounts = true,
  showPercentages = false,
  multiSelect = true,
  virtualized: _virtualized = false,
  className,
  maxVisible: _maxVisible = 200,
  showSelectAll: _showSelectAll = true,
  showStats: _showStats = true,
}: AdvancedFacetedFilterProps) {
  // Local state
  const [searchQuery, setSearchQuery] = useState("");
  const [sortBy, setSortBy] = useState<SortBy>("count");
  const [sortOrder, setSortOrder] = useState<SortOrder>("desc");
  const [isExpanded, setIsExpanded] = useState(false);

  // Memoized filtered and sorted options
  const processedOptions = useMemo(() => {
    const filtered = filterOptions(facetedData, searchQuery);
    return sortOptions(filtered, sortBy, sortOrder);
  }, [facetedData, searchQuery, sortBy, sortOrder]);

  // Handle selection changes
  const handleToggle = useCallback(
    (value: unknown, selected: boolean) => {
      if (disabled) {
        return;
      }

      let newSelection: unknown[];

      if (multiSelect) {
        if (selected) {
          newSelection = [...selectedValues, value];
        } else {
          newSelection = selectedValues.filter((v) => v !== value);
        }
      } else {
        newSelection = selected ? [value] : [];
      }

      onSelectionChange(newSelection);
    },
    [selectedValues, onSelectionChange, disabled, multiSelect]
  );

  // Quick selection handlers
  const handleSelectAll = useCallback(() => {
    if (disabled) {
      return;
    }
    const allValues = processedOptions.map((opt) => opt.value);
    onSelectionChange(allValues);
  }, [processedOptions, onSelectionChange, disabled]);

  const handleSelectNone = useCallback(() => {
    if (disabled) {
      return;
    }
    onSelectionChange([]);
  }, [onSelectionChange, disabled]);

  const handleSelectTop = useCallback(() => {
    if (disabled) {
      return;
    }
    const topValues = processedOptions
      .sort((a, b) => b.count - a.count)
      .slice(0, 5)
      .map((opt) => opt.value);
    onSelectionChange(topValues);
  }, [processedOptions, onSelectionChange, disabled]);

  const handleSelectTrending = useCallback(() => {
    if (disabled) {
      return;
    }
    const trendingValues = processedOptions
      .filter((opt) => opt.metadata?.trending)
      .map((opt) => opt.value);
    onSelectionChange(trendingValues);
  }, [processedOptions, onSelectionChange, disabled]);

  const selectedCount = selectedValues.length;
  const totalCount = processedOptions.length;

  // Compact mode for small spaces
  if (!isExpanded) {
    return (
      <Popover onOpenChange={setIsExpanded} open={isExpanded}>
        <PopoverTrigger>
          <Button
            className={cn(
              "justify-between",
              selectedCount > 0 && "border-primary",
              disabled && "opacity-50",
              className
            )}
            disabled={disabled}
            variant="outline"
          >
            <div className="flex items-center gap-2">
              <Filter className="h-4 w-4" />
              <span>
                {config.label || columnId}
                {selectedCount > 0 && ` (${selectedCount})`}
              </span>
            </div>
            <ChevronDown className="h-4 w-4" />
          </Button>
        </PopoverTrigger>

        <PopoverContent align="start" className="w-80 p-0">
          <FilterContent
            columnId={columnId}
            config={config}
            handleSelectAll={handleSelectAll}
            handleSelectNone={handleSelectNone}
            handleSelectTop={handleSelectTop}
            handleSelectTrending={handleSelectTrending}
            handleToggle={handleToggle}
            maxHeight={maxHeight}
            multiSelect={multiSelect}
            processedOptions={processedOptions}
            searchable={searchable}
            searchQuery={searchQuery}
            selectedCount={selectedCount}
            selectedValues={selectedValues}
            setSearchQuery={setSearchQuery}
            setSortBy={setSortBy}
            setSortOrder={setSortOrder}
            showCounts={showCounts}
            showPercentages={showPercentages}
            sortBy={sortBy}
            sortOrder={sortOrder}
            totalCount={totalCount}
          />
        </PopoverContent>
      </Popover>
    );
  }

  // Expanded mode for dedicated space
  return (
    <div className={cn("space-y-4 rounded-lg border p-4", className)}>
      {/* Header */}
      <div className="flex items-center justify-between">
        <h3 className="font-medium">{config.label || columnId}</h3>
        <Button
          className="h-6 w-6 p-0"
          onClick={() => setIsExpanded(false)}
          size="sm"
          variant="ghost"
        >
          <X className="h-4 w-4" />
        </Button>
      </div>

      {/* Controls */}
      {searchable && (
        <FilterControls
          onClear={handleSelectNone}
          onSearchChange={setSearchQuery}
          onSortByChange={setSortBy}
          onSortOrderChange={setSortOrder}
          searchQuery={searchQuery}
          selectedCount={selectedCount}
          sortBy={sortBy}
          sortOrder={sortOrder}
          totalCount={totalCount}
        />
      )}

      {/* Quick selection */}
      {multiSelect && (
        <QuickSelection
          onSelectAll={handleSelectAll}
          onSelectNone={handleSelectNone}
          onSelectTop={handleSelectTop}
          onSelectTrending={handleSelectTrending}
          options={processedOptions}
        />
      )}

      <Separator />

      {/* Options list */}
      <ScrollArea style={{ maxHeight }}>
        {processedOptions.length === 0 ? (
          <div className="py-8 text-center text-muted-foreground">
            <Search className="mx-auto mb-3 h-8 w-8 opacity-50" />
            <h4 className="mb-1 font-medium">No options found</h4>
            <p className="text-sm">
              {searchQuery
                ? "Try a different search term"
                : "No data available for this filter"}
            </p>
          </div>
        ) : (
          <div className="space-y-1">
            {processedOptions.map((option) => (
              <FacetedOption
                isDisabled={option.isDisabled}
                isSelected={selectedValues.includes(option.value)}
                key={String(option.value)}
                multiSelect={multiSelect}
                onToggle={handleToggle}
                option={option}
                showCount={showCounts}
                showPercentage={showPercentages}
              />
            ))}
          </div>
        )}
      </ScrollArea>
    </div>
  );
}

/**
 * Statistics summary component
 */
function FacetedStats({
  data,
  selectedCount,
  totalCount: _totalCount,
}: {
  data: FacetedData[];
  selectedCount: number;
  totalCount: number;
}) {
  const visibleOptions = data.filter((d) => !d.isDisabled).length;
  const totalRecords = data.reduce((sum, d) => sum + d.count, 0);
  const selectedRecords = data
    .filter((d) => d.isSelected)
    .reduce((sum, d) => sum + d.count, 0);

  return (
    <div className="rounded-md bg-muted/30 p-3">
      <div className="mb-2 flex items-center gap-2">
        <BarChart3 className="h-4 w-4 text-muted-foreground" />
        <span className="font-medium text-sm">Statistics</span>
      </div>

      <div className="grid grid-cols-2 gap-4 text-sm">
        <div>
          <div className="text-muted-foreground">Options</div>
          <div className="font-medium">
            {selectedCount} / {visibleOptions}
          </div>
        </div>
        <div>
          <div className="text-muted-foreground">Records</div>
          <div className="font-medium">
            {selectedRecords.toLocaleString()} / {totalRecords.toLocaleString()}
          </div>
        </div>
      </div>

      {selectedCount > 0 && (
        <div className="mt-2 text-muted-foreground text-xs">
          Coverage: {((selectedRecords / totalRecords) * 100).toFixed(1)}% of
          data
        </div>
      )}
    </div>
  );
}

/**
 * Compact variant for smaller spaces
 */
export function CompactFacetedFilter({
  columnId,
  selectedValues,
  facetedData,
  config,
  onSelectionChange,
  disabled = false,
  className,
}: Omit<
  AdvancedFacetedFilterProps,
  | "maxHeight"
  | "searchable"
  | "showCounts"
  | "showPercentages"
  | "multiSelect"
  | "virtualized"
  | "maxVisible"
  | "showSelectAll"
  | "showStats"
>) {
  const [isOpen, setIsOpen] = useState(false);
  const selectedCount = selectedValues.length;

  return (
    <Popover onOpenChange={setIsOpen} open={isOpen}>
      <PopoverTrigger>
        <Button
          className={cn("justify-between", className)}
          disabled={disabled}
          size="sm"
          variant="outline"
        >
          <span className="truncate">
            {selectedCount > 0
              ? `${config.label || columnId} (${selectedCount})`
              : config.label || columnId}
          </span>
          <ChevronDown className="ml-2 h-4 w-4 shrink-0" />
        </Button>
      </PopoverTrigger>

      <PopoverContent align="start" className="w-80 p-0">
        <div className="space-y-4 p-4">
          {/* Header */}
          <div className="flex items-center justify-between">
            <h4 className="font-medium">{config.label || columnId}</h4>
            <div className="flex items-center gap-1 text-muted-foreground text-xs">
              <Target className="h-3 w-3" />
              <span>{selectedCount} options</span>
            </div>
          </div>

          {/* Controls */}
          <div className="flex items-center justify-between">
            <Button
              className="h-6 px-2 text-xs"
              disabled={disabled || selectedCount === 0}
              onClick={() => onSelectionChange(facetedData.map((d) => d.value))}
              size="sm"
              variant="ghost"
            >
              Select All ({facetedData.length})
            </Button>

            {selectedCount > 0 && (
              <Button
                className="h-6 px-2 text-muted-foreground text-xs"
                disabled={disabled}
                onClick={() => onSelectionChange([])}
                size="sm"
                variant="ghost"
              >
                Clear ({selectedCount})
              </Button>
            )}
          </div>

          <Separator />

          {/* Options list */}
          <div className="max-h-60 overflow-y-auto">
            {facetedData.length === 0 ? (
              <div className="py-8 text-center text-muted-foreground">
                <Search className="mx-auto mb-3 h-8 w-8 opacity-50" />
                <h5 className="mb-1 font-medium">No options available</h5>
              </div>
            ) : (
              <div className="space-y-1">
                {facetedData.map((option) => (
                  <FacetedOption
                    isDisabled={option.isDisabled}
                    isSelected={selectedValues.includes(option.value)}
                    key={String(option.value)}
                    onToggle={(value, selected) =>
                      onSelectionChange(
                        selected
                          ? [...selectedValues, value]
                          : selectedValues.filter((v) => v !== value)
                      )
                    }
                    option={option}
                  />
                ))}
              </div>
            )}
          </div>

          {/* Statistics */}
          <FacetedStats
            data={facetedData}
            selectedCount={selectedCount}
            totalCount={facetedData.length}
          />
        </div>
      </PopoverContent>
    </Popover>
  );
}

/**
 * Advanced filter panel component
 * Main interface for managing advanced filters with design inspired by bazza/ui and Linear
 */
"use client";

import {
  Calendar,
  CheckSquare,
  Filter,
  Hash,
  List as ListIcon,
  MoreHorizontal,
  Pencil,
  Plus,
  Power,
  RotateCcw,
  Trash2,
  Type,
  X,
} from "lucide-react";
import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { cn } from "@/lib/utils";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import { Label } from "@/components/ui/label";
import { Popover, PopoverContent, PopoverTrigger } from "@/components/ui/popover";
import { Separator } from "@/components/ui/separator";
import {
  Tooltip,
  TooltipContent,
  TooltipProvider,
  TooltipTrigger,
} from "@/components/ui/tooltip";
import {
  type AdvancedFilterModel,
  type AdvancedFiltersState,
  type ColumnDataType,
  type ColumnsFilterConfig,
  FILTER_OPERATORS_LABELS,
