/**
 * Compact filter panel for smaller spaces
 */
export function CompactFilterPanel({
  filters,
  columnsConfig,
  actions,
  disabled = false,
}: Pick<
  AdvancedFilterPanelProps,
  "filters" | "columnsConfig" | "actions" | "disabled"
>) {
  const [isExpanded, setIsExpanded] = useState(false);
  const [showInlineAdd, setShowInlineAdd] = useState(false);
  const activeFiltersCount = filters.filter((f) => f.isActive).length;

  if (filters.length === 0) {
    return (
      <div className="flex items-center justify-between gap-3 rounded-md border border-muted border-dashed bg-muted/10 p-2">
        <div className="flex items-center gap-2">
          <Filter className="h-3 w-3 shrink-0 text-muted-foreground opacity-50" />
          <span className="text-muted-foreground text-xs">No filters</span>
        </div>
        <TooltipProvider>
          <Tooltip>
            <TooltipTrigger>
              <Button
                className="h-7 px-2 text-xs"
                disabled={disabled}
                onClick={() => setShowInlineAdd((v) => !v)}
                size="sm"
                variant="outline"
              >
                Add filter...
              </Button>
            </TooltipTrigger>
            <TooltipContent>
              <p>Add filters to narrow down results</p>
            </TooltipContent>
          </Tooltip>
        </TooltipProvider>
        {showInlineAdd && (
          <div className="mt-2">
            <InlineAddFilterPanel
              activeFiltersCount={0}
              columnsConfig={columnsConfig}
              disabled={disabled}
              onAddFilter={(columnId, type) => {
                const operator = getDefaultFilterOperator(type);
                const value = getDefaultFilterValue(type, operator) as
                  | string
                  | number
                  | [number, number]
                  | Date
                  | [Date, Date]
                  | string[];
                actions.addFilter({
                  columnId,
                  type,
                  operator,
                  values: value,
                  isActive: true,
                });
                setShowInlineAdd(false);
              }}
            />
          </div>
        )}
      </div>
    );
  }

  return (
    <Popover onOpenChange={setIsExpanded} open={isExpanded}>
      <PopoverTrigger>
        <Button
          className="h-7 gap-1"
          disabled={disabled}
          size="sm"
          variant="outline"
        >
          <Filter className="h-3 w-3" />
          {activeFiltersCount > 0 ? `${activeFiltersCount} filters` : "Filter"}
        </Button>
      </PopoverTrigger>
      <PopoverContent
        align="start"
        className="w-auto min-w-96 max-w-screen-sm p-4"
      >
        <div className="space-y-3">
          <div className="flex items-center justify-between">
            <Label className="font-medium">Filters</Label>
            {filters.length > 0 && (
              <Button
                className="h-6 text-xs"
                onClick={actions.clearFilters}
                size="sm"
                variant="ghost"
              >
                Clear all
              </Button>
            )}
          </div>

          <div className="max-h-80 overflow-y-auto">
            <div className="space-y-2">
              {filters.map((filter) => {
                const config = columnsConfig[filter.columnId];
                if (!config) {
                  return null;
                }

                return (
                  <FilterChip
                    config={config}
                    disabled={disabled}
                    filter={filter}
                    key={filter.id}
                    onRemove={() => actions.removeFilter(filter.id)}
                    onToggle={() => actions.toggleFilter(filter.id)}
                    onUpdate={(updates) =>
                      actions.updateFilter(filter.id, updates)
                    }
                  />
                );
              })}
            </div>
          </div>

          <Separator />

          <InlineAddFilterPanel
            activeFiltersCount={filters.filter((f) => f.isActive).length}
            columnsConfig={columnsConfig}
            disabled={disabled}
            onAddFilter={(columnId, type) => {
              const operator = getDefaultFilterOperator(type);
              const value = getDefaultFilterValue(type, operator) as
                | string
                | number
                | [number, number]
                | Date
                | [Date, Date]
                | string[];
              actions.addFilter({
                columnId,
                type,
                operator,
                values: value,
                isActive: true,
              });
            }}
            onReset={actions.clearFilters}
          />
        </div>
      </PopoverContent>
    </Popover>
  );
}

/**
 * Date filter component
 * Provides filtering for date columns with various date operators and date picker
 */
"use client";

import { format } from "date-fns";
import { CalendarIcon, ChevronDown } from "lucide-react";
import { useCallback, useEffect, useState } from "react";
import { cn } from "@/lib/utils";
import { Button } from "@/components/ui/button";
import { Calendar } from "@/components/ui/calendar";
import { Label } from "@/components/ui/label";
import { Popover, PopoverContent, PopoverTrigger } from "@/components/ui/popover";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { useTranslations } from "../../providers/table-provider";
import type { FilterOperators } from "../../types/filter-types";
import {
  DEFAULT_OPERATORS,
  FILTER_OPERATORS_LABELS,
} from "../../types/filter-types";

export interface DateFilterProps {
  /** Current filter value - single date or [start, end] for between */
  value: Date | [Date, Date];
  /** Current operator */
  operator: FilterOperators["date"];
  /** Available operators (defaults to all date operators) */
  operators?: readonly FilterOperators["date"][];
  /** Whether the filter is disabled */
  disabled?: boolean;
  /** Callback when the value changes */
  onValueChange: (value: Date | [Date, Date]) => void;
  /** Callback when the operator changes */
  onOperatorChange: (operator: FilterOperators["date"]) => void;
  /** Optional label */
  label?: string;
  /** Whether to show the operator selector */
  showOperator?: boolean;
  /** Date format for display */
  dateFormat?: string;
  /** Render pickers inline instead of popover */
  inline?: boolean;
}

/**
 * Date filter component with operator selection and date picker
 */
export function DateFilter({
  value,
  operator,
  operators = DEFAULT_OPERATORS.date,
  disabled = false,
  onValueChange,
  onOperatorChange,
  label,
  showOperator = true,
  dateFormat = "PPP",
  inline = false,
}: DateFilterProps) {
  const { t } = useTranslations();
  const [internalValue, setInternalValue] = useState(value);
  const [isOpen, setIsOpen] = useState(false);

  // Sync internal value with prop
  useEffect(() => {
    setInternalValue(value);
  }, [value]);

  // Handle value change
  const handleValueChange = useCallback(
    (newValue: Date | [Date, Date]) => {
      setInternalValue(newValue);
      onValueChange(newValue);
    },
    [onValueChange]
  );

  // Check if this operator needs a value input
  const needsValue = !["isEmpty", "isNotEmpty"].includes(operator);
  const isBetween = operator === "between";
  const currentSingleValue = Array.isArray(internalValue)
    ? internalValue[0]
    : internalValue;
  const currentRangeValue = Array.isArray(internalValue)
    ? internalValue
    : [new Date(), new Date()];

  // Handle single date selection
  const handleSingleDateSelect = useCallback(
    (date: Date | undefined) => {
      if (date) {
        handleValueChange(date);
        setIsOpen(false);
      }
    },
    [handleValueChange]
  );

  // Handle date range selection
  const handleDateRangeSelect = useCallback(
    (range: { from?: Date; to?: Date } | undefined) => {
      if (range?.from && range?.to) {
        handleValueChange([range.from, range.to]);
        setIsOpen(false);
      } else if (range?.from) {
        // If only start date is selected, set end date to same date
        handleValueChange([range.from, range.from]);
      }
    },
    [handleValueChange]
  );

  // Format date for display
  const formatDateForDisplay = useCallback(
    (date: Date | [Date, Date]) => {
      if (Array.isArray(date)) {
        return `${format(date[0], dateFormat)} - ${format(date[1], dateFormat)}`;
      }
      return format(date, dateFormat);
    },
    [dateFormat]
  );

  return (
    <div className="space-y-3">
      {label && <Label className="font-medium text-sm">{label}</Label>}

      <div className="flex flex-col gap-3">
        {/* Operator selector */}
        {showOperator && (
          <Select
            disabled={disabled}
            onValueChange={(selectedValue) =>
              onOperatorChange(selectedValue as FilterOperators["date"])
            }
            value={operator}
          >
            <SelectTrigger className="w-full">
              <SelectValue placeholder={t("filters.select_operator")} />
            </SelectTrigger>
            <SelectContent>
              {operators.map((op) => (
                <SelectItem key={op} value={op}>
                  {FILTER_OPERATORS_LABELS.date[op]}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
        )}

        {/* Date picker */}
        {needsValue &&
          (inline ? (
            <div className="mr-auto w-fit rounded-md border p-2">
              {isBetween ? (
                <Calendar
                  className="[--cell-size:--spacing(7)] sm:[--cell-size:--spacing(8)]"
                  disabled={disabled}
                  initialFocus
                  mode="range"
                  onSelect={handleDateRangeSelect}
                  required
                  selected={{
                    from: currentRangeValue[0],
                    to: currentRangeValue[1],
                  }}
                />
              ) : (
                <Calendar
                  className="[--cell-size:--spacing(7)] sm:[--cell-size:--spacing(8)]"
                  disabled={disabled}
                  initialFocus
                  mode="single"
                  onSelect={handleSingleDateSelect}
                  selected={currentSingleValue}
                />
              )}
            </div>
          ) : (
            <Popover onOpenChange={setIsOpen} open={isOpen}>
              <PopoverTrigger>
                <Button
                  aria-expanded={isOpen}
                  className={cn(
                    "w-full justify-start text-left font-normal",
                    !internalValue && "text-muted-foreground"
                  )}
                  disabled={disabled}
                  type="button"
                  variant="outline"
                >
                  <CalendarIcon className="mr-2 h-4 w-4" />
                  <span className="flex-1 truncate">
                    {internalValue ? (
                      formatDateForDisplay(internalValue)
                    ) : (
                      <span>
                        {isBetween ? t("filters.value") : t("filters.value")}
                      </span>
                    )}
                  </span>
                  <ChevronDown className="ml-2 h-4 w-4 shrink-0 opacity-50" />
                </Button>
              </PopoverTrigger>
              <PopoverContent align="start" className="w-72 p-0">
                {isBetween ? (
                  <div className="space-y-2 p-2">
                    <DateRangeShortcuts
                      disabled={disabled}
                      onSelect={(range) => {
                        handleValueChange(range);
                        setIsOpen(false);
                      }}
                    />
                    <div className="rounded-md border">
                      <Calendar
                        className="[--cell-size:--spacing(7)] sm:[--cell-size:--spacing(8)]"
                        disabled={disabled}
                        initialFocus
                        mode="range"
                        onSelect={handleDateRangeSelect}
                        required
                        selected={{
                          from: currentRangeValue[0],
                          to: currentRangeValue[1],
                        }}
                      />
                    </div>
                  </div>
                ) : (
                  <div className="p-2">
                    <div className="rounded-md border">
                      <Calendar
                        className="[--cell-size:--spacing(7)] sm:[--cell-size:--spacing(8)]"
                        disabled={disabled}
                        initialFocus
                        mode="single"
                        onSelect={handleSingleDateSelect}
                        selected={currentSingleValue}
                      />
                    </div>
                  </div>
                )}
              </PopoverContent>
            </Popover>
          ))}

        {/* Info text for operators that don't need values */}
        {!needsValue && (
          <div className="text-muted-foreground text-sm italic">
            This filter will show rows where the field{" "}
            {operator === "isEmpty" ? "is empty" : "is not empty"}.
          </div>
        )}
      </div>
    </div>
  );
}

