/**
 * Save preset dialog
 */
function SavePresetDialog({
  currentState,
  onSave,
  isOpen,
  onOpenChange,
}: {
  currentState?: AdvancedFilterState;
  onSave: (options: {
    name: string;
    description?: string;
    tags?: string[];
    icon?: string;
    color?: string;
    isPublic?: boolean;
  }) => Promise<void>;
  isOpen: boolean;
  onOpenChange: (open: boolean) => void;
}) {
  const [name, setName] = useState("");
  const [description, setDescription] = useState("");
  const [tags, setTags] = useState("");
  const [isPublic, setIsPublic] = useState(false);
  const [isSaving, setIsSaving] = useState(false);

  const handleSave = async () => {
    if (!(name.trim() && currentState)) {
      return;
    }

    setIsSaving(true);
    try {
      await onSave({
        name,
        description: description || undefined,
        tags: tags
          .split(",")
          .map((t) => t.trim())
          .filter(Boolean),
        isPublic,
      });

      // Reset form
      setName("");
      setDescription("");
      setTags("");
      setIsPublic(false);
      onOpenChange(false);
    } catch (_error) {
      // Error handling can be added here if needed
    } finally {
      setIsSaving(false);
    }
  };

  const hasFilters = currentState?.groups.some(
    (group) => group.filters.length > 0 && group.isActive
  );

  return (
    <Dialog onOpenChange={onOpenChange} open={isOpen}>
      <DialogContent className="sm:max-w-md">
        <DialogHeader>
          <DialogTitle>Save Filter Preset</DialogTitle>
          <DialogDescription>
            Save your current filter configuration for future use.
          </DialogDescription>
        </DialogHeader>

        {hasFilters ? (
          <div className="space-y-4">
            <div className="space-y-2">
              <Label htmlFor="name">Name *</Label>
              <Input
                id="name"
                maxLength={100}
                onChange={(e) => setName(e.target.value)}
                placeholder="My awesome filter preset"
                value={name}
              />
            </div>

            <div className="space-y-2">
              <Label htmlFor="description">Description</Label>
              <Textarea
                id="description"
                maxLength={500}
                onChange={(e) => setDescription(e.target.value)}
                placeholder="Optional description..."
                rows={3}
                value={description}
              />
            </div>

            <div className="space-y-2">
              <Label htmlFor="tags">Tags</Label>
              <Input
                id="tags"
                onChange={(e) => setTags(e.target.value)}
                placeholder="work, urgent, weekly (comma separated)"
                value={tags}
              />
            </div>

            <div className="flex items-center space-x-2">
              <input
                checked={isPublic}
                className="rounded"
                id="public"
                onChange={(e) => setIsPublic(e.target.checked)}
                type="checkbox"
              />
              <Label htmlFor="public">
                Make public (visible to other users)
              </Label>
            </div>
          </div>
        ) : (
          <div className="py-6 text-center">
            <Filter className="mx-auto mb-2 h-8 w-8 text-muted-foreground opacity-50" />
            <p className="text-muted-foreground text-sm">
              No active filters to save. Add some filters first.
            </p>
          </div>
        )}

        <DialogFooter>
          <Button
            onClick={() => onOpenChange(false)}
            type="button"
            variant="outline"
          >
            Cancel
          </Button>
          <Button
            disabled={!(name.trim() && hasFilters) || isSaving}
            onClick={handleSave}
            type="button"
          >
            {isSaving ? "Saving..." : "Save Preset"}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

/**
 * Main filter presets panel
 */
export function FilterPresetsPanel({
  currentState,
  presets,
  onLoadPreset,
  compact = false,
  className,
}: FilterPresetsPanelProps) {
  const [searchQuery, setSearchQuery] = useState("");
  const [presetIdToDelete, setPresetIdToDelete] = useState<null | string>(null);
  const [selectedTab, setSelectedTab] = useState<
    "all" | "recent" | "popular" | "system"
  >("all");
  const [saveDialogOpen, setSaveDialogOpen] = useState(false);

  // Filter presets based on search and tab
  const filteredPresets = useMemo(() => {
    let filtered = presets.presets;

    // Filter by tab
    switch (selectedTab) {
      case "recent":
        filtered = presets.recentPresets;
        break;
      case "popular":
        filtered = presets.popularPresets;
        break;
      case "system":
        filtered = presets.systemPresets;
        break;
      default:
        // 'all' - no additional filtering
        break;
    }

    // Filter by search query
    if (searchQuery.trim()) {
      filtered = presets.searchPresets(searchQuery);
    }

    return filtered;
  }, [presets, searchQuery, selectedTab]);

  // Handle preset actions
  const handleLoadPreset = useCallback(
    async (presetId: string) => {
      try {
        const state = await presets.loadPreset(presetId);
        onLoadPreset?.(state);
      } catch (_error) {
        // Error handling can be added here if needed
      }
    },
    [presets, onLoadPreset]
  );

  const handleSavePreset = useCallback(
    async (options: {
      name: string;
      description?: string;
      isPublic?: boolean;
      tags?: string[];
      icon?: string;
      color?: string;
    }) => {
      if (!currentState) {
        return;
      }
      await presets.savePreset(currentState, options);
    },
    [presets, currentState]
  );

  const handleDeletePresetClick = useCallback((presetId: string) => {
    setPresetIdToDelete(presetId);
  }, []);

  const handleConfirmDeletePreset = useCallback(async () => {
    if (presetIdToDelete) {
      await presets.deletePreset(presetIdToDelete);
      setPresetIdToDelete(null);
    }
  }, [presets, presetIdToDelete]);

  const handleCancelDeletePreset = useCallback(() => {
    setPresetIdToDelete(null);
  }, []);

  const handleSharePreset = useCallback(
    async (presetId: string) => {
      try {
        const url = await presets.sharePreset(presetId);
        await navigator.clipboard.writeText(url);
        // You would show a toast notification here
      } catch (_error) {
        // Error handling can be added here if needed
      }
    },
    [presets]
  );

  const handleToggleFavorite = useCallback(
    async (presetId: string, isFavorite: boolean) => {
      await presets.setFavorite(presetId, !isFavorite);
    },
    [presets]
  );

  if (compact) {
    return (
      <div className={cn("space-y-3", className)}>
        <div className="flex items-center justify-between">
          <h3 className="font-medium text-sm">Presets</h3>
          <Button
            className="h-6 px-2 text-xs"
            onClick={() => setSaveDialogOpen(true)}
            size="sm"
          >
            <Save className="mr-1 h-3 w-3" />
            Save
          </Button>
        </div>

        <div className="grid grid-cols-2 gap-2">
          {filteredPresets.slice(0, 4).map((preset) => (
            <Button
              className="h-8 justify-start px-2 text-xs"
              key={preset.id}
              onClick={() => handleLoadPreset(preset.id)}
              size="sm"
              variant="outline"
            >
              {preset.icon && <span className="mr-1">{preset.icon}</span>}
              <span className="truncate">{preset.name}</span>
            </Button>
          ))}
        </div>

        <SavePresetDialog
          currentState={currentState}
          isOpen={saveDialogOpen}
          onOpenChange={setSaveDialogOpen}
          onSave={handleSavePreset}
        />
      </div>
    );
  }

  return (
    <div className={cn("space-y-4", className)}>
      <AlertDialog
        onOpenChange={(open) => {
          if (!open) {
            setPresetIdToDelete(null);
          }
        }}
        open={presetIdToDelete !== null}
      >
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Delete preset</AlertDialogTitle>
            <AlertDialogDescription>
              Are you sure you want to delete this preset? This action cannot be
              undone.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel onClick={handleCancelDeletePreset}>
              Cancel
            </AlertDialogCancel>
            <AlertDialogAction onClick={handleConfirmDeletePreset}>
              Delete
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>

      {/* Header */}
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-2">
          <Bookmark className="h-5 w-5 text-muted-foreground" />
          <h2 className="font-semibold text-lg">Filter Presets</h2>
        </div>

        <div className="flex items-center gap-2">
          <Button
            className="gap-1"
            onClick={() => setSaveDialogOpen(true)}
            size="sm"
          >
            <Save className="h-4 w-4" />
            Save Current
          </Button>

          <DropdownMenu>
            <DropdownMenuTrigger
              render={
                <Button size="sm" variant="outline">
                  <MoreHorizontal className="h-4 w-4" />
                </Button>
              }
            />
            <DropdownMenuContent align="end">
              <DropdownMenuItem>
                <Upload className="mr-2 h-4 w-4" />
                Import Presets
              </DropdownMenuItem>
              <DropdownMenuItem>
                <Download className="mr-2 h-4 w-4" />
                Export All
              </DropdownMenuItem>
            </DropdownMenuContent>
          </DropdownMenu>
        </div>
      </div>

      {/* Search */}
      <div className="relative">
        <Search className="absolute top-1/2 left-3 h-4 w-4 -translate-y-1/2 transform text-muted-foreground" />
        <Input
          className="pl-9"
          onChange={(e) => setSearchQuery(e.target.value)}
          placeholder="Search presets..."
          value={searchQuery}
        />
      </div>

      {/* Tabs */}
      <Tabs
        onValueChange={(value) =>
          setSelectedTab(value as "all" | "recent" | "popular" | "system")
        }
        value={selectedTab}
      >
        <TabsList className="grid w-full grid-cols-4">
          <TabsTrigger value="all">All</TabsTrigger>
          <TabsTrigger value="recent">Recent</TabsTrigger>
          <TabsTrigger value="popular">Popular</TabsTrigger>
          <TabsTrigger value="system">System</TabsTrigger>
        </TabsList>

        <TabsContent className="mt-4" value={selectedTab}>
          <ScrollArea className="h-96">
            {filteredPresets.length === 0 ? (
              <div className="py-12 text-center">
                <Sparkles className="mx-auto mb-3 h-8 w-8 text-muted-foreground opacity-50" />
                <h3 className="mb-1 font-medium">No presets found</h3>
                <p className="mb-4 text-muted-foreground text-sm">
                  {searchQuery
                    ? "Try a different search term"
                    : "Create your first preset by saving your current filters"}
                </p>
                {!searchQuery && (
                  <Button onClick={() => setSaveDialogOpen(true)}>
                    <Save className="mr-2 h-4 w-4" />
                    Save First Preset
                  </Button>
                )}
              </div>
            ) : (
              <div className="space-y-3">
                {filteredPresets.map((preset) => (
                  <PresetCard
                    isFavorite={preset.tags.includes("favorite")}
                    isPopular={presets.popularPresets.some(
                      (p) => p.id === preset.id
                    )}
                    isRecent={presets.recentPresets.some(
                      (p) => p.id === preset.id
                    )}
                    key={preset.id}
                    onDelete={() => handleDeletePresetClick(preset.id)}
                    onDuplicate={() => presets.duplicatePreset(preset.id)}
                    onEdit={() => {
                      /* TODO: Edit dialog */
                    }}
                    onLoad={() => handleLoadPreset(preset.id)}
                    onShare={() => handleSharePreset(preset.id)}
                    onToggleFavorite={() =>
                      handleToggleFavorite(
                        preset.id,
                        preset.tags.includes("favorite")
                      )
                    }
                    preset={preset}
                  />
                ))}
              </div>
            )}
          </ScrollArea>
        </TabsContent>
      </Tabs>

      {/* Save dialog */}
      <SavePresetDialog
        currentState={currentState}
        isOpen={saveDialogOpen}
        onOpenChange={setSaveDialogOpen}
        onSave={handleSavePreset}
      />
    </div>
  );
}

/**
 * Filter value input component
 * Central component that routes to the appropriate filter input based on data type
 */
"use client";

import { useCallback } from "react";
import type {
  ColumnDataType,
  ColumnFilterConfig,
  FilterOperators,
  FilterValues,
} from "../../types/filter-types";

import { CompactDateFilter, DateFilter } from "./date-filter";
import {
  CompactMultiOptionFilter,
  MultiOptionFilter,
} from "./multi-option-filter";
import { CompactNumberFilter, NumberFilter } from "./number-filter";
import { CompactOptionFilter, OptionFilter } from "./option-filter";
import { CompactTextFilter, TextFilter } from "./text-filter";

export interface FilterValueInputProps<
  TType extends ColumnDataType = ColumnDataType,
> {
  /** The column data type */
  type: TType;
  /** Current filter value */
  value: FilterValues<TType>;
  /** Current operator */
  operator: FilterOperators[TType];
  /** Column configuration */
  config: ColumnFilterConfig<TType>;
  /** Whether the filter is disabled */
  disabled?: boolean;
  /** Callback when the value changes */
  onValueChange: (value: FilterValues<TType>) => void;
  /** Callback when the operator changes */
  onOperatorChange: (operator: FilterOperators[TType]) => void;
  /** Optional label */
  label?: string;
  /** Whether to show the operator selector */
  showOperator?: boolean;
  /** Whether to use compact mode */
  compact?: boolean;
  /** Render value pickers inline (no popovers) */
  inline?: boolean;
}

/**
 * Filter value input component that routes to the appropriate filter based on data type
 */
export function FilterValueInput<TType extends ColumnDataType>({
  type,
  value,
  operator,
  config,
  disabled = false,
  onValueChange,
  onOperatorChange,
  label,
  showOperator = true,
  compact = false,
  inline = false,
}: FilterValueInputProps<TType>) {
  // Type-safe value change handler
  const handleValueChange = useCallback(
    (newValue: unknown) => {
      onValueChange(newValue as FilterValues<TType>);
    },
    [onValueChange]
  );

  // Type-safe operator change handler
  const handleOperatorChange = useCallback(
    (newOperator: unknown) => {
      onOperatorChange(newOperator as FilterOperators[TType]);
    },
    [onOperatorChange]
  );

  // Route to the appropriate filter component based on type
  switch (type) {
    case "text": {
      const textValue = value as string;
      const textOperator = operator as FilterOperators["text"];

      if (compact) {
        return (
          <CompactTextFilter
            disabled={disabled}
            onValueChange={handleValueChange}
            operator={textOperator}
            placeholder={config.placeholder}
            value={textValue}
          />
        );
      }

      return (
        <TextFilter
          debounceMs={0}
          disabled={disabled}
          label={label}
          onOperatorChange={handleOperatorChange}
          onValueChange={handleValueChange}
          operator={textOperator}
          operators={config.operators as readonly FilterOperators["text"][]}
          placeholder={config.placeholder}
          showOperator={showOperator}
          value={textValue}
        />
      );
    }

    case "number": {
      const numberValue = value as number | [number, number];
      const numberOperator = operator as FilterOperators["number"];

      if (compact) {
        return (
          <CompactNumberFilter
            disabled={disabled}
            onValueChange={handleValueChange}
            operator={numberOperator}
            placeholder={config.placeholder}
            value={numberValue}
          />
        );
      }

      return (
        <NumberFilter
          disabled={disabled}
          label={label}
          max={config.max}
          min={config.min}
          onOperatorChange={handleOperatorChange}
          onValueChange={handleValueChange}
          operator={numberOperator}
          operators={config.operators as readonly FilterOperators["number"][]}
          placeholder={config.placeholder}
          showOperator={showOperator}
          value={numberValue}
        />
      );
    }

    case "date": {
      const dateValue = value as Date | [Date, Date];
      const dateOperator = operator as FilterOperators["date"];

      if (compact) {
        return (
          <CompactDateFilter
            disabled={disabled}
            onValueChange={handleValueChange}
            operator={dateOperator}
            value={dateValue}
          />
        );
      }

      return (
        <DateFilter
          disabled={disabled}
          inline={inline}
          label={label}
          onOperatorChange={handleOperatorChange}
          onValueChange={handleValueChange}
          operator={dateOperator}
          operators={config.operators as readonly FilterOperators["date"][]}
          showOperator={showOperator}
          value={dateValue}
        />
      );
    }

    case "option": {
      const optionValue = value as string | string[];
      const optionOperator = operator as FilterOperators["option"];

      if (!config.options) {
        return null;
      }

      if (compact) {
        return (
          <CompactOptionFilter
            disabled={disabled}
            onValueChange={handleValueChange}
            operator={optionOperator}
            options={config.options}
            placeholder={config.placeholder}
            value={optionValue}
          />
        );
      }

      return (
        <OptionFilter
          disabled={disabled}
          inline={inline}
          label={label}
          onOperatorChange={handleOperatorChange}
          onValueChange={handleValueChange}
          operator={optionOperator}
          operators={config.operators as readonly FilterOperators["option"][]}
          options={config.options}
          placeholder={config.placeholder}
          showCounts={config.faceted}
          showOperator={showOperator}
          value={optionValue}
        />
      );
    }

    case "multiOption": {
      const multiOptionValue = value as string[];
      const multiOptionOperator = operator as FilterOperators["multiOption"];

      if (!config.options) {
        return null;
      }

      if (compact) {
        return (
          <CompactMultiOptionFilter
            disabled={disabled}
            onValueChange={handleValueChange}
            operator={multiOptionOperator}
            options={config.options}
            placeholder={config.placeholder}
            value={multiOptionValue}
          />
        );
      }

      return (
        <MultiOptionFilter
          disabled={disabled}
          inline={inline}
          label={label}
          onOperatorChange={handleOperatorChange}
          onValueChange={handleValueChange}
          operator={multiOptionOperator}
          operators={
            config.operators as readonly FilterOperators["multiOption"][]
          }
          options={config.options}
          placeholder={config.placeholder}
          showCounts={config.faceted}
          showOperator={showOperator}
          value={multiOptionValue}
        />
      );
    }

    default:
      return null;
  }
}

/**
 * Helper to get the default value for a filter type
 */
export function getDefaultFilterValue<TType extends ColumnDataType>(
  type: TType,
  operator: FilterOperators[TType]
): FilterValues<TType> {
  switch (type) {
    case "text":
      return "" as FilterValues<TType>;

    case "number": {
      const numOperator = operator as FilterOperators["number"];
      if (numOperator === "between") {
        return [0, 100] as FilterValues<TType>;
      }
      return 0 as FilterValues<TType>;
    }

    case "date": {
      const dateOperator = operator as FilterOperators["date"];
      if (dateOperator === "between") {
        const now = new Date();
        const tomorrow = new Date(now);
        tomorrow.setDate(tomorrow.getDate() + 1);
        return [now, tomorrow] as FilterValues<TType>;
      }
      return new Date() as FilterValues<TType>;
    }

    case "option": {
      const optOperator = operator as FilterOperators["option"];
      if (["isAnyOf", "isNoneOf"].includes(optOperator)) {
        return [] as FilterValues<TType>;
      }
      return "" as FilterValues<TType>;
    }

    case "multiOption":
      return [] as FilterValues<TType>;

    default:
      return "" as FilterValues<TType>;
  }
}

/**
 * Helper to get the default operator for a filter type
 */
export function getDefaultFilterOperator<TType extends ColumnDataType>(
  type: TType
): FilterOperators[TType] {
  switch (type) {
    case "text":
      return "contains" as FilterOperators[TType];
    case "number":
      return "equals" as FilterOperators[TType];
    case "date":
      return "equals" as FilterOperators[TType];
    case "option":
      return "is" as FilterOperators[TType];
    case "multiOption":
      return "contains" as FilterOperators[TType];
    default:
      return "equals" as FilterOperators[TType];
  }
}

/**
 * Helper to validate a filter value for a given type and operator
 */
export function isValidFilterValue<TType extends ColumnDataType>(
  type: TType,
  operator: FilterOperators[TType],
  value: FilterValues<TType>
): boolean {
  // Operators that don't need values are always valid
  if (["isEmpty", "isNotEmpty"].includes(operator as string)) {
    return true;
  }

  switch (type) {
    case "text":
      return typeof value === "string";

    case "number": {
      if (operator === "between") {
        return (
          Array.isArray(value) &&
          value.length === 2 &&
          typeof value[0] === "number" &&
          typeof value[1] === "number"
        );
      }
      return typeof value === "number" && !Number.isNaN(value);
    }

    case "date": {
      if (operator === "between") {
        return (
          Array.isArray(value) &&
          value.length === 2 &&
          value[0] instanceof Date &&
          value[1] instanceof Date
        );
      }
      return (
        value != null &&
        Object.prototype.toString.call(value) === "[object Date]" &&
        !Number.isNaN((value as Date).getTime())
      );
    }

    case "option": {
      if (["isAnyOf", "isNoneOf"].includes(operator as string)) {
        return Array.isArray(value);
      }
      return typeof value === "string";
    }

    case "multiOption":
      return Array.isArray(value);

    default:
      return false;
  }
}

