}

interface FilterEmptyStateProps {
  className?: string;
  title?: string;
  description?: string;
  onAddFilter?: () => void;
  showAddButton?: boolean;
  variant?: "default" | "compact" | "minimal";
}

interface FilterErrorStateProps {
  className?: string;
  title?: string;
  description?: string;
  onRetry?: () => void;
