/**
 * Success state when filters are working well
 */
export function FilterSuccessState({
  className,
  activeFiltersCount,
  totalResults,
  onClearAll,
}: {
  className?: string;
  activeFiltersCount: number;
  totalResults?: number;
  onClearAll?: () => void;
