  options,
  disabled = false,
  onValueChange,
  onOperatorChange,
  label,
  showOperator = true,
  showCounts = true,
  placeholder = "Select options...",
  maxDisplayedTags = 3,
  inline = false,
}: MultiOptionFilterProps) {
  const { t } = useTranslations();
  const [internalValue, setInternalValue] = useState(value);
  const [isOpen, setIsOpen] = useState(false);
  const [searchTerm, setSearchTerm] = useState("");

  // Sync internal value with prop
  useEffect(() => {
    setInternalValue(value);
  }, [value]);

  // Handle value change
  const handleValueChange = useCallback(
    (newValue: string[]) => {
      setInternalValue(newValue);
      onValueChange(newValue);
    },
    [onValueChange]
  );

  // Check if this operator needs a value input
  const needsValue = !["isEmpty", "isNotEmpty"].includes(operator);

  // Filter options based on search term
  const filteredOptions = useMemo(() => {
    if (!searchTerm) {
      return options;
    }
    return options.filter(
      (option) =>
        option.label.toLowerCase().includes(searchTerm.toLowerCase()) ||
        option.value.toLowerCase().includes(searchTerm.toLowerCase())
    );
  }, [options, searchTerm]);

  // Handle option selection toggle
  const handleOptionToggle = useCallback(
    (optionValue: string) => {
      const newValue = internalValue.includes(optionValue)
        ? internalValue.filter((v) => v !== optionValue)
        : [...internalValue, optionValue];
      handleValueChange(newValue);
    },
    [internalValue, handleValueChange]
  );

  // Handle select all
  const handleSelectAll = useCallback(() => {
    const allValues = filteredOptions.map((opt) => opt.value);
    handleValueChange(allValues);
  }, [filteredOptions, handleValueChange]);

  // Handle clear all
  const handleClearAll = useCallback(() => {
    handleValueChange([]);
  }, [handleValueChange]);

  // Get option by value
  const getOptionByValue = useCallback(
    (optionValue: string) => {
      return options.find((opt) => opt.value === optionValue);
    },
    [options]
  );

  // Format selected values for display
  const formatValueForDisplay = useCallback(() => {
    if (internalValue.length === 0) {
      return placeholder;
    }
    if (internalValue.length === 1) {
      const option = getOptionByValue(internalValue[0]);
      return option?.label || internalValue[0];
    }
    return t("filters.selectedCount", { count: internalValue.length });
  }, [internalValue, placeholder, getOptionByValue, t]);

  // Get displayed tags
  const displayedTags = useMemo(() => {
    const tags = internalValue.slice(0, maxDisplayedTags);
    const hasMore = internalValue.length > maxDisplayedTags;
    return {
      tags,
      hasMore,
      remainingCount: internalValue.length - maxDisplayedTags,
    };
  }, [internalValue, maxDisplayedTags]);

  return (
    <div className="space-y-3">
      {label && <Label className="font-medium text-sm">{label}</Label>}

      <div className="flex flex-col gap-3">
        {/* Operator selector */}
        {showOperator && (
          <Select
            disabled={disabled}
            onValueChange={(operatorValue) =>
              onOperatorChange(operatorValue as FilterOperators["multiOption"])
            }
            value={operator}
          >
            <SelectTrigger className="w-full">
              <SelectValue placeholder={t("filters.select_operator")} />
            </SelectTrigger>
            <SelectContent>
              {operators.map((op) => (
                <SelectItem key={op} value={op}>
                  {FILTER_OPERATORS_LABELS.multiOption[op]}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
        )}

        {/* Option picker */}
        {needsValue && (
          <div className="space-y-2">
            {inline ? (
              <div className="rounded-md border">
                <Command>
                  <CommandInput
                    onValueChange={setSearchTerm}
                    placeholder={t("filters.search", { filter: "options" })}
                    value={searchTerm}
                  />
                  <CommandList>
                    <CommandEmpty>{t("filters.noResults")}</CommandEmpty>
                    <CommandGroup>
                      {filteredOptions.map((option) => {
                        const isSelected = internalValue.includes(option.value);
                        return (
                          <CommandItem
                            key={option.value}
                            onSelect={() => handleOptionToggle(option.value)}
                            value={option.value}
                          >
                            <div className="flex flex-1 items-center gap-2">
                              {option.icon && (
                                <span className="flex h-4 w-4 flex-shrink-0 items-center justify-center">
                                  {typeof option.icon === "function" ? (
                                    <option.icon />
                                  ) : (
                                    option.icon
                                  )}
                                </span>
                              )}
                              <span className="flex-1">{option.label}</span>
                              {showCounts && option.count !== undefined && (
                                <Badge className="text-xs" variant="secondary">
                                  {option.count}
                                </Badge>
                              )}
                            </div>
                            <Check
                              className={cn(
                                "ml-auto h-4 w-4",
                                isSelected ? "opacity-100" : "opacity-0"
                              )}
                            />
                          </CommandItem>
                        );
                      })}
                    </CommandGroup>
                  </CommandList>
                </Command>
              </div>
            ) : (
              <Popover onOpenChange={setIsOpen} open={isOpen}>
                <PopoverTrigger>
                  <Button
                    aria-expanded={isOpen}
                    className="w-full justify-between"
                    disabled={disabled}
                    variant="outline"
                  >
                    <span className="truncate">{formatValueForDisplay()}</span>
                    <ChevronDown className="ml-2 h-4 w-4 shrink-0 opacity-50" />
                  </Button>
                </PopoverTrigger>
                <PopoverContent align="start" className="w-full p-0">
                  <Command>
                    <CommandInput
                      onValueChange={setSearchTerm}
                      placeholder={t("filters.search", { filter: "options" })}
                      value={searchTerm}
                    />
                    <CommandList>
                      <CommandEmpty>{t("filters.noResults")}</CommandEmpty>
                      <CommandGroup>
                        {/* Select/Clear all buttons */}
                        {filteredOptions.length > 1 && (
                          <>
                            <CommandItem
                              className="justify-center border-b"
                              onSelect={handleSelectAll}
                            >
                              Select All ({filteredOptions.length})
                            </CommandItem>
                            {internalValue.length > 0 && (
                              <CommandItem
                                className="mb-1 justify-center border-b"
                                onSelect={handleClearAll}
                              >
                                {t("filters.clear")}
                              </CommandItem>
                            )}
                          </>
                        )}

                        {filteredOptions.map((option) => {
                          const isSelected = internalValue.includes(
                            option.value
                          );

                          return (
                            <CommandItem
                              key={option.value}
                              onSelect={() => handleOptionToggle(option.value)}
                              value={option.value}
                            >
                              <div className="flex flex-1 items-center gap-2">
                                {option.icon && (
                                  <span className="flex h-4 w-4 flex-shrink-0 items-center justify-center">
                                    {typeof option.icon === "function" ? (
                                      <option.icon />
                                    ) : (
                                      option.icon
                                    )}
                                  </span>
                                )}
                                <span className="flex-1">{option.label}</span>
                                {showCounts && option.count !== undefined && (
                                  <Badge
                                    className="text-xs"
                                    variant="secondary"
                                  >
                                    {option.count}
                                  </Badge>
                                )}
                              </div>
                              <Check
                                className={cn(
                                  "ml-auto h-4 w-4",
                                  isSelected ? "opacity-100" : "opacity-0"
                                )}
                              />
                            </CommandItem>
                          );
                        })}
                      </CommandGroup>
                    </CommandList>
                  </Command>
                </PopoverContent>
              </Popover>
            )}

            {/* Selected tags display */}
            {internalValue.length > 0 && (
              <div className="flex flex-wrap gap-1">
                {displayedTags.tags.map((selectedValue) => {
                  const option = getOptionByValue(selectedValue);
                  return (
                    <Badge
                      className="text-xs"
                      key={selectedValue}
                      variant="secondary"
                    >
                      {option?.icon && (
                        <span className="mr-1 flex h-3 w-3 items-center justify-center">
                          {typeof option.icon === "function" ? (
                            <option.icon />
                          ) : (
                            option.icon
                          )}
                        </span>
                      )}
                      {option?.label || selectedValue}
                      <Button
                        className="ml-1 h-5 w-5 rounded-full p-0 outline-none ring-offset-background focus:ring-2 focus:ring-ring focus:ring-offset-2"
                        onClick={() => handleOptionToggle(selectedValue)}
                        onKeyDown={(e) => {
                          if (e.key === "Enter") {
                            handleOptionToggle(selectedValue);
                          }
                        }}
                        onMouseDown={(e) => {
                          e.preventDefault();
                          e.stopPropagation();
                        }}
                        size="icon"
                        type="button"
                        variant="ghost"
                      >
                        <X className="h-3 w-3 text-muted-foreground hover:text-foreground" />
                      </Button>
                    </Badge>
                  );
                })}

                {/* Show remaining count if there are more tags */}
                {displayedTags.hasMore && (
                  <Badge className="text-xs" variant="outline">
                    +{displayedTags.remainingCount}
                  </Badge>
                )}
              </div>
            )}
          </div>
        )}

        {/* Info text for operators that don't need values */}
        {!needsValue && (
          <div className="text-muted-foreground text-sm italic">
            {operator === "isEmpty"
              ? t("filters.operators.empty")
              : t("filters.operators.not_empty")}
          </div>
        )}
      </div>
    </div>
  );
}

/**
 * Compact multi-option filter for use in filter chips
 */
export function CompactMultiOptionFilter({
  value,
  operator,
  options,
  onValueChange,
  disabled = false,
  placeholder = "Select...",
  maxDisplayedTags = 2,
}: Pick<
  MultiOptionFilterProps,
  | "value"
  | "operator"
  | "options"
  | "onValueChange"
  | "disabled"
  | "placeholder"
  | "maxDisplayedTags"
>) {
  const [internalValue, setInternalValue] = useState(value);
  const [isOpen, setIsOpen] = useState(false);

  useEffect(() => {
    setInternalValue(value);
  }, [value]);

  const getOptionByValue = useCallback(
    (optionValue: string) => {
      return options.find((opt) => opt.value === optionValue);
    },
    [options]
  );

  const formatValueForDisplay = useCallback(() => {
    if (internalValue.length === 0) {
      return placeholder;
    }
    if (internalValue.length === 1) {
      const option = getOptionByValue(internalValue[0]);
      return option?.label || internalValue[0];
    }
    return `${internalValue.length} items`;
  }, [internalValue, placeholder, getOptionByValue]);

  const handleOptionToggle = useCallback(
    (optionValue: string) => {
      const newValue = internalValue.includes(optionValue)
        ? internalValue.filter((v) => v !== optionValue)
        : [...internalValue, optionValue];

      setInternalValue(newValue);
      onValueChange(newValue);
    },
    [internalValue, onValueChange]
  );

  const needsValue = !["isEmpty", "isNotEmpty"].includes(operator);

  if (!needsValue) {
    return (
      <span className="text-muted-foreground text-xs">
        {operator === "isEmpty" ? "is empty" : "is not empty"}
      </span>
    );
  }

  return (
    <div className="flex flex-col gap-1">
      <Popover onOpenChange={setIsOpen} open={isOpen}>
        <PopoverTrigger>
          <Button
            className="h-6 max-w-32 justify-between px-2 font-normal text-xs"
            disabled={disabled}
            size="sm"
            variant="ghost"
          >
            <span className="truncate">{formatValueForDisplay()}</span>
            <ChevronDown className="ml-1 h-3 w-3 shrink-0 opacity-50" />
          </Button>
        </PopoverTrigger>
        <PopoverContent align="start" className="w-48 p-0">
          <Command>
            <CommandInput placeholder="Search..." />
            <CommandList>
              <CommandEmpty>No options found.</CommandEmpty>
              <CommandGroup>
                {options.map((option) => {
                  const isSelected = internalValue.includes(option.value);

                  return (
                    <CommandItem
                      key={option.value}
                      onSelect={() => handleOptionToggle(option.value)}
                      value={option.value}
                    >
                      <div className="flex flex-1 items-center gap-2">
                        {option.icon && (
                          <span className="flex h-3 w-3 flex-shrink-0 items-center justify-center">
                            {typeof option.icon === "function" ? (
                              <option.icon />
                            ) : (
                              option.icon
                            )}
                          </span>
                        )}
                        <span className="flex-1 text-xs">{option.label}</span>
                      </div>
                      <Check
                        className={cn(
                          "ml-auto h-3 w-3",
                          isSelected ? "opacity-100" : "opacity-0"
                        )}
                      />
                    </CommandItem>
                  );
                })}
              </CommandGroup>
            </CommandList>
          </Command>
        </PopoverContent>
      </Popover>

      {/* Compact tags display */}
      {internalValue.length > 0 && (
        <div className="flex flex-wrap gap-1">
          {internalValue.slice(0, maxDisplayedTags).map((selectedValue) => {
            const option = getOptionByValue(selectedValue);
            return (
              <Badge
                className="h-4 px-1 text-xs"
                key={selectedValue}
                variant="secondary"
              >
                {option?.label || selectedValue}
                <Button
                  className="ml-1 h-4 w-4 p-0 hover:bg-destructive hover:text-destructive-foreground"
                  onClick={(e) => {
                    e.preventDefault();
                    e.stopPropagation();
                    handleOptionToggle(selectedValue);
                  }}
                  size="icon"
                  type="button"
                  variant="ghost"
                >
                  <X className="h-2 w-2" />
                </Button>
              </Badge>
            );
          })}
          {internalValue.length > maxDisplayedTags && (
            <Badge className="h-4 px-1 text-xs" variant="outline">
              +{internalValue.length - maxDisplayedTags}
            </Badge>
          )}
        </div>
      )}
    </div>
  );
}

/**
 * Number filter component
 * Provides filtering for numeric columns with various numeric operators and range slider
 */
"use client";

import { useCallback, useEffect, useState } from "react";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Slider } from "@/components/ui/slider";
import { useTranslations } from "../../providers/table-provider";
import type { FilterOperators } from "../../types/filter-types";
import {
  DEFAULT_OPERATORS,
  FILTER_OPERATORS_LABELS,
} from "../../types/filter-types";

export interface NumberFilterProps {
  /** Current filter value - single number or [min, max] for between */
  value: number | [number, number];
  /** Current operator */
  operator: FilterOperators["number"];
  /** Available operators (defaults to all number operators) */
  operators?: readonly FilterOperators["number"][];
  /** Minimum value for slider/validation */
  min?: number;
  /** Maximum value for slider/validation */
  max?: number;
  /** Step size for slider */
  step?: number;
  /** Placeholder text for inputs */
  placeholder?: string;
  /** Whether the filter is disabled */
  disabled?: boolean;
  /** Callback when the value changes */
  onValueChange: (value: number | [number, number]) => void;
  /** Callback when the operator changes */
  onOperatorChange: (operator: FilterOperators["number"]) => void;
  /** Optional label */
  label?: string;
  /** Whether to show the operator selector */
  showOperator?: boolean;
  /** Whether to show slider for range operations */
  showSlider?: boolean;
}

/**
 * Number filter component with operator selection and numeric input/slider
 */
export function NumberFilter({
  value,
  operator,
  operators = DEFAULT_OPERATORS.number,
  min = 0,
  max = 100,
  step = 1,
  placeholder = "Enter number...",
  disabled = false,
  onValueChange,
  onOperatorChange,
  label,
  showOperator = true,
  showSlider = true,
}: NumberFilterProps) {
  const { t } = useTranslations();
  const [internalValue, setInternalValue] = useState(value);

  // Sync internal value with prop
  useEffect(() => {
    setInternalValue(value);
  }, [value]);

  // Handle value change with debouncing
  const handleValueChange = useCallback(
    (newValue: number | [number, number]) => {
      setInternalValue(newValue);

      // Debounce the callback
      const timeoutId = setTimeout(() => {
        onValueChange(newValue);
      }, 300);

      return () => clearTimeout(timeoutId);
    },
    [onValueChange]
  );

  // Handle immediate value change
  const handleImmediateChange = useCallback(
    (newValue: number | [number, number]) => {
      setInternalValue(newValue);
      onValueChange(newValue);
    },
    [onValueChange]
  );

  // Check if this operator needs a value input
  const needsValue = !["isEmpty", "isNotEmpty"].includes(operator);
  const isBetween = operator === "between";
  const currentSingleValue = Array.isArray(internalValue)
    ? internalValue[0]
    : internalValue;
  const currentRangeValue = Array.isArray(internalValue)
    ? internalValue
    : [min, max];

  // Handle single number input change
  const handleSingleInputChange = useCallback(
    (inputValue: string) => {
      const numValue = Number.parseFloat(inputValue);
      if (!Number.isNaN(numValue)) {
        handleValueChange(numValue);
      }
    },
    [handleValueChange]
  );

  // Handle range input changes
  const handleRangeMinChange = useCallback(
    (inputValue: string) => {
      const numValue = Number.parseFloat(inputValue);
      if (!Number.isNaN(numValue)) {
        const [, maxVal] = currentRangeValue;
        handleValueChange([numValue, maxVal]);
      }
    },
    [currentRangeValue, handleValueChange]
  );

  const handleRangeMaxChange = useCallback(
    (inputValue: string) => {
      const numValue = Number.parseFloat(inputValue);
      if (!Number.isNaN(numValue)) {
        const [minVal] = currentRangeValue;
        handleValueChange([minVal, numValue]);
      }
    },
    [currentRangeValue, handleValueChange]
  );

  // Handle slider change
  const handleSliderChange = useCallback(
    (values: number[]) => {
      if (isBetween) {
        handleImmediateChange([values[0], values[1]]);
      } else {
        handleImmediateChange(values[0]);
      }
    },
    [isBetween, handleImmediateChange]
  );

  return (
    <div className="space-y-3">
      {label && <Label className="font-medium text-sm">{label}</Label>}

      <div className="flex flex-col gap-3">
        {/* Operator selector */}
        {showOperator && (
          <Select
            disabled={disabled}
            onValueChange={(operatorValue) =>
              onOperatorChange(operatorValue as FilterOperators["number"])
            }
            value={operator}
          >
            <SelectTrigger className="w-full">
              <SelectValue placeholder={t("filters.select_operator")} />
            </SelectTrigger>
            <SelectContent>
              {operators.map((op) => (
                <SelectItem key={op} value={op}>
                  {FILTER_OPERATORS_LABELS.number[op]}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
        )}

        {/* Value inputs */}
        {needsValue && (
          <div className="space-y-2">
            {isBetween ? (
              <>
                {/* Range inputs */}
                <div className="flex items-center gap-2">
                  <Input
                    className="flex-1"
                    disabled={disabled}
                    max={max}
                    min={min}
                    onChange={(e) => handleRangeMinChange(e.target.value)}
                    placeholder={t("filters.value")}
                    step={step}
                    type="number"
                    value={currentRangeValue[0]}
                  />
                  <span className="text-muted-foreground text-sm">to</span>
                  <Input
                    className="flex-1"
                    disabled={disabled}
                    max={max}
                    min={min}
                    onChange={(e) => handleRangeMaxChange(e.target.value)}
                    placeholder={t("filters.value_to")}
                    step={step}
                    type="number"
                    value={currentRangeValue[1]}
                  />
                </div>

                {/* Range slider */}
                {showSlider && (
                  <div className="px-2">
                    <Slider
                      className="w-full"
                      disabled={disabled}
                      max={max}
                      min={min}
                      onValueChange={(value) =>
                        handleSliderChange(
                          Array.isArray(value) ? [...value] : [value as number]
                        )
                      }
                      step={step}
                      value={currentRangeValue}
                    />
                    <div className="mt-1 flex justify-between text-muted-foreground text-xs">
                      <span>{min}</span>
                      <span>{max}</span>
                    </div>
                  </div>
                )}
              </>
            ) : (
              <>
                {/* Single number input */}
                <Input
                  className="w-full"
                  disabled={disabled}
                  max={max}
                  min={min}
                  onChange={(e) => handleSingleInputChange(e.target.value)}
                  placeholder={placeholder}
                  step={step}
                  type="number"
                  value={currentSingleValue || ""}
                />

                {/* Single value slider */}
                {showSlider && (
                  <div className="px-2">
                    <Slider
                      className="w-full"
                      disabled={disabled}
                      max={max}
                      min={min}
                      onValueChange={(value) =>
                        handleSliderChange(
                          Array.isArray(value) ? [...value] : [value as number]
                        )
                      }
                      step={step}
                      value={[currentSingleValue || min]}
                    />
                    <div className="mt-1 flex justify-between text-muted-foreground text-xs">
                      <span>{min}</span>
                      <span>{max}</span>
                    </div>
                  </div>
                )}
              </>
            )}
          </div>
        )}

        {/* Info text for operators that don't need values */}
        {!needsValue && (
          <div className="text-muted-foreground text-sm italic">
            {operator === "isEmpty"
              ? t("filters.operators.empty")
              : t("filters.operators.not_empty")}
          </div>
        )}
      </div>
    </div>
  );
}

/**
 * Compact number filter for use in filter chips
 */
export function CompactNumberFilter({
  value,
  operator,
  onValueChange,
  placeholder = "0",
  disabled = false,
}: Pick<
  NumberFilterProps,
  "value" | "operator" | "onValueChange" | "placeholder" | "disabled"
>) {
  const [internalValue, setInternalValue] = useState(value);

  useEffect(() => {
    setInternalValue(value);
  }, [value]);

  const handleChange = useCallback(
    (newValue: number | [number, number]) => {
      setInternalValue(newValue);
      const timeoutId = setTimeout(() => {
        onValueChange(newValue);
      }, 300);
      return () => clearTimeout(timeoutId);
    },
    [onValueChange]
  );

  const needsValue = !["isEmpty", "isNotEmpty"].includes(operator);
  const isBetween = operator === "between";

  if (!needsValue) {
    return (
      <span className="text-muted-foreground text-xs">
        {operator === "isEmpty" ? "is empty" : "is not empty"}
      </span>
    );
  }

  if (isBetween && Array.isArray(internalValue)) {
    return (
      <div className="flex items-center gap-1">
        <Input
          className="h-6 w-16 text-xs"
          disabled={disabled}
          onChange={(e) => {
            const val = Number.parseFloat(e.target.value);
            if (!Number.isNaN(val)) {
              handleChange([val, internalValue[1]]);
            }
          }}
          type="number"
          value={internalValue[0]}
        />
        <span className="text-xs">-</span>
        <Input
          className="h-6 w-16 text-xs"
          disabled={disabled}
          onChange={(e) => {
            const val = Number.parseFloat(e.target.value);
            if (!Number.isNaN(val)) {
              handleChange([internalValue[0], val]);
            }
          }}
          type="number"
          value={internalValue[1]}
        />
      </div>
    );
  }

  const singleValue = Array.isArray(internalValue)
    ? internalValue[0]
    : internalValue;

  return (
    <Input
      className="h-6 w-20 text-xs"
      disabled={disabled}
      onChange={(e) => {
        const val = Number.parseFloat(e.target.value);
        if (!Number.isNaN(val)) {
          handleChange(val);
        }
      }}
      placeholder={placeholder}
      type="number"
      value={singleValue || ""}
    />
  );
}

/**
 * Option filter component
