import { Label } from "@/components/ui/label";
import { Popover, PopoverContent, PopoverTrigger } from "@/components/ui/popover";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { useTranslations } from "../../providers/table-provider";
import type { ColumnOption, FilterOperators } from "../../types/filter-types";
import {
  DEFAULT_OPERATORS,
  FILTER_OPERATORS_LABELS,
} from "../../types/filter-types";

export interface OptionFilterProps {
  /** Current filter value - single value or array for isAnyOf/isNoneOf */
  value: string | string[];
  /** Current operator */
  operator: FilterOperators["option"];
  /** Available operators (defaults to all option operators) */
  operators?: readonly FilterOperators["option"][];
  /** Available options */
  options: ColumnOption[];
  /** Whether the filter is disabled */
  disabled?: boolean;
  /** Callback when the value changes */
  onValueChange: (value: string | string[]) => void;
  /** Callback when the operator changes */
  onOperatorChange: (operator: FilterOperators["option"]) => void;
  /** Optional label */
  label?: string;
  /** Whether to show the operator selector */
  showOperator?: boolean;
  /** Whether to show faceted counts */
  showCounts?: boolean;
  /** Placeholder text */
  placeholder?: string;
  /** Render picker inline instead of popover */
  inline?: boolean;
}

/**
 * Option filter component with operator selection and option picker
 */
export function OptionFilter({
  value,
  operator,
  operators = DEFAULT_OPERATORS.option,
  options,
  disabled = false,
  onValueChange,
  onOperatorChange,
  label,
  showOperator = true,
  showCounts = true,
  placeholder = "Select option...",
  inline = false,
}: OptionFilterProps) {
  const { t } = useTranslations();
  const [internalValue, setInternalValue] = useState(value);
  const [isOpen, setIsOpen] = useState(false);
  const [searchTerm, setSearchTerm] = useState("");

  // Sync internal value with prop
  useEffect(() => {
    setInternalValue(value);
  }, [value]);

  // Handle value change
  const handleValueChange = useCallback(
    (newValue: string | string[]) => {
      setInternalValue(newValue);
      onValueChange(newValue);
    },
    [onValueChange]
  );

  // Check if this operator needs a value input
  const needsValue = !["isEmpty", "isNotEmpty"].includes(operator);
  const isMultiple = ["isAnyOf", "isNoneOf"].includes(operator);
  const currentSingleValue = Array.isArray(internalValue)
    ? internalValue[0]
    : internalValue;
  let currentMultipleValue: string[];
  if (Array.isArray(internalValue)) {
    currentMultipleValue = internalValue;
  } else if (internalValue) {
    currentMultipleValue = [internalValue];
  } else {
    currentMultipleValue = [];
  }

  // Filter options based on search term
  const filteredOptions = useMemo(() => {
    if (!searchTerm) {
      return options;
    }
    return options.filter(
      (option) =>
        option.label.toLowerCase().includes(searchTerm.toLowerCase()) ||
        option.value.toLowerCase().includes(searchTerm.toLowerCase())
    );
  }, [options, searchTerm]);

  // Handle single option selection
  const handleSingleOptionSelect = useCallback(
    (optionValue: string) => {
      handleValueChange(optionValue);
      setIsOpen(false);
    },
    [handleValueChange]
  );

  // Handle multiple option selection
  const handleMultipleOptionToggle = useCallback(
    (optionValue: string) => {
      const newValue = currentMultipleValue.includes(optionValue)
        ? currentMultipleValue.filter((v) => v !== optionValue)
        : [...currentMultipleValue, optionValue];
      handleValueChange(newValue);
    },
    [currentMultipleValue, handleValueChange]
  );

  // Get option by value
  const getOptionByValue = useCallback(
    (optionValue: string) => {
      return options.find((opt) => opt.value === optionValue);
    },
    [options]
  );

  // Format selected values for display
  const formatValueForDisplay = useCallback(() => {
    if (isMultiple) {
      if (currentMultipleValue.length === 0) {
        return placeholder;
      }
      if (currentMultipleValue.length === 1) {
        const option = getOptionByValue(currentMultipleValue[0]);
        return option?.label || currentMultipleValue[0];
      }
      return `${currentMultipleValue.length} selected`;
    }
    if (!currentSingleValue) {
      return placeholder;
    }
    const option = getOptionByValue(currentSingleValue);
    return option?.label || currentSingleValue;
  }, [
    isMultiple,
    currentMultipleValue,
    currentSingleValue,
    placeholder,
    getOptionByValue,
  ]);

  return (
    <div className="space-y-3">
      {label && <Label className="font-medium text-sm">{label}</Label>}

      <div className="flex flex-col gap-3">
        {/* Operator selector */}
        {showOperator && (
          <Select
            disabled={disabled}
            onValueChange={(operatorValue) =>
              onOperatorChange(operatorValue as FilterOperators["option"])
            }
            value={operator}
          >
            <SelectTrigger className="w-full">
              <SelectValue placeholder={t("filters.select_operator")} />
            </SelectTrigger>
            <SelectContent>
              {operators.map((op) => (
                <SelectItem key={op} value={op}>
                  {FILTER_OPERATORS_LABELS.option[op]}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
        )}

        {/* Option picker */}
        {needsValue && (
          <div className="space-y-2">
            {inline ? (
              <div className="rounded-md border">
                <Command>
                  <CommandInput
                    onValueChange={setSearchTerm}
                    placeholder={t("filters.search", { filter: "options" })}
                    value={searchTerm}
                  />
                  <CommandList>
                    <CommandEmpty>{t("filters.noResults")}</CommandEmpty>
                    <CommandGroup>
                      {filteredOptions.map((option) => {
                        const isSelected = isMultiple
                          ? currentMultipleValue.includes(option.value)
                          : currentSingleValue === option.value;

                        return (
                          <CommandItem
                            key={option.value}
                            onSelect={() => {
                              if (isMultiple) {
                                handleMultipleOptionToggle(option.value);
                              } else {
                                handleSingleOptionSelect(option.value);
                              }
                            }}
                            value={option.value}
                          >
                            <div className="flex flex-1 items-center gap-2">
                              {option.icon && (
                                <span className="flex h-4 w-4 flex-shrink-0 items-center justify-center">
                                  {typeof option.icon === "function" ? (
                                    <option.icon />
                                  ) : (
                                    option.icon
                                  )}
                                </span>
                              )}
                              <span className="flex-1">{option.label}</span>
                              {showCounts && option.count !== undefined && (
                                <Badge className="text-xs" variant="secondary">
                                  {option.count}
                                </Badge>
                              )}
                            </div>
                            <Check
                              className={cn(
                                "ml-auto h-4 w-4",
                                isSelected ? "opacity-100" : "opacity-0"
                              )}
                            />
                          </CommandItem>
                        );
                      })}
                    </CommandGroup>
                  </CommandList>
                </Command>
              </div>
            ) : (
              <Popover onOpenChange={setIsOpen} open={isOpen}>
                <PopoverTrigger>
                  <Button
                    aria-expanded={isOpen}
                    className="w-full justify-between"
                    disabled={disabled}
                    variant="outline"
                  >
                    <span className="truncate">{formatValueForDisplay()}</span>
                    <ChevronDown className="ml-2 h-4 w-4 shrink-0 opacity-50" />
                  </Button>
                </PopoverTrigger>
                <PopoverContent align="start" className="w-full p-0">
                  <Command>
                    <CommandInput
                      onValueChange={setSearchTerm}
                      placeholder={t("filters.search", { filter: "options" })}
                      value={searchTerm}
                    />
                    <CommandList>
                      <CommandEmpty>{t("filters.noResults")}</CommandEmpty>
                      <CommandGroup>
                        {filteredOptions.map((option) => {
                          const isSelected = isMultiple
                            ? currentMultipleValue.includes(option.value)
                            : currentSingleValue === option.value;

                          return (
                            <CommandItem
                              key={option.value}
                              onSelect={() => {
                                if (isMultiple) {
                                  handleMultipleOptionToggle(option.value);
                                } else {
                                  handleSingleOptionSelect(option.value);
                                }
                              }}
                              value={option.value}
                            >
                              <div className="flex flex-1 items-center gap-2">
                                {option.icon && (
                                  <span className="flex h-4 w-4 flex-shrink-0 items-center justify-center">
                                    {typeof option.icon === "function" ? (
                                      <option.icon />
                                    ) : (
                                      option.icon
                                    )}
                                  </span>
                                )}
                                <span className="flex-1">{option.label}</span>
                                {showCounts && option.count !== undefined && (
                                  <Badge
                                    className="text-xs"
                                    variant="secondary"
                                  >
                                    {option.count}
                                  </Badge>
                                )}
                              </div>
                              <Check
                                className={cn(
                                  "ml-auto h-4 w-4",
                                  isSelected ? "opacity-100" : "opacity-0"
                                )}
                              />
                            </CommandItem>
                          );
                        })}
                      </CommandGroup>
                    </CommandList>
                  </Command>
                </PopoverContent>
              </Popover>
            )}

            {/* Selected values display for multiple selection */}
            {isMultiple && currentMultipleValue.length > 0 && (
              <div className="flex flex-wrap gap-1">
                {currentMultipleValue.map((selectedValue) => {
                  const option = getOptionByValue(selectedValue);
                  return (
                    <Badge
                      className="text-xs"
                      key={selectedValue}
                      variant="secondary"
                    >
                      {option?.icon && (
                        <span className="mr-1 flex h-3 w-3 items-center justify-center">
                          {typeof option.icon === "function" ? (
                            <option.icon />
                          ) : (
                            option.icon
                          )}
                        </span>
                      )}
                      {option?.label || selectedValue}
                      <Button
                        className="ml-1 h-5 w-5 rounded-full p-0 outline-none ring-offset-background focus:ring-2 focus:ring-ring focus:ring-offset-2"
                        onClick={() =>
                          handleMultipleOptionToggle(selectedValue)
                        }
                        onKeyDown={(e) => {
                          if (e.key === "Enter") {
                            handleMultipleOptionToggle(selectedValue);
                          }
                        }}
                        onMouseDown={(e) => {
                          e.preventDefault();
                          e.stopPropagation();
                        }}
                        size="icon"
                        type="button"
                        variant="ghost"
                      >
                        <X className="h-3 w-3 text-muted-foreground hover:text-foreground" />
                      </Button>
                    </Badge>
                  );
                })}
              </div>
            )}
          </div>
        )}

        {/* Info text for operators that don't need values */}
        {!needsValue && (
          <div className="text-muted-foreground text-sm italic">
            This filter will show rows where the field{" "}
            {operator === "isEmpty" ? "is empty" : "is not empty"}.
          </div>
        )}
      </div>
    </div>
  );
}

/**
 * Compact option filter for use in filter chips
 */
export function CompactOptionFilter({
  value,
  operator,
  options,
  onValueChange,
  disabled = false,
  placeholder = "Select...",
}: Pick<
  OptionFilterProps,
  | "value"
  | "operator"
  | "options"
  | "onValueChange"
  | "disabled"
  | "placeholder"
>) {
  const { t } = useTranslations();
  const [internalValue, setInternalValue] = useState(value);
  const [isOpen, setIsOpen] = useState(false);

  useEffect(() => {
    setInternalValue(value);
  }, [value]);

  const handleValueChange = useCallback(
    (newValue: string | string[]) => {
      setInternalValue(newValue);
      onValueChange(newValue);
    },
    [onValueChange]
  );

  const getOptionByValue = useCallback(
    (optionValue: string) => {
      return options.find((opt) => opt.value === optionValue);
    },
    [options]
  );

  const isMultiple = ["isAnyOf", "isNoneOf"].includes(operator);
  const currentSingleValue = Array.isArray(internalValue)
    ? internalValue[0]
    : internalValue;
  let currentMultipleValue: string[];
  if (Array.isArray(internalValue)) {
    currentMultipleValue = internalValue;
  } else if (internalValue) {
    currentMultipleValue = [internalValue];
  } else {
    currentMultipleValue = [];
  }

  const formatValueForDisplay = useCallback(() => {
    if (isMultiple) {
      if (currentMultipleValue.length === 0) {
        return placeholder;
      }
      if (currentMultipleValue.length === 1) {
        const option = getOptionByValue(currentMultipleValue[0]);
        return option?.label || currentMultipleValue[0];
      }
      return t("filters.selectedCount", { count: currentMultipleValue.length });
    }
    if (!currentSingleValue) {
      return placeholder;
    }
    const option = getOptionByValue(currentSingleValue);
    return option?.label || currentSingleValue;
  }, [
    isMultiple,
    currentMultipleValue,
    currentSingleValue,
    placeholder,
    getOptionByValue,
    t,
  ]);

  const needsValue = !["isEmpty", "isNotEmpty"].includes(operator);

  if (!needsValue) {
    return (
      <span className="text-muted-foreground text-xs">
        {operator === "isEmpty"
          ? t("filters.operators.empty")
          : t("filters.operators.not_empty")}
      </span>
    );
  }

  return (
    <Popover onOpenChange={setIsOpen} open={isOpen}>
      <PopoverTrigger>
        <Button
          className="h-6 max-w-32 justify-between px-2 font-normal text-xs"
          disabled={disabled}
          size="sm"
          variant="ghost"
        >
          <span className="truncate">{formatValueForDisplay()}</span>
          <ChevronDown className="ml-1 h-3 w-3 shrink-0 opacity-50" />
        </Button>
      </PopoverTrigger>
      <PopoverContent align="start" className="w-48 p-0">
        <Command>
          <CommandInput
            placeholder={t("filters.search", { filter: "options" })}
          />
          <CommandList>
            <CommandEmpty>{t("filters.noResults")}</CommandEmpty>
            <CommandGroup>
              {options.map((option) => {
                const isSelected = isMultiple
                  ? currentMultipleValue.includes(option.value)
                  : currentSingleValue === option.value;

                return (
                  <CommandItem
                    key={option.value}
                    onSelect={() => {
                      if (isMultiple) {
                        const newValue = currentMultipleValue.includes(
                          option.value
                        )
                          ? currentMultipleValue.filter(
                              (v) => v !== option.value
                            )
                          : [...currentMultipleValue, option.value];
                        handleValueChange(newValue);
                      } else {
                        handleValueChange(option.value);
                        setIsOpen(false);
                      }
                    }}
                    value={option.value}
                  >
                    <div className="flex flex-1 items-center gap-2">
                      {option.icon && (
                        <span className="flex h-3 w-3 flex-shrink-0 items-center justify-center">
                          {typeof option.icon === "function" ? (
                            <option.icon />
                          ) : (
                            option.icon
                          )}
                        </span>
                      )}
                      <span className="flex-1 text-xs">{option.label}</span>
                    </div>
                    <Check
                      className={cn(
                        "ml-auto h-3 w-3",
                        isSelected ? "opacity-100" : "opacity-0"
                      )}
                    />
                  </CommandItem>
                );
              })}
            </CommandGroup>
          </CommandList>
        </Command>
      </PopoverContent>
    </Popover>
  );
}

/**
 * Text filter component
 * Provides filtering for text-based columns with various text operators
 */
"use client";

import { useCallback, useEffect, useState } from "react";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { useTranslations } from "../../providers/table-provider";
import type { FilterOperators } from "../../types/filter-types";
import {
  DEFAULT_OPERATORS,
  FILTER_OPERATORS_LABELS,
} from "../../types/filter-types";

export interface TextFilterProps {
  /** Current filter value */
  value: string;
  /** Current operator */
  operator: FilterOperators["text"];
  /** Available operators (defaults to all text operators) */
  operators?: readonly FilterOperators["text"][];
  /** Placeholder text */
  placeholder?: string;
  /** Whether the filter is disabled */
  disabled?: boolean;
  /** Callback when the value changes */
  onValueChange: (value: string) => void;
  /** Callback when the operator changes */
  onOperatorChange: (operator: FilterOperators["text"]) => void;
  /** Optional label */
  label?: string;
  /** Whether to show the operator selector */
  showOperator?: boolean;
  /** Debounce delay for value changes (ms). 0 = no debounce */
  debounceMs?: number;
}

/**
 * Text filter component with operator selection and text input
 */
export function TextFilter({
  value,
  operator,
  operators = DEFAULT_OPERATORS.text,
  placeholder = "Enter text...",
  disabled = false,
  onValueChange,
  onOperatorChange,
  label,
  showOperator = true,
  debounceMs = 300,
}: TextFilterProps) {
  const { t } = useTranslations();
  const [internalValue, setInternalValue] = useState(value);

  // Sync internal value with prop
  useEffect(() => {
    setInternalValue(value);
  }, [value]);

  // Handle value change with debouncing
  const handleValueChange = useCallback(
    (newValue: string) => {
      setInternalValue(newValue);
      if (debounceMs <= 0) {
        onValueChange(newValue);
        return () => {
          /* no-op cleanup */
        };
      }
      const timeoutId = setTimeout(() => {
        onValueChange(newValue);
      }, debounceMs);
      return () => clearTimeout(timeoutId);
    },
    [onValueChange, debounceMs]
  );

  // Handle immediate value change for certain operators
  const handleImmediateChange = useCallback(
    (newValue: string) => {
      setInternalValue(newValue);
      onValueChange(newValue);
    },
    [onValueChange]
  );

  // Check if this operator needs a value input
  const needsValue = !["isEmpty", "isNotEmpty"].includes(operator);

  return (
    <div className="space-y-3">
      {label && <Label className="font-medium text-sm">{label}</Label>}

      <div className="flex flex-col gap-2">
        {/* Operator selector */}
        {showOperator && (
          <Select
            disabled={disabled}
            onValueChange={(operatorValue) =>
              onOperatorChange(operatorValue as FilterOperators["text"])
            }
            value={operator}
          >
            <SelectTrigger className="w-full">
              <SelectValue placeholder={t("filters.select_operator")} />
            </SelectTrigger>
            <SelectContent>
              {operators.map((op) => (
                <SelectItem key={op} value={op}>
                  {FILTER_OPERATORS_LABELS.text[op]}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
        )}

        {/* Value input - only show if operator needs a value */}
        {needsValue && (
          <Input
            className="w-full"
            disabled={disabled}
            onBlur={(e) => handleImmediateChange(e.target.value)}
            onChange={(e) => handleValueChange(e.target.value)}
            placeholder={placeholder}
            type="text"
            value={internalValue}
          />
        )}

        {/* Info text for operators that don't need values */}
        {!needsValue && (
          <div className="text-muted-foreground text-sm italic">
            {operator === "isEmpty"
              ? t("filters.operators.empty")
              : t("filters.operators.not_empty")}
          </div>
        )}
      </div>
    </div>
  );
}

/**
 * Compact text filter for use in filter chips
 */
export function CompactTextFilter({
  value,
  operator,
  onValueChange,
  placeholder = "Type...",
  disabled = false,
}: Pick<
  TextFilterProps,
  "value" | "operator" | "onValueChange" | "placeholder" | "disabled"
>) {
  const [internalValue, setInternalValue] = useState(value);

  useEffect(() => {
    setInternalValue(value);
  }, [value]);

  const handleChange = useCallback(
    (newValue: string) => {
      setInternalValue(newValue);
      const timeoutId = setTimeout(() => {
        onValueChange(newValue);
      }, 300);
      return () => clearTimeout(timeoutId);
    },
    [onValueChange]
  );

  const needsValue = !["isEmpty", "isNotEmpty"].includes(operator);

  if (!needsValue) {
    return (
      <span className="text-muted-foreground text-xs">
        {operator === "isEmpty" ? "is empty" : "is not empty"}
      </span>
    );
  }

  return (
    <Input
      className="h-6 text-xs"
      disabled={disabled}
      onChange={(e) => handleChange(e.target.value)}
      placeholder={placeholder}
      type="text"
      value={internalValue}
    />
  );
}

import { atom } from "jotai";

export interface TranslationConfig {
  keys: {
    cancel: string;
    categories: {
      current: string;
      empty: string;
      newPlaceholder: string;
    };
    create: string;
    createForm: {
      description: string;
      title: string;
    };
    error: string;
    errorDescription: string;
    submit: string;
    success: string;
    successDescription: string;
  };
  namespace: string;
}

export const translationConfigAtom = atom<TranslationConfig>({
  keys: {
    cancel: "cancel",
    categories: {
      current: "categories.current",
      empty: "categories.empty",
      newPlaceholder: "categories.new_placeholder",
    },
    create: "create",
    createForm: {
      description: "create_form.description",
      title: "create_form.title",
    },
    error: "error",
    errorDescription: "error_description",
    submit: "submit",
    success: "success",
    successDescription: "success_description",
  },
  namespace: "common",
});

/**
 * Atoms for the catalogue form
 * These atoms manage the state of the catalogue form drawer
 */
import { atom } from "jotai";

/**
 * Interface for the catalogue form state
 */
export interface CatalogueFormState<TData = Record<string, unknown>> {
  /**
   * Type of form to use (corresponds to a key in the form catalogue)
   */
  formType?: string;

  /**
   * Initial data for the form (used for update operations)
   */
  initialData?: TData;

  /**
   * Whether the form drawer is open
   */
  isOpen: boolean;

  /**
   * Mode of the form (create or update)
   */
  mode: "create" | "update";

  /**
   * Callback when the form is submitted successfully
   */
  onSuccess?: (data: TData) => void;

  /**
   * Table ID associated with the form
   */
  tableId?: string;
}

/**
 * Default state for the catalogue form
 */
const defaultState: CatalogueFormState = {
  formType: undefined,
  initialData: undefined,
  isOpen: false,
  mode: "create",
  onSuccess: undefined,
  tableId: undefined,
};

/**
 * Atom for the catalogue form state
 */
export const catalogueFormAtom = atom<CatalogueFormState>(defaultState);

/**
 * Atom to track whether a form has been submitted
 * This prevents showing success notifications except after actual form submission
 */
export const formSubmittedAtom = atom<boolean>(false);

/**
 * Form renderer components
 */
export const FormRenderer = {
  CONTAINER: "container",
  NONE: "none",
  TOOLBAR: "toolbar",
} as const;

export type FormRenderer = (typeof FormRenderer)[keyof typeof FormRenderer];

/**
 * Atom to track which component is responsible for rendering the form
 * This helps prevent multiple components from rendering the same form
 */
export const formRendererAtom = atom<FormRenderer>(FormRenderer.NONE);

/**
 * Open the form in create mode
 */
export const openCreateForm = <TData = Record<string, unknown>>(
  formType: string,
  tableId: string,
  onSuccess?: (data: TData) => void
): CatalogueFormState<TData> => ({
  formType,
  initialData: undefined,
  isOpen: true,
  mode: "create",
  onSuccess,
  tableId,
});

/**
 * Open the form in update mode
 */
export const openUpdateForm = <TData = Record<string, unknown>>(
  formType: string,
  tableId: string,
  initialData: TData,
  onSuccess?: (data: TData) => void
): CatalogueFormState<TData> => ({
  formType,
  initialData,
  isOpen: true,
  mode: "update",
  onSuccess,
  tableId,
});

/**
 * Close the form
 */
export const closeForm = <
  TData = Record<string, unknown>,
>(): CatalogueFormState<TData> => ({
  formType: undefined,
  initialData: undefined,
  isOpen: false,
  mode: "create",
  onSuccess: undefined,
  tableId: undefined,
});

/**
 * Handle form open state changes
 * This function updates the form state based on the open state
 */
export const handleFormOpenChange = <TData = Record<string, unknown>>(
  open: boolean,
  currentState: CatalogueFormState<TData>
): CatalogueFormState<TData> => {
  // If the state is already what we want, return the current state to prevent unnecessary re-renders
  if (currentState.isOpen === open) {
    return currentState;
  }

  // If opening, just update the isOpen state and keep everything else
  if (open) {
    return {
      ...currentState,
      isOpen: true,
    };
  }

  // If closing, only reset the form if it was actually open
  // This prevents unnecessary state changes
  if (currentState.isOpen) {
    return {
      formType: undefined,
      initialData: undefined,
      isOpen: false,
      mode: "create",
      onSuccess: undefined,
      tableId: undefined,
    };
  }

  // Form was already closed, return current state
  return currentState;
};

/**
 * CatalogueFormContainer component
 * This component renders the CatalogueForm and listens to the catalogueFormAtom
 * It will automatically show/hide the form based on the atom state
 */
"use client";

import { useAtomValue } from "jotai";
import { lazy, Suspense } from "react";

import { catalogueFormAtom } from "./atoms/catalogue-form-atoms";

// Dynamically import the CatalogueForm component using React.lazy
const CatalogueForm = lazy(() =>
  import("./catalogue-form").then((mod) => ({ default: mod.CatalogueForm }))
);

/**
 * CatalogueFormContainer component
 * This component is responsible for rendering the CatalogueForm
 * and listening to the catalogueFormAtom
 */
export function CatalogueFormContainer() {
  // Get the form state from the atom (read-only to prevent conflicts)
  const formState = useAtomValue(catalogueFormAtom);

  // Extract the necessary values from the form state
  const { formType, initialData, mode, onSuccess, tableId } = formState;

  // If no form type is provided, don't render anything
  if (!formType) {
    return null;
  }

  // Render the CatalogueForm with the values from the atom
  // Let CatalogueForm handle all state management internally
  return (
    <Suspense fallback={null}>
      <CatalogueForm
        formType={formType}
        initialData={initialData}
        mode={mode}
        onSuccess={onSuccess as ((data: unknown) => void) | undefined}
        tableId={tableId}
      />
    </Suspense>
  );
}

/**
 * Catalogue form component
 * This component renders a form based on a form configuration from the catalogue
 */
"use client";

// Debug flag to control logging
const _DEBUG = false;

import { useAtom } from "jotai";
import { PencilIcon, PlusIcon } from "lucide-react";
import type React from "react";
import { type ReactNode, useCallback, useMemo, useRef, useState } from "react";
import { toast } from "sonner";
import { Button } from "@/components/ui/button";
import {
  Drawer,
  DrawerClose,
  DrawerContent,
  DrawerDescription,
  DrawerFooter,
  DrawerHeader,
  DrawerTitle,
} from "@/components/ui/drawer";
import {
  type CatalogueFormState,
  catalogueFormAtom,
  formSubmittedAtom,
  handleFormOpenChange,
} from "./atoms/catalogue-form-atoms";
import { DrawerFormPortalContainerContext } from "./drawer-form-portal-context";
import { FormBuilder } from "./form-builder";
import { useFormCatalogue } from "./hooks/use-form-catalogue";
import type { FieldValues } from "./types";

interface CatalogueFormTranslations {
  updated?: string;
  created?: string;
  updateError?: string;
  createError?: string;
  updating?: string;
  creating?: string;
}

interface CatalogueFormProps<TFieldValues extends FieldValues = FieldValues> {
  /**
   * Children to render as the trigger
   * If provided, will be used instead of the default button
   */
  children?: ReactNode;

  /**
   * Type of form to use (corresponds to a key in the form catalogue)
   */
  formType?: string;

  /**
   * Initial data for the form (used for update operations)
   */
  initialData?: Partial<TFieldValues>;

  /**
   * Mode of the form (create or update)
   */
  mode?: "create" | "update";

  /**
   * Callback when the form is submitted successfully
   */
  onSuccess?: (data: unknown) => void;

  /**
   * Table ID associated with the form
   */
  tableId?: string;
}

/**
 * Returns only values that differ from initial data (for update mode)
 */
function getChangedValues<T extends FieldValues>(
  currentValues: T,
  initialData: Partial<T> | undefined
): Partial<T> {
  if (!initialData || typeof currentValues !== "object") {
    return currentValues;
  }
  const result = {} as Partial<T>;
  for (const key of Object.keys(currentValues) as (keyof T)[]) {
    const cur = currentValues[key];
    const init = initialData[key];
    if (JSON.stringify(cur) !== JSON.stringify(init)) {
      result[key] = cur;
    }
  }
  return result;
}

const FOCUSABLE_SELECTOR =
  'button:not([disabled]), [href], input:not([disabled]):not([type="hidden"]), select:not([disabled]), textarea:not([disabled]), [tabindex]:not([tabindex="-1"])';

function findFirstFocusable(container: HTMLElement): HTMLElement | null {
  const el = container.querySelector<HTMLElement>(FOCUSABLE_SELECTOR);
  return el;
}

/**
 * Prepare submission data based on mode
 */
function prepareSubmissionData<T extends FieldValues>(
  values: T,
  mode: "create" | "update",
  initialData: Partial<T> | undefined
): T {
  if (mode === "update" && initialData) {
    return {
      ...(initialData as T),
      ...getChangedValues(values, initialData),
    };
  }
  return values;
}

/**
 * Handle submission success
 */
function handleSubmissionSuccess(
  result: unknown,
  mode: "create" | "update",
  onSuccess: ((resultParam: unknown) => void) | undefined,
  _setFormState: (fn: (prev: CatalogueFormState) => CatalogueFormState) => void,
  setFormSubmitted: (submitted: boolean) => void,
  translations: CatalogueFormTranslations
): string {
  // No need to update success state as CatalogueFormState doesn't have it
  setFormSubmitted(false);

  // Call the success callback if provided
  if (onSuccess) {
    onSuccess(result);
  }

  return mode === "update"
    ? translations.updated || "Updated successfully!"
    : translations.created || "Created successfully!";
}

/**
 * Handle success flow after form submission
 */
function handleSuccessFlow<TFieldValues extends FieldValues>(
  result: unknown,
  currentMode: "create" | "update",
  currentOnSuccess: ((resultParam: unknown) => void) | undefined,
  setFormState: (fn: (prev: CatalogueFormState) => CatalogueFormState) => void,
  setFormSubmitted: (submitted: boolean) => void,
  translations: CatalogueFormTranslations,
  formSubmitted: boolean,
  form: { reset: (values?: TFieldValues) => void },
  isChangingStateRef: React.MutableRefObject<boolean>
): string {
  // Get success message using helper
  const successMessage = handleSubmissionSuccess(
    result,
    currentMode,
    currentOnSuccess,
    setFormState,
    setFormSubmitted,
    translations
  );

  // Only show success toast if a form was actually submitted
  if (formSubmitted) {
    toast.success(successMessage, {
      duration: 3000,
    });
  }

  // For update operations, update the initialData in the form state with fresh data
  if (currentMode === "update" && result) {
    setFormState((prev) => ({
      ...prev,
      initialData: result as Record<string, unknown>,
    }));
  }

  // Call the success callback first to trigger cache invalidation
  if (currentOnSuccess) {
    currentOnSuccess(result as Record<string, unknown>);
  }

  // Reset the form
  form.reset();

  // Close the form after successful submission with protection
  if (!isChangingStateRef.current) {
    isChangingStateRef.current = true;
    setFormState((prev) => handleFormOpenChange(false, prev));
    // Reset the flag after a brief delay
    setTimeout(() => {
      isChangingStateRef.current = false;
    }, 100);
  }

  return successMessage;
}

/**
 * Handle submission error
 */
function handleSubmissionError(
  error: unknown,
  mode: "create" | "update",
  setError: (errorParam: Error | null) => void,
  translations: CatalogueFormTranslations
): string {
  const errorObj = error instanceof Error ? error : new Error("Unknown error");
  setError(errorObj);

  return mode === "update"
    ? translations.updateError || "Failed to update"
    : translations.createError || "Failed to create";
}

/**
 * Initialize form state and resolve props vs atom values
 */
function useFormStateResolution<TFieldValues extends FieldValues>(
  props: CatalogueFormProps<TFieldValues>
) {
  const [formState, setFormState] = useAtom(catalogueFormAtom);
  const [loading, setLoading] = useState(false);
  const [_error, setError] = useState<Error | null>(null);

  // Extract values from form state
  const {
    formType: atomFormType,
    initialData: atomInitialData,
    isOpen,
    mode: atomMode = "create",
    onSuccess: atomOnSuccess,
    tableId: atomTableId,
  } = formState;

  // Determine which values to use (props take precedence over atom)
  const formType = props.formType || atomFormType;
  const initialData = props.initialData || atomInitialData;
  const mode = props.mode || atomMode;
  const onSuccess = props.onSuccess || atomOnSuccess;
  const _tableId = props.tableId || atomTableId;

  // Stable references to prevent callback recreation
  const onSuccessRef = useRef(onSuccess);
  const initialDataRef = useRef(initialData);
  const modeRef = useRef(mode);

  // Update refs when values change
  onSuccessRef.current = onSuccess;
  initialDataRef.current = initialData;
  modeRef.current = mode;

  return {
    formState,
    setFormState,
    loading,
    setLoading,
    setError,
    isOpen,
    formType,
    initialData,
    mode,
    onSuccessRef,
    initialDataRef,
    modeRef,
  };
}

export function CatalogueForm<TFieldValues extends FieldValues>(
  props: CatalogueFormProps<TFieldValues>
) {
  const { children } = props;

  // Initialize form state and resolve props vs atom values
  const {
    setFormState,
    loading,
    setLoading,
    setError,
    isOpen,
    formType,
    initialData,
    mode,
    onSuccessRef,
  } = useFormStateResolution(props);

  // Add a ref to track if we're in the middle of a state change
  const isChangingStateRef = useRef(false);

  const [formSubmitted, setFormSubmitted] = useAtom(formSubmittedAtom);

  const drawerContentRef = useRef<HTMLDivElement>(null);
  const previousActiveElementRef = useRef<HTMLElement | null>(null);

  const formCatalogueParams = useMemo(
    () => ({
      formType: formType || "",
      initialData: initialData as Partial<TFieldValues>,
      mode,
    }),
    [formType, initialData, mode]
  );

  const translationsRef = useRef<CatalogueFormTranslations>({});
  const formRef = useRef<{ reset: (values?: TFieldValues) => void } | null>(
    null
  );

  const onFormSubmit = useCallback(
    async (
      values: TFieldValues,
      doSubmit: (values: TFieldValues) => Promise<unknown>
    ) => {
      setFormSubmitted(true);
      setLoading(true);
      setError(null);
      const t = translationsRef.current;
      const loadingToastId = toast.loading(
        mode === "update"
          ? (t.updating ?? "Updating...")
          : (t.creating ?? "Creating...")
      );
      try {
        const valuesToSubmit = prepareSubmissionData(
          values,
          mode,
          initialData as Partial<TFieldValues> | undefined
        );
        const result = await doSubmit(valuesToSubmit as TFieldValues);
        toast.dismiss(loadingToastId);
        handleSuccessFlow(
          result,
          mode,
          onSuccessRef.current as ((resultParam: unknown) => void) | undefined,
          setFormState,
          setFormSubmitted,
          t,
          formSubmitted,
          formRef.current ?? {
            reset: () => {
              /* fallback when form not yet set */
            },
          },
          isChangingStateRef
        );
      } catch (error) {
        toast.dismiss(loadingToastId);
        toast.error(handleSubmissionError(error, mode, setError, t));
      } finally {
        setLoading(false);
      }
    },
    [
      setFormState,
      setFormSubmitted,
      setLoading,
      setError,
      mode,
      initialData,
      formSubmitted,
      onSuccessRef.current,
    ]
  );

  const formCatalogueParamsWithSubmit = useMemo(
    () => ({ ...formCatalogueParams, onFormSubmit }),
    [formCatalogueParams, onFormSubmit]
  );

  const { fields, form, translations } = useFormCatalogue<TFieldValues>(
    formCatalogueParamsWithSubmit
  );

  translationsRef.current = translations;
  formRef.current = form;

  // Handle open state changes with stable dependencies and protection
  const handleOpenChange = useCallback(
    (open: boolean) => {
      // Prevent rapid state changes
      if (isChangingStateRef.current) {
        return;
      }

      isChangingStateRef.current = true;

      if (open) {
        setFormSubmitted(false);
        previousActiveElementRef.current =
          document.activeElement instanceof HTMLElement
            ? document.activeElement
            : null;
      }

      // Use the utility function to update the form state
      setFormState((prev) => handleFormOpenChange(open, prev));

      // Reset the flag after a brief delay
      setTimeout(() => {
        isChangingStateRef.current = false;
      }, 100);
    },
    [setFormSubmitted, setFormState]
  );

  // Determine if this is a standalone form (with its own button)
  const isStandaloneForm = !(children || isOpen);

  // Stabilize the button onClick handler; capture focus restore target before opening
  const handleButtonClick = useCallback(
    (e: React.MouseEvent<HTMLButtonElement>) => {
      if (!isChangingStateRef.current) {
        previousActiveElementRef.current =
          e.currentTarget ??
          (document.activeElement instanceof HTMLElement
            ? document.activeElement
            : null);
        setFormState((prev) => handleFormOpenChange(true, prev));
      }
    },
    [setFormState]
  );

  // Use Radix Dialog's focus callbacks (Vaul uses Radix under the hood). No useEffect.
  const handleOpenAutoFocus = useCallback((e: Event) => {
    e.preventDefault();
    // Double rAF so drawer layout (and Select/portals) is committed before focus
    requestAnimationFrame(() => {
      requestAnimationFrame(() => {
        const first = drawerContentRef.current
          ? findFirstFocusable(drawerContentRef.current)
          : null;
        first?.focus();
      });
    });
  }, []);

  const handleCloseAutoFocus = useCallback((e: Event) => {
    e.preventDefault();
    const prev = previousActiveElementRef.current;
    previousActiveElementRef.current = null;
    if (prev?.isConnected) {
      prev.focus();
    }
  }, []);

  // If no form type is provided, don't render anything
  if (!formType) {
    return children || null;
  }

  return (
    <Drawer direction="right" onOpenChange={handleOpenChange} open={isOpen}>
      {/* Only render the button if this is a standalone form or if children are provided */}
      {isStandaloneForm ? (
        <Button
          onClick={handleButtonClick}
          size="sm"
          type="button"
          variant="outline"
        >
          {mode === "update" ? (
            <>
              <PencilIcon className="mr-2 h-4 w-4" />
              <span>{translations.update || "Edit"}</span>
            </>
          ) : (
            <>
              <PlusIcon className="mr-2 h-4 w-4" />
              <span>{translations.create || "Create"}</span>
            </>
          )}
        </Button>
      ) : (
        children
      )}

      <DrawerContent
        className="w-full sm:max-w-md"
        onCloseAutoFocus={handleCloseAutoFocus}
        onOpenAutoFocus={handleOpenAutoFocus}
      >
        <DrawerFormPortalContainerContext.Provider value={drawerContentRef}>
          <div
            className="relative mx-auto w-full max-w-md overflow-visible p-6"
            ref={drawerContentRef}
          >
            <DrawerHeader className="px-0">
              <DrawerTitle>
                {mode === "update"
                  ? translations["updateForm.title"]
                  : translations["createForm.title"]}
              </DrawerTitle>
              {(mode === "update"
                ? translations["updateForm.description"]
                : translations["createForm.description"]) && (
                <DrawerDescription>
                  {mode === "update"
                    ? translations["updateForm.description"]
                    : translations["createForm.description"]}
                </DrawerDescription>
              )}
            </DrawerHeader>

            {/* Use FormBuilder without its own submit button */}
            <div className="py-4">
              <FormBuilder fields={fields} form={form} submitText={null} />
            </div>

            <DrawerFooter className="flex-row justify-end gap-2 px-0">
              <DrawerClose asChild>
                <Button type="button" variant="outline">
                  {translations.cancel}
                </Button>
              </DrawerClose>
              <Button
                disabled={loading}
                onClick={() => {
                  form.handleSubmit();
                }}
                type="button"
              >
                {mode === "update" ? translations.update : translations.submit}
              </Button>
            </DrawerFooter>
          </div>
        </DrawerFormPortalContainerContext.Provider>
      </DrawerContent>
    </Drawer>
  );
}

"use client";

import { createContext, type RefObject, useContext } from "react";

/**
 * Context that provides a ref to the drawer form content container.
 * When set, Select (and other portalled components) can render their dropdown
 * inside this container so focus stays within the drawer and the dropdown
 * doesn't get closed by the drawer's focus trap.
 */
const DrawerFormPortalContainerContext =
  createContext<RefObject<HTMLElement | null> | null>(null);

export function useDrawerFormPortalContainer(): RefObject<HTMLElement | null> | null {
  return useContext(DrawerFormPortalContainerContext);
}

export { DrawerFormPortalContainerContext };

import type {
  AnyFieldDefinition,
  CheckboxFieldDefinition,
  CustomFieldDefinition,
  DateFieldDefinition,
  DynamicValueFieldDefinition,
  FieldValues,
  NumberFieldDefinition,
  Path,
  SelectFieldDefinition,
  SelectWithAddNewFieldDefinition,
  SwitchFieldDefinition,
  TextareaFieldDefinition,
  TextFieldDefinition,
  ValueTypeFieldDefinition,
} from "./types";

interface BaseFieldOptions<TFieldValues extends FieldValues> {
  dependsOn?: {
    field: Path<TFieldValues>;
    transform: (value: unknown) => string;
  };
  description?: string;
  descriptionKey?: string;
  disabled?: boolean;
  label: string;
  labelKey?: string;
  name: Path<TFieldValues>;
  placeholder?: string;
  placeholderKey?: string;
  required?: boolean;
}

/**
 * Create a checkbox field definition
 */
export function createCheckboxField<
  TFieldValues extends FieldValues = FieldValues,
>(
  options: Omit<CheckboxFieldDefinition<TFieldValues>, "type">
): CheckboxFieldDefinition<TFieldValues> {
  return {
    ...options,
    type: "checkbox",
  };
}

/**
 * Create a custom field definition
 */
export function createCustomField<
  TFieldValues extends FieldValues = FieldValues,
>(
  options: Omit<CustomFieldDefinition<TFieldValues>, "type">
): CustomFieldDefinition<TFieldValues> {
  return {
    ...options,
    type: "custom",
  };
}

/**
 * Create a date field definition
 */
export const createDateField = (
  name: string,
  label: string,
  options: Partial<DateFieldDefinition> = {}
): DateFieldDefinition => ({
  label,
  name,
  type: "date",
  ...options,
});

/**
 * Create a dynamic value field definition
 */
export function createDynamicValueField<
  TFieldValues extends FieldValues = FieldValues,
>(
  options: Omit<DynamicValueFieldDefinition<TFieldValues>, "type">
): DynamicValueFieldDefinition<TFieldValues> {
  return {
    ...options,
    type: "dynamic-value",
  };
}

/**
 * Helper to create a field definition with a name
 * This is useful for creating fields with a specific name
 */
export function createNamedField<
  TFieldValues extends FieldValues = FieldValues,
>(
  name: Path<TFieldValues>,
  fieldDefinition: Omit<AnyFieldDefinition<TFieldValues>, "name">
): AnyFieldDefinition<TFieldValues> {
  if (!fieldDefinition.type) {
    throw new Error("Field definition must have a type property");
  }

  return {
    ...fieldDefinition,
    name,
  } as AnyFieldDefinition<TFieldValues>;
}

/**
 * Create a number field definition
 */
export function createNumberField<
  TFieldValues extends FieldValues = FieldValues,
>(
  options: BaseFieldOptions<TFieldValues> & {
    max?: number;
    min?: number;
  }
): NumberFieldDefinition<TFieldValues> {
  return {
    ...options,
    type: "number",
  };
}

/**
 * Create a select field definition
 */
export function createSelectField<
  TFieldValues extends FieldValues = FieldValues,
>(
  options: Omit<SelectFieldDefinition<TFieldValues>, "type">
): SelectFieldDefinition<TFieldValues> {
  return {
    ...options,
    type: "select",
  };
}

/**
 * Create a select with add new field definition
 */
export function createSelectWithAddNewField<
  TFieldValues extends FieldValues = FieldValues,
>(
  options: Omit<SelectWithAddNewFieldDefinition<TFieldValues>, "type">
): SelectWithAddNewFieldDefinition<TFieldValues> {
  return {
    ...options,
    options: options.options || [],
    type: "select-with-add-new",
  };
}

/**
 * Create a switch field definition
 */
export function createSwitchField<
  TFieldValues extends FieldValues = FieldValues,
>(
  options: Omit<SwitchFieldDefinition<TFieldValues>, "type">
): SwitchFieldDefinition<TFieldValues> {
  return {
    ...options,
    type: "switch",
  };
}

/**
 * Create a textarea field definition
 */
export function createTextareaField<
  TFieldValues extends FieldValues = FieldValues,
