  return {
    ...options,
    type: "value-type",
  };
}

/**
 * Checkbox field component for forms (TanStack Form + Field)
 */
"use client";

import { Checkbox } from "@/components/ui/checkbox";
import {
  Field,
  FieldDescription,
  FieldError,
  FieldLabel,
} from "@/components/ui/field";
import { useTranslations } from "../../../providers/table-provider";
import type { CheckboxFieldDefinition, FormFieldApi } from "../types";

interface CheckboxFieldProps<TFieldValues extends Record<string, unknown>> {
  field: CheckboxFieldDefinition<TFieldValues>;
  fieldApi: FormFieldApi<boolean>;
}

export function CheckboxField<TFieldValues extends Record<string, unknown>>({
  field,
  fieldApi,
}: CheckboxFieldProps<TFieldValues>) {
  const { t } = useTranslations();
  const errors = fieldApi.state.meta.errors;
  const errorMessages = Array.isArray(errors)
    ? errors.map((e) => (typeof e === "string" ? e : String(e)))
    : [];
  const checked = Boolean(fieldApi.state.value);

  return (
    <Field data-invalid={!fieldApi.state.meta.isValid}>
      <div className="flex flex-row items-start space-x-3 space-y-0 rounded-md border p-4">
        <Checkbox
          checked={checked}
          disabled={field.disabled}
          id={fieldApi.name}
          onCheckedChange={(val) => fieldApi.handleChange(Boolean(val))}
        />
        <div className="space-y-1 leading-none">
          <FieldLabel htmlFor={fieldApi.name}>
            {field.labelKey ? t(field.labelKey) : field.label}
          </FieldLabel>
          {field.description != null && (
            <FieldDescription>
              {field.descriptionKey
                ? t(field.descriptionKey)
                : field.description}
            </FieldDescription>
          )}
        </div>
      </div>
      <FieldError errors={errorMessages.map((message) => ({ message }))} />
    </Field>
  );
}

/**
 * Dynamic value field – renders different inputs based on type (TanStack Form + Field)
 */
"use client";

import type {
  AnyFieldDefinition,
  CheckboxFieldDefinition,
  FormFieldApi,
  NumberFieldDefinition,
  TextareaFieldDefinition,
  TextFieldDefinition,
} from "../types";

import { NumberField } from "./number-field";
import { SwitchField } from "./switch-field";
import { TextField } from "./text-field";
import { TextareaField } from "./textarea-field";
import { ValueTypeField } from "./value-type-field";

interface DynamicValueFieldProps {
  field: AnyFieldDefinition;
  fieldApi: FormFieldApi<unknown>;
  type: "boolean" | "json" | "number" | "string";
}

export function DynamicValueField({
  field,
  fieldApi,
  type,
}: DynamicValueFieldProps) {
  switch (type) {
    case "boolean":
      return (
        <SwitchField
          field={
            {
              ...field,
              type: "checkbox",
              variant: "switch",
            } as CheckboxFieldDefinition
          }
          fieldApi={fieldApi as FormFieldApi<boolean>}
        />
      );
    case "json":
      return (
        <TextareaField
          field={
            {
              ...field,
              type: "textarea",
            } as TextareaFieldDefinition
          }
          fieldApi={fieldApi as FormFieldApi<string>}
        />
      );
    case "number":
      return (
        <NumberField
          field={
            {
              ...field,
              type: "number",
            } as NumberFieldDefinition
          }
          fieldApi={fieldApi as FormFieldApi<number | string>}
        />
      );
    case "string":
      return (
        <TextField
          field={
            {
              ...field,
              type: "text",
            } as TextFieldDefinition
          }
          fieldApi={fieldApi as FormFieldApi<string>}
        />
      );
    default:
      return (
        <ValueTypeField
          fieldApi={fieldApi}
          label={field.label}
          valueType={type}
        />
      );
  }
}

/**
 * Form-layer select dropdown content with built-in drawer support.
 * Uses Base UI primitives and applies container + absolute positioning when
 * the form is inside a drawer, so it works without modifying the shared Select.
 */
"use client";

import { Select as SelectPrimitive } from "@base-ui/react/select";
import { ChevronDownIcon, ChevronUpIcon } from "lucide-react";
import { cn } from "@/lib/utils";
import { useDrawerFormPortalContainer } from "../drawer-form-portal-context";

const POPUP_CLASSES =
