  const handleValueTypeChange = (value: string) => {
    fieldApi.handleChange(value);
    onValueTypeChange?.(value as ValueType);
  };

  return (
    <Field data-invalid={!fieldApi.state.meta.isValid}>
      <FieldLabel>{label}</FieldLabel>
