"use client";

import { type ReactNode, useEffect } from "react";
import { Button } from "@/components/ui/button";
import { useTranslations } from "../../providers/table-provider";
import {
  CheckboxField,
  DynamicValueField,
  NumberField,
  SelectField,
  SelectWithAddNewField,
  SwitchField,
  TextareaField,
  TextField,
  ValueTypeField,
} from "./fields";
import type { FormBuilderFormInstance } from "./hooks/use-form-builder";
import type {
  AnyFieldDefinition,
  DynamicValueFieldDefinition,
  FieldValues,
  FormFieldApi,
  Path,
} from "./types";

interface FormBuilderProps<TFieldValues extends FieldValues> {
  actions?: ReactNode;
  className?: string;
  disabled?: boolean;
  fields: AnyFieldDefinition<TFieldValues>[];
  form: FormBuilderFormInstance<TFieldValues>;
  isSubmitting?: boolean;
  submitText?: null | string;
}

interface WindowWithDynamicUpdates extends Window {
  __dynamicFieldUpdates?: Map<string, { name: string; value: unknown }>;
}

function normalizeFieldApi<T>(field: {
  state: { value: T; meta: { errors: unknown[]; isValid: boolean } };
  handleChange: (value: T) => void;
  handleBlur: () => void;
  name: string;
}): FormFieldApi<T> {
  const errors = field.state.meta.errors;
  const errorStrings = Array.isArray(errors)
    ? errors.map((e) => (typeof e === "string" ? e : String(e)))
    : [];
  return {
    handleBlur: field.handleBlur,
    handleChange: field.handleChange,
    name: field.name,
    state: {
      meta: { errors: errorStrings, isValid: field.state.meta.isValid },
      value: field.state.value,
    },
  };
}

export function FormBuilder<TFieldValues extends FieldValues>({
  actions,
  className,
  disabled = false,
  fields,
  form,
  isSubmitting = false,
  submitText,
}: FormBuilderProps<TFieldValues>) {
  const { t } = useTranslations();

  useEffect(() => {
    const fieldsWithDeps = fields.filter(
      (f): f is DynamicValueFieldDefinition<TFieldValues> =>
        f.type === "dynamic-value" && "dependsOn" in f
    );
    if (fieldsWithDeps.length === 0) {
      return;
    }

    const shouldTransform = (fieldName: string, fieldType: string) => {
      const isValueField = fieldName === "value";
      const isDynamic = fieldType === "dynamic-value";
      return !(isDynamic || isValueField);
    };

    for (const field of fieldsWithDeps) {
      const depField = field.dependsOn.field as Path<TFieldValues>;
      const currentVal = form.getFieldValue(depField);
      if (
        currentVal != null &&
        shouldTransform(field.name as string, field.type)
      ) {
        const transformed = field.dependsOn.transform(currentVal);
        if (typeof transformed === "string") {
          form.setFieldValue(
            field.name as Path<TFieldValues>,
            transformed as Parameters<
              FormBuilderFormInstance<TFieldValues>["setFieldValue"]
            >[1]
          );
        }
      }
    }
  }, [form, fields]);

  useEffect(() => {
    const win = window as WindowWithDynamicUpdates;
    const updates = win.__dynamicFieldUpdates;
    if (updates?.size) {
      for (const update of updates.values()) {
        try {
          form.setFieldValue(
            update.name as Path<TFieldValues>,
            update.value as Parameters<
              FormBuilderFormInstance<TFieldValues>["setFieldValue"]
            >[1]
          );
        } catch {
          // ignore
        }
      }
      updates.clear();
    }
  });

  const renderField = (field: AnyFieldDefinition<TFieldValues>) => {
    switch (field.type) {
      case "checkbox":
        return (
          <form.Field key={field.name} name={field.name as Path<TFieldValues>}>
            {(f) => (
              <CheckboxField
                field={field}
                fieldApi={
                  normalizeFieldApi(f) as unknown as FormFieldApi<boolean>
                }
              />
            )}
          </form.Field>
        );
      case "custom":
        return (
          <form.Field key={field.name} name={field.name as Path<TFieldValues>}>
            {(f) =>
              field.renderField({
                field: normalizeFieldApi(f) as unknown as FormFieldApi<unknown>,
                form: {
                  getFieldValue: (name) =>
                    form.getFieldValue(name as Path<TFieldValues>),
                  setFieldValue: (name, value) =>
                    form.setFieldValue(
                      name as Path<TFieldValues>,
                      value as Parameters<
                        FormBuilderFormInstance<TFieldValues>["setFieldValue"]
                      >[1]
                    ),
                },
              })
            }
          </form.Field>
        );
      case "dynamic-value": {
        if (!("dependsOn" in field)) {
          return null;
        }
        const depField = field.dependsOn.field as Path<TFieldValues>;
        return (
          <form.Subscribe
            key={field.name}
            selector={(state) => state.values[depField]}
          >
            {(depValue: unknown) => {
              const transformed = field.dependsOn.transform(depValue);
              const type = transformed;
              if (
                typeof type !== "string" ||
                !["boolean", "json", "number", "string"].includes(type)
              ) {
                return null;
              }
              return (
                <form.Field name={field.name as Path<TFieldValues>}>
                  {(f) => (
                    <DynamicValueField
                      field={field}
                      fieldApi={
                        normalizeFieldApi(f) as unknown as FormFieldApi<unknown>
                      }
                      type={type as "boolean" | "json" | "number" | "string"}
                    />
                  )}
                </form.Field>
              );
            }}
          </form.Subscribe>
        );
      }
      case "number":
        return (
          <form.Field key={field.name} name={field.name as Path<TFieldValues>}>
            {(f) => (
              <NumberField
                field={
                  field as AnyFieldDefinition<TFieldValues> & { type: "number" }
                }
                fieldApi={
                  normalizeFieldApi(f) as unknown as FormFieldApi<
                    number | string
                  >
                }
              />
            )}
          </form.Field>
        );
      case "select":
        return (
          <form.Field key={field.name} name={field.name as Path<TFieldValues>}>
            {(f) => (
              <SelectField
                field={field}
                fieldApi={
                  normalizeFieldApi(f) as unknown as FormFieldApi<
                    string | number | null
                  >
                }
              />
            )}
          </form.Field>
        );
      case "select-with-add-new":
        return (
          <form.Field key={field.name} name={field.name as Path<TFieldValues>}>
            {(f) => (
              <SelectWithAddNewField
                fieldApi={
                  normalizeFieldApi(f) as unknown as FormFieldApi<string | null>
                }
                items={field.options?.map((o) => String(o.value)) ?? []}
                label={field.label}
                name={field.name as string}
                optionsLoader={field.optionsLoader}
                placeholder={field.placeholder}
              />
            )}
          </form.Field>
        );
      case "switch":
        return (
          <form.Field key={field.name} name={field.name as Path<TFieldValues>}>
            {(f) => (
              <SwitchField
                field={{ ...field, type: "checkbox", variant: "switch" }}
                fieldApi={
                  normalizeFieldApi(f) as unknown as FormFieldApi<boolean>
                }
              />
            )}
          </form.Field>
        );
      case "text":
        return (
          <form.Field key={field.name} name={field.name as Path<TFieldValues>}>
            {(f) => (
              <TextField
                field={field}
                fieldApi={
                  normalizeFieldApi(f) as unknown as FormFieldApi<string>
                }
              />
            )}
          </form.Field>
        );
      case "textarea":
        return (
          <form.Field key={field.name} name={field.name as Path<TFieldValues>}>
            {(f) => (
              <TextareaField
                field={
                  field as AnyFieldDefinition<TFieldValues> & {
                    type: "textarea";
                  }
                }
                fieldApi={
                  normalizeFieldApi(f) as unknown as FormFieldApi<string>
                }
              />
            )}
          </form.Field>
        );
      case "value-type":
        return (
          <form.Field key={field.name} name={field.name as Path<TFieldValues>}>
            {(f) => (
              <form.Subscribe
                selector={(state) =>
                  state.values[field.valueTypeField as Path<TFieldValues>]
                }
              >
                {(valueType: unknown) => (
                  <ValueTypeField
                    description={field.description}
                    fieldApi={
                      normalizeFieldApi(f) as unknown as FormFieldApi<unknown>
                    }
                    label={field.label}
                    placeholder={field.placeholder}
                    valueType={
                      ((valueType as string) || "string") as
                        | "boolean"
                        | "json"
                        | "number"
                        | "string"
                    }
                  />
                )}
              </form.Subscribe>
            )}
          </form.Field>
        );
      default:
        return null;
    }
  };

  return (
    <form
      className={className}
      onSubmit={(e) => {
        e.preventDefault();
        e.stopPropagation();
        form.handleSubmit();
      }}
    >
      <div className="space-y-4">
        {fields.map((field) => (
          <div key={String(field.name)}>{renderField(field)}</div>
        ))}
      </div>
      {submitText != null && (
        <div className="mt-6 flex items-center justify-between">
          <div className="flex items-center gap-4">{actions}</div>
          {submitText && (
            <Button disabled={disabled || isSubmitting} type="submit">
              {t(submitText)}
            </Button>
          )}
        </div>
      )}
    </form>
  );
}

/**
 * Form definition helpers
 * These functions help define form configurations
 */

import type { z } from "zod";
import type { AnyFieldDefinition, FieldValues, FormConfig } from "./types";

/**
 * Default form translations
 */
export const defaultFormTranslations = {
  keys: {
    cancel: "cancel",
    create: "create",
    "createForm.description": "create_form.description",
    "createForm.title": "create_form.title",
    error: "error",
    errorDescription: "error_description",
    submit: "submit",
    success: "success",
    successDescription: "success_description",
  },
  namespace: "common",
};

/**
 * Define a form configuration
 * @param config Form configuration
 * @returns Complete form configuration with defaults
 */
export function defineFormConfig<
  TFieldValues extends FieldValues = FieldValues,
>(config: {
  /**
   * Default values for the form
   */
  defaultValues: Partial<TFieldValues>;

  /**
   * Field definitions
   */
  fields: AnyFieldDefinition<TFieldValues>[];

  /**
   * Form ID
   */
  id: string;

  /**
   * Schema for form validation
   */
  schema: z.ZodType<TFieldValues>;

  /**
   * Translation configuration
   */
  translations?: Partial<FormConfig<TFieldValues>["translations"]>;
}): FormConfig<TFieldValues> {
  // Merge translations with defaults
  const translations = {
    ...defaultFormTranslations,
    ...config.translations,
  };

  return {
    defaultValues: config.defaultValues,
    fields: config.fields,
    id: config.id,
    schema: config.schema,
    translations,
  };
}

/**
 * Form builder hook
 * This hook creates a form instance based on a form configuration (TanStack Form)
 */
"use client";

import { useForm } from "@tanstack/react-form";
import { zodValidator } from "@tanstack/zod-form-adapter";
import { useCallback, useEffect, useMemo, useRef } from "react";
import { useTranslations } from "../../../providers/table-provider";

import type {
  AnyFieldDefinition,
  FieldValues,
  FormConfig,
  SelectFieldDefinition,
} from "../types";

export interface UseFormBuilderOptions<TFieldValues extends FieldValues> {
  config: FormConfig<TFieldValues>;
  formOptions?: {
    onSubmit?: (values: TFieldValues) => void | Promise<void>;
  };
  initialData?: Partial<TFieldValues>;
}

/**
 * Form builder hook
 * @param options - Hook options
 * @returns Form instance and fields
 */
export function useFormBuilder<TFieldValues extends FieldValues>({
  config,
  formOptions = {},
  initialData,
}: UseFormBuilderOptions<TFieldValues>) {
  const { t } = useTranslations();
  const prevInitialDataRef = useRef<Partial<TFieldValues> | undefined>(
    undefined
  );
  const formResetInProgressRef = useRef(false);

  const defaultValues = useMemo(() => {
    return initialData
      ? { ...(config.defaultValues as TFieldValues), ...initialData }
      : (config.defaultValues as TFieldValues);
  }, [config.defaultValues, initialData]);

  const form = useForm({
    defaultValues,
    validators: {
      onSubmit: (
        zodValidator() as (
          schema: unknown
        ) => ReturnType<ReturnType<typeof zodValidator>>
      )(config.schema),
    } as unknown as { onSubmit: (opts: { value: TFieldValues }) => unknown },
    onSubmit: formOptions.onSubmit
      ? ({ value }) => {
          formOptions.onSubmit?.(value as TFieldValues);
        }
      : undefined,
  });

  useEffect(() => {
    if (
      initialData &&
      !formResetInProgressRef.current &&
      JSON.stringify(initialData) !== JSON.stringify(prevInitialDataRef.current)
    ) {
      formResetInProgressRef.current = true;
      const newDefaultValues = {
        ...(config.defaultValues as TFieldValues),
        ...initialData,
      };
      form.reset(newDefaultValues);
      prevInitialDataRef.current = initialData;
      setTimeout(() => {
        formResetInProgressRef.current = false;
      }, 10);
    }
  }, [initialData, config.defaultValues, form]);

  const translateField = useCallback(
    (
      field: AnyFieldDefinition<TFieldValues>
    ): AnyFieldDefinition<TFieldValues> => {
      if (field.labelKey) {
        return { ...field, label: t(field.labelKey) };
      }
      if (field.descriptionKey) {
        return { ...field, description: t(field.descriptionKey) };
      }
      if (field.placeholderKey) {
        return { ...field, placeholder: t(field.placeholderKey) };
      }
      if (field.type === "select") {
        const selectField = field as SelectFieldDefinition<TFieldValues>;
        const optionKeys = selectField.optionKeys;
        if (optionKeys?.length) {
          return {
            ...selectField,
            options: selectField.options.map((option, index) => ({
              label:
                index < optionKeys.length ? t(optionKeys[index]) : option.label,
              value: option.value,
            })),
          };
        }
      }
      return field;
    },
    [t]
  );

  const fields = useMemo(
    () =>
      config.fields.map(translateField) as AnyFieldDefinition<TFieldValues>[],
    [config.fields, translateField]
  );

  const translations = useMemo(() => {
    return Object.entries(config.translations.keys).reduce(
      (acc, [key, value]) => {
        acc[key] = t(value);
        return acc;
      },
      {} as Record<string, string>
    );
  }, [config.translations.keys, t]);

  return {
    fields,
    form,
    translations,
  };
}

/** Form instance type returned by useFormBuilder (TanStack Form API) */
export type FormBuilderFormInstance<TFieldValues extends FieldValues> =
  ReturnType<typeof useFormBuilder<TFieldValues>>["form"];

/**
 * Hook for using form configurations from the catalogue
 */
"use client";

import { useCallback, useMemo } from "react";
import { z } from "zod";

import {
  useFormConfig,
  useTableActions,
} from "../../../providers/table-provider";
import type { AnyFieldDefinition, FieldValues, FormConfig } from "../types";

import { useFormBuilder } from "./use-form-builder";

export interface UseFormCatalogueOptions<TFieldValues extends FieldValues> {
  /**
   * Type of form to use (corresponds to a key in the form catalogue)
   */
  formType: string;

  /**
   * Initial data for the form (used for update operations)
   */
  initialData?: Partial<TFieldValues>;

  /**
   * Mode of the form (create or update)
   */
  mode?: "create" | "update";

  /**
   * Optional wrapper for submit (e.g. loading, toast). Receives validated values and the actual submit function.
   * The wrapper can use form from its closure (e.g. via a ref updated after useFormCatalogue returns).
   */
  onFormSubmit?: (
    values: TFieldValues,
    doSubmit: (values: TFieldValues) => Promise<unknown>
  ) => Promise<void>;
}

/**
 * Hook for using form configurations from the catalogue
 * @param options Hook options
 * @returns Form builder result
 */
export function useFormCatalogue<TFieldValues extends FieldValues>({
  formType,
  initialData,
  mode = "create",
  onFormSubmit,
}: UseFormCatalogueOptions<TFieldValues>) {
  // Get the configuration helpers from the provider
  const getFormConfig = useFormConfig();
  const getTableActions = useTableActions();

  // Stabilize the form configuration object to prevent recreation
  const config = useMemo(() => {
    return (
      getFormConfig?.<TFieldValues>(formType) ||
      ({
        id: formType,
        fields: [],
        defaultValues: {} as Partial<TFieldValues>,
        schema: z.any() as z.ZodType<TFieldValues>,
        translations: {
          namespace: "common",
          keys: {},
        },
      } as FormConfig<TFieldValues>)
    );
  }, [getFormConfig, formType]);

  // Stabilize the table actions object to prevent recreation
  const actions = useMemo(() => {
    return getTableActions?.(formType) || {};
  }, [getTableActions, formType]);

  // Helper function to sanitize a single field value
  const sanitizeFieldValue = useCallback(
    (
      _key: string,
      value: unknown,
      fieldDef: AnyFieldDefinition<TFieldValues> | undefined
    ): unknown => {
      if (!fieldDef) {
        return value;
      }

      // Handle JSON fields
      if (
        fieldDef.type === "value-type" &&
        fieldDef.supportedTypes?.includes("json") &&
        typeof value === "string"
      ) {
        try {
          return JSON.parse(value);
        } catch {
          return value; // Keep as string if parsing fails
        }
      }

      // Handle boolean fields (ensure they're actual booleans)
      if (fieldDef.type === "checkbox") {
        return Boolean(value);
      }

      return value;
    },
    []
  );

  // Helper function to sanitize form values
  const sanitizeFormValues = useCallback(
    (values: TFieldValues) => {
      return Object.entries(values).reduce(
        (acc, [key, value]) => {
          // Find the field definition to check its type
          const fieldDef = config?.fields?.find(
            (f: AnyFieldDefinition<TFieldValues>) => f.name === key
          );

          acc[key] = sanitizeFieldValue(key, value, fieldDef);
          return acc;
        },
        {} as Record<string, unknown>
      );
    },
    [config?.fields, sanitizeFieldValue]
  );

  // Helper function to prepare update data
  const prepareUpdateData = useCallback(
    (
      sanitizedValues: Record<string, unknown>,
      operationMode: "create" | "update",
      initialFormData?: Partial<TFieldValues>
    ) => {
      let dataToSubmit = sanitizedValues;
      if (operationMode === "update" && initialFormData) {
        // Merge the sanitized form values with the initial data
        dataToSubmit = {
          ...(initialFormData as Record<string, unknown>),
          ...sanitizedValues,
        };

        // Remove null JSON fields entirely - this prevents validation errors
        // and lets Prisma handle the fields appropriately
        for (const key of Object.keys(dataToSubmit)) {
          if (
            dataToSubmit[key] === null &&
            (key === "options" ||
              key === "value" ||
              key === "config" ||
              key === "metadata")
          ) {
            // For JSON fields, omit them entirely if they're null
            delete dataToSubmit[key];
          }
        }
      }
      return dataToSubmit;
    },
    []
  );

  // Helper function to execute form action
  const executeFormAction = useCallback(
    async (
      operationMode: "create" | "update",
      tableActions: {
        create?: (data: Record<string, unknown>) => Promise<{
          success: boolean;
          data?: unknown;
          error?: string | undefined;
        }>;
        update?: (
          id: string,
          data: Record<string, unknown>
        ) => Promise<{
          success: boolean;
          data?: unknown;
          error?: string | undefined;
        }>;
      },
      formValues: TFieldValues,
      initialFormData: Partial<TFieldValues> | undefined,
      formTypeName: string,
      dataToSubmit: Record<string, unknown>,
      sanitizedValues: Record<string, unknown>
    ) => {
      if (operationMode === "update" && tableActions.update) {
        // For update, we need the ID from the values or initialData
        let id: string;

        // Try to get ID from values first
        if ("id" in formValues) {
          id = String(formValues.id);
        }
        // Then try to get ID from initialData if available
        else if (initialFormData && "id" in initialFormData) {
          id = String((initialFormData as Record<string, unknown>).id);
        }
        // If no ID is found, throw an error
        else {
          throw new Error(
            `ID not found for update operation on ${formTypeName}`
          );
        }

        // Create a clean copy of the data without the ID for the update operation
        const updateData = { ...dataToSubmit };
        if ("id" in updateData) {
          (updateData as Record<string, unknown>).id = undefined;
        }

        return await tableActions.update(
          id as string,
          updateData as Record<string, unknown>
        );
      }
      if (operationMode === "create" && tableActions.create) {
        return await tableActions.create(
          sanitizedValues as Record<string, unknown>
        );
      }
      throw new Error(
        `Action ${operationMode} not available for ${formTypeName}`
      );
    },
    []
  );

  // Handle form submission (passed to useFormBuilder as onSubmit)
  const handleSubmit = useCallback(
    async (values: TFieldValues) => {
      const sanitizedValues = sanitizeFormValues(values);
      const dataToSubmit = prepareUpdateData(
        sanitizedValues,
        mode,
        initialData
      );
      const result = await executeFormAction(
        mode,
        actions,
        values,
        initialData,
        formType,
        dataToSubmit,
        sanitizedValues
      );
      if (!result.success) {
        throw new Error(result.error ?? `Failed to ${mode} ${formType}`);
      }
      return result.data;
    },
    [
      formType,
      mode,
      actions,
      initialData,
      executeFormAction,
      sanitizeFormValues,
      prepareUpdateData,
    ]
  );

  const { fields, form, translations } = useFormBuilder<TFieldValues>({
    config,
    formOptions: {
      onSubmit: onFormSubmit
        ? (values) => {
            onFormSubmit(values, handleSubmit);
          }
        : (values) => {
            handleSubmit(values);
          },
    },
    initialData,
  });

  return {
    fields,
    form,
    handleSubmit,
    translations,
  };
}

