/**
 * Pagination sans Select Radix pour éviter les boucles infinies
 * Utilise des boutons simples à la place
 */
"use client";

import type { Table } from "@tanstack/react-table";
import {
  ChevronLeft,
  ChevronRight,
  ChevronsLeft,
  ChevronsRight,
} from "lucide-react";
import { useCallback } from "react";
import { cn } from "@/lib/utils";
import { Button } from "@/components/ui/button";
import { useTableTranslations } from "../hooks";

interface SafePaginationProps<TData> {
  table: Table<TData>;
  rowCount?: number;
  className?: string;
}

export function SafePagination<TData>({
  table,
  rowCount,
  className,
}: SafePaginationProps<TData>) {
  const translations = useTableTranslations();

  // Get pagination state
  const { pageIndex, pageSize } = table.getState().pagination;
  const pageCount = table.getPageCount();

  // Calculate display info
  const startRow = pageIndex * pageSize + 1;
  const endRow = Math.min(
    (pageIndex + 1) * pageSize,
    rowCount || table.getRowModel().rows.length
  );

  // Page size options
  const pageSizeOptions = [5, 10, 20, 30, 50];

  // Handle page size change with buttons instead of Select
  const handlePageSizeChange = useCallback(
    (newSize: number) => {
      if (newSize === pageSize) {
        return; // Prevent unnecessary updates
      }
      table.setPageSize(newSize);
    },
    [table, pageSize]
  );

  return (
    <div
      className={cn(
        "flex flex-col items-center justify-between gap-4 py-4 sm:flex-row",
        className
      )}
    >
      {/* Row range display */}
      <div className="flex-1 text-muted-foreground text-sm">
        {startRow}-{endRow} {translations.of}{" "}
        {rowCount ?? table.getRowModel().rows.length}
      </div>

      {/* Page size selector with buttons */}
      <div className="flex items-center gap-2">
        <p className="font-medium text-sm">{translations.rowsPerPage}</p>
        <div className="flex gap-1">
          {pageSizeOptions.map((size) => (
            <Button
              className="h-8 w-10 p-0"
              key={size}
              onClick={() => handlePageSizeChange(size)}
              size="sm"
              type="button"
              variant={size === pageSize ? "default" : "outline"}
            >
              {size}
            </Button>
          ))}
        </div>
      </div>

      {/* Page navigation */}
      <div className="flex items-center gap-2">
        <Button
          aria-label={translations.firstPage}
          className="h-8 w-8"
          disabled={!table.getCanPreviousPage()}
          onClick={() => table.setPageIndex(0)}
          size="icon"
          type="button"
          variant="outline"
        >
          <ChevronsLeft className="h-4 w-4" />
        </Button>
        <Button
          aria-label={translations.previousPage}
          className="h-8 w-8"
          disabled={!table.getCanPreviousPage()}
          onClick={() => table.previousPage()}
          size="icon"
          type="button"
          variant="outline"
        >
          <ChevronLeft className="h-4 w-4" />
        </Button>

        <div className="flex items-center gap-1 text-sm">
          <span>Page</span>
          <span className="font-medium">{pageIndex + 1}</span>
          <span>of</span>
          <span className="font-medium">{pageCount}</span>
        </div>

        <Button
          aria-label={translations.nextPage}
          className="h-8 w-8"
          disabled={!table.getCanNextPage()}
          onClick={() => table.nextPage()}
          size="icon"
          type="button"
          variant="outline"
        >
          <ChevronRight className="h-4 w-4" />
        </Button>
        <Button
          aria-label={translations.lastPage}
          className="h-8 w-8"
          disabled={!table.getCanNextPage()}
          onClick={() => table.setPageIndex(pageCount - 1)}
          size="icon"
          type="button"
          variant="outline"
        >
          <ChevronsRight className="h-4 w-4" />
        </Button>
      </div>
    </div>
  );
}

/**
 * Sortable row component for DataTable
 * Uses dnd-kit for drag and drop functionality
 */
"use client";

import { useSortable } from "@dnd-kit/sortable";
import { CSS } from "@dnd-kit/utilities";
import { useAtomValue } from "jotai";
import type * as React from "react";
import { cn } from "@/lib/utils";

import { activeRowDragAtom, rowDragEnabledAtom } from "../atoms/table-atoms";

interface SortableRowProps {
  children: React.ReactNode;
  className?: string;
  id: string;
  tableId: string;
}

/**
 * A sortable row component that can be dragged to reorder rows
 */
export function SortableRow({
  children,
  className,
  id,
  tableId,
}: SortableRowProps) {
  // Get state from atoms
  const isDragEnabled = useAtomValue(rowDragEnabledAtom(tableId));
  const activeDragId = useAtomValue(activeRowDragAtom(tableId));

  // Get sortable props from dnd-kit - always call hooks at the top level
  const {
    attributes,
    isDragging,
    listeners,
    setNodeRef,
    transform,
    transition,
  } = useSortable({
    // Use the provided ID directly for the DnD context
    data: {
      stableId: `row-${id}`,
    },
    disabled: !isDragEnabled, // Disable sortable functionality instead of conditionally rendering
    id,
  });

  // Create style for the draggable element
  const style = {
    transform: CSS.Transform.toString(transform),
    transition,
  };

  // Determine if this row is being dragged over
  const isOver = activeDragId !== null && activeDragId !== id;

  // If drag is disabled, just return the children as-is
  if (!isDragEnabled) {
    return <>{children}</>;
  }

  // Use a simpler approach to avoid hydration issues
  // Instead of trying to clone elements, we'll simply wrap the children in a div
  // with the drag-and-drop properties

  // Create an object with the drag-and-drop properties
  const dragProps = {
    ref: setNodeRef,
    style,
    ...attributes,
    ...listeners,
    "aria-label": `Drag to reorder row ${id}`,
    className: cn(
      className,
      "relative cursor-grab select-none",
      isDragging && "z-10 cursor-grabbing opacity-50 shadow-lg",
      isOver && "border-2 border-primary/50"
    ),
  };

  // Return the children wrapped in a div with the drag-and-drop properties
  return <div {...dragProps}>{children}</div>;
}

