            <Filter className="mx-auto mb-2 h-8 w-8 opacity-50" />
            <p className="text-sm">{t("filters.noFilters")}</p>
            <p className="text-xs">{t("filters.noResults")}</p>
          </div>

          {/* Show legacy column filters if any exist */}
          {columnFilters.length > 0 && (
            <div className="space-y-2">
              <Separator />
              <h4 className="font-medium text-sm">{t("filters.title")}</h4>
              {columnFilters.map((filter, index) => (
                <div
                  className="flex items-center gap-2 rounded-md border p-2"
                  key={`${filter.id}-${index}`}
                >
                  <span className="font-medium text-sm">{filter.id}</span>
                  <span className="text-muted-foreground text-xs">:</span>
                  <span className="text-sm">{String(filter.value)}</span>
                  <Button
                    className="ml-auto h-6 w-6 p-0"
                    onClick={() => {
                      const newFilters = columnFilters.filter(
                        (_, i) => i !== index
                      );
                      setColumnFilters(newFilters);
                    }}
                    size="sm"
                    variant="ghost"
                  >
                    <X className="h-3 w-3" />
                  </Button>
                </div>
              ))}
            </div>
          )}
        </div>
      </StackMenuContent>
    </StackMenuView>
  );
}

"use client";

import type { GroupingState } from "@tanstack/react-table";
import { useMemo } from "react";
import { StackMenuContent, StackMenuView } from "../../../ui-custom/stack-menu";
import { useTableConfig } from "../../../hooks/use-table-config";
import { useTableUrlState } from "../../../hooks/use-table-url-state";
import { useTranslations } from "../../../providers/table-provider";
import { GroupPicker } from "./group-picker";

export interface TableGroupingMenuProps {
  columns: {
    canFilter?: boolean;
    canGroup?: boolean;
    canHide?: boolean;
    canSort?: boolean;
    id: string;
    label: string;
  }[];
  grouping: GroupingState;
  invalidateTable: () => Promise<void>;
  setGrouping: (state: GroupingState) => void;
  tableId: string;
}

export function TableGroupingMenu({
  columns,
  grouping,
  setGrouping,
  tableId: _tableId,
}: TableGroupingMenuProps) {
  const _t = useTranslations();
  const { setExpandedFromUI } = useTableUrlState({ tableId: _tableId });
  const { config } = useTableConfig(_tableId);

  // Get groupable columns with types from config
  const groupableColumns = useMemo(() => {
    // Exclude system/action columns and those that explicitly disable grouping
    const filteredColumns = columns.filter(
      (col) => col.id !== "actions" && col.canGroup !== false
    );

    // Map each column to include its type from the config
    return filteredColumns.map((col) => {
      const configColumn = config.columns.definitions.find(
        (def) => def.id === col.id
      );
      return {
        ...col,
        type: configColumn?.type || "text",
      };
    });
  }, [columns, config.columns.definitions]);

  // Always render the wrapper view; show empty state content when no columns

  return (
    <StackMenuView name="group">
      <StackMenuContent>
        <GroupPicker
          columns={groupableColumns.map((c) => ({
            id: c.id,
            label: c.label,
            type: c.type || "text",
          }))}
          grouping={grouping as string[]}
          onChange={(next) => setGrouping(next as typeof grouping)}
          onCollapseAll={() => setExpandedFromUI({})}
          onExpandAll={() => setExpandedFromUI({ _all: true })}
          onReset={() => setGrouping([])}
        />
      </StackMenuContent>
    </StackMenuView>
  );
}

"use client";

import type { SortingState } from "@tanstack/react-table";
import { ArrowDownAZ, ArrowUpAZ, ArrowUpDown, Plus } from "lucide-react";
import {
  StackMenuContent,
  StackMenuItem,
  StackMenuView,
  useStackMenu,
} from "../../../ui-custom/stack-menu";
import { Button } from "@/components/ui/button";
import { useDataTable } from "../../../hooks/use-data-table";
import { useTranslations } from "../../../providers/table-provider";

export interface TableSortMenuProps {
  columns: Array<{
    canSort?: boolean;
    getCanSort: () => boolean;
    id: string;
    label: string;
  }>;
  invalidateTable: () => Promise<void>;
  setSorting: (state: SortingState) => void;
  sorting: SortingState;
  tableId: string;
}

export function TableSortMenu({
  columns,
  invalidateTable: _invalidateTable,
  setSorting,
  sorting,
  tableId,
}: TableSortMenuProps) {
  const { t } = useTranslations();
  const stackMenu = useStackMenu();

  // Get table configuration to access column headers with translations
  const { config } = useDataTable({
    tableType: tableId,
  });

  // Get sortable columns
  const sortableColumns = columns.filter((col) => {
    const canSort =
      typeof col.getCanSort === "function"
        ? col.getCanSort()
        : col.canSort !== false;
    return canSort;
  });

  // Skip rendering if no sortable columns
  if (sortableColumns.length === 0) {
    return null;
  }

  // Split into active and inactive to show active first
  const activeSortIds = new Set((sorting || []).map((s) => s.id));
  const activeColumns = sortableColumns.filter((c) => activeSortIds.has(c.id));
  const inactiveColumns = sortableColumns.filter(
    (c) => !activeSortIds.has(c.id)
  );

  return (
    <StackMenuView name="sort">
      <StackMenuContent>
        <div className="mb-2 flex items-center justify-between">
          <div className="px-2 font-medium text-foreground text-sm">
            {sorting.length > 0
              ? t("sorting.current")
              : t("sorting.choose_column")}
          </div>
          <Button
            disabled={sorting.length === 0}
            onClick={() => setSorting([])}
            size="sm"
            variant="outline"
          >
            {t("common.reset")}
          </Button>
        </div>

        {/* Active sorts */}
        {activeColumns.map((column) => {
          const columnId = column.id;
          const sortOrder = sorting.find((sort) => sort.id === columnId)?.desc;
          const isActiveSorted = sortOrder !== undefined;

          // Get column configuration from table config to get proper translated header
          const columnConfig = config?.columns?.definitions?.find(
            (def: { id: string; header?: string }) => def.id === columnId
          );

          // Use translated header from config, with fallbacks
          let columnLabel: string;
          if (columnId === "actions") {
            columnLabel = t("actions.title");
          } else if (columnConfig?.header) {
            // Try to translate the header from config
            columnLabel = t(columnConfig.header);
          } else {
            // Fallback to the label from the column or columnId
            columnLabel = column.label || columnId;
          }

          return (
            <StackMenuItem
              className={`h-7 gap-2 px-2 text-sm ${isActiveSorted ? "bg-accent font-medium" : ""}`}
              endIcon={
                isActiveSorted ? undefined : <Plus className="h-3.5 w-3.5" />
              }
              icon={(() => {
                if (sortOrder === undefined) {
                  return (
                    <ArrowUpDown className="h-3.5 w-3.5 text-muted-foreground" />
                  );
                }
                if (sortOrder) {
                  return (
                    <ArrowDownAZ className="h-3.5 w-3.5 text-foreground" />
                  );
                }
                return <ArrowUpAZ className="h-3.5 w-3.5 text-foreground" />;
              })()}
              key={columnId}
              onClick={(e) => {
                e.preventDefault();
                e.stopPropagation();
                if (sortOrder === undefined) {
                  // First click: ascending
                  setSorting([{ desc: false, id: columnId }]);
                } else if (sortOrder) {
                  // Third click: remove sort
                  setSorting([]);
                } else {
                  // Second click: descending
                  setSorting([{ desc: true, id: columnId }]);
                }
                // Keep menu open after updating sorting
                stackMenu.onOpenChange?.(true);
              }}
            >
              <span className={isActiveSorted ? "font-medium" : ""}>
                {columnLabel}
              </span>
            </StackMenuItem>
          );
        })}

        {/* Inactive sorts */}
        {inactiveColumns.map((column) => {
          const columnId = column.id;
          const sortOrder = sorting.find((sort) => sort.id === columnId)?.desc;
          const isActiveSorted = sortOrder !== undefined;

          const columnConfig = config?.columns?.definitions?.find(
            (def: { id: string; header?: string }) => def.id === columnId
          );

          let columnLabel: string;
          if (columnId === "actions") {
            columnLabel = t("actions.title");
          } else if (columnConfig?.header) {
            columnLabel = t(columnConfig.header);
          } else {
            columnLabel = column.label || columnId;
          }

          return (
            <StackMenuItem
              className={`h-7 gap-2 px-2 text-sm ${isActiveSorted ? "bg-accent font-medium" : ""}`}
              endIcon={<Plus className="h-3.5 w-3.5" />}
              icon={
                <ArrowUpDown className="h-3.5 w-3.5 text-muted-foreground" />
              }
              key={columnId}
              onClick={(e) => {
                e.preventDefault();
                e.stopPropagation();
                setSorting([{ desc: false, id: columnId }]);
                stackMenu.onOpenChange?.(true);
              }}
            >
              <span>{columnLabel}</span>
            </StackMenuItem>
          );
        })}
      </StackMenuContent>
    </StackMenuView>
  );
}

"use client";

import type { TableState } from "@tanstack/react-table";
import { useAtomValue, useSetAtom } from "jotai";
import {
  ArrowUpDown,
