  /** Advanced filters configuration */
  advancedFiltersConfig?: {
    filters: AdvancedFiltersState;
    actions: FilterActions;
    columnsConfig: ColumnsFilterConfig;
    onConvertToAdvanced?: (columnId: string, type: ColumnDataType) => void;
