/**
 * Helper hook for creating a quick filter setup
 */
export function useQuickFilterSetup<TData = Record<string, unknown>>(
  _tableId: string,
  _data: TData[]
) {
  const {
    createTextColumn,
    createNumberColumn: _createNumberColumn,
    createDateColumn: _createDateColumn,
    createOptionColumn: _createOptionColumn,
  } = useColumnFilterConfig();

  // Basic text search across multiple columns
  const createQuickSearch = useCallback(
    (
      searchColumns: Array<{
        id: string;
        accessor: (row: TData) => unknown;
        weight?: number;
      }>
    ) => {
      const columnsConfig: ColumnsFilterConfig = {};
      const accessors: Record<string, (row: TData) => unknown> = {};

      for (const { id, accessor } of searchColumns) {
        columnsConfig[id] = createTextColumn(id, {
          placeholder: `Search ${id}...`,
        });
        accessors[id] = accessor;
      }

      return { columnsConfig, accessors };
    },
    [createTextColumn]
  );

  return {
    createQuickSearch,
  };
}

/**
 * Hook for managing bulk actions on selected table rows
 */
"use client";

import type { Row, Table } from "@tanstack/react-table";
import { useCallback } from "react";
import { useTableActions } from "./use-table-actions";

/**
 * Configuration for bulk actions
 */
interface BulkActionsConfig<TData> {
  /**
   * Table instance from TanStack Table
   */
  table: Table<TData>;

  /**
   * Callback when bulk edit is triggered
   */
  onBulkEdit?: (rows: Row<TData>[]) => void;

  /**
   * Callback when bulk delete is triggered
   */
  onBulkDelete?: (rows: Row<TData>[]) => void;

  /**
   * Callback when bulk copy is triggered
   */
  onBulkCopy?: (rows: Row<TData>[]) => void;

  /**
   * Minimum number of selected rows to show bulk actions menu
   */
  minimumSelection?: number;

  /**
   * Optional table type to auto-wire provider actions when callbacks are not provided
   */
  tableType?: string;
}

/**
 * Return type for the bulk actions hook
 */
interface BulkActionsReturn<TData> {
  /**
   * Currently selected rows
   */
  selectedRows: Row<TData>[];

  /**
   * Number of selected rows
   */
  selectedCount: number;

  /**
   * Whether the bulk actions menu should be visible
   */
  showBulkActions: boolean;

  /**
   * Handle bulk edit action
   */
  handleBulkEdit: () => void;

  /**
   * Handle bulk delete action
   */
  handleBulkDelete: () => void;

  /**
   * Handle bulk copy action
   */
  handleBulkCopy: () => void;

  /**
   * Clear all selections
   */
  clearSelection: () => void;

  /**
   * Close bulk actions menu (clears selection)
   */
  closeBulkActions: () => void;
}

const _DEBUG = false;
/**
 * Hook to manage bulk actions for data table
 *
 * Provides state management and handlers for bulk operations
 * on selected table rows
 */
export function useBulkActions<TData>({
  table,
  onBulkEdit,
  onBulkDelete,
  onBulkCopy,
  minimumSelection = 1,
  tableType,
}: BulkActionsConfig<TData>): BulkActionsReturn<TData> {
  // Call hook unconditionally to satisfy Rules of Hooks; use result only when tableType is set
  const providerResult = useTableActions<{ id: string }>({
    tableType: tableType ?? "",
    enableLogging: false,
  });
  const provider = tableType ? providerResult : undefined;

  // Use core row model so selected rows are correct even when grouping is active (collapsed = getRowModel() has no leaves)
  const selectedRows =
    table && typeof table.getState === "function"
      ? (() => {
          const rowSelection = table.getState().rowSelection || {};
          const rows = table.getCoreRowModel().rows;
          return rows.filter((row) => rowSelection[row.id]) as Row<TData>[];
        })()
      : [];
  const showBulkActions = selectedRows.length >= minimumSelection;

  // Clear all selections
  const clearSelection = useCallback(() => {
    if (!table) {
      return;
    }
    table.setRowSelection({});
  }, [table]);

  // Handle bulk edit
  const handleBulkEdit = useCallback(() => {
    if (selectedRows.length === 0) {
      return;
    }
    if (onBulkEdit) {
      onBulkEdit(selectedRows);
      return;
    }
    // If provider available, delegate to update for each selected row (no-op without data)
    if (provider?.actions.update) {
      for (const row of selectedRows) {
        const original = row.original as unknown;
        if (original && typeof original === "object" && "id" in original) {
          const idValue = (original as { id: unknown }).id;
          if (typeof idValue === "string") {
            provider.actions
              .update(idValue, original as Record<string, unknown>)
              .catch(() => {
                /* ignore update errors */
              });
          }
        }
      }
    }
  }, [selectedRows, onBulkEdit, provider?.actions?.update]);

  // Handle bulk delete
  const handleBulkDelete = useCallback(() => {
    if (selectedRows.length === 0) {
      return;
    }
    if (onBulkDelete) {
      onBulkDelete(selectedRows);
      clearSelection();
      return;
    }
    if (provider?.actions.delete) {
      for (const row of selectedRows) {
        const original = row.original as unknown;
        if (original && typeof original === "object" && "id" in original) {
          const idValue = (original as { id: unknown }).id;
          if (typeof idValue === "string") {
            provider.actions.delete(idValue).catch(() => {
              /* ignore delete errors */
            });
          }
        }
      }
      clearSelection();
    }
  }, [selectedRows, onBulkDelete, clearSelection, provider?.actions]);

  // Handle bulk copy
  const handleBulkCopy = useCallback(() => {
    if (selectedRows.length === 0) {
      return;
    }
    if (onBulkCopy) {
      onBulkCopy(selectedRows);
      return;
    }
    // Default copy to clipboard
    try {
      const data = selectedRows.map((row) => row.original as unknown);
      const jsonString = JSON.stringify(data, null, 2);
      if (navigator.clipboard) {
        navigator.clipboard.writeText(jsonString).catch(() => {
          /* ignore clipboard errors */
        });
      }
    } catch {
      /* ignore clipboard errors */
    }
  }, [selectedRows, onBulkCopy]);

  // Close bulk actions (alias for clearSelection)
  const closeBulkActions = useCallback(() => {
    clearSelection();
  }, [clearSelection]);

  return {
    selectedRows,
    selectedCount: selectedRows.length,
    showBulkActions,
    handleBulkEdit,
    handleBulkDelete,
    handleBulkCopy,
    clearSelection,
    closeBulkActions,
  };
}

/**
 * Default bulk action handlers
 *
 * Provides basic implementations for common bulk actions
 */
/**
 * Default bulk action handlers (no-op / silent).
 * Apps should provide their own handlers for user feedback (toast, modal, etc.).
 */
export const defaultBulkActions = {
  onBulkEdit: <TData>(_rows: Row<TData>[]) => {
    /* Provide onBulkEdit in table config for custom behavior */
  },

  onBulkDelete: <TData>(rows: Row<TData>[]) => {
    /* Provide onBulkDelete in table config; consider confirmation UI in app */
    if (rows.length > 0) {
      /* no-op unless app provides handler */
    }
  },

  onBulkCopy: <TData>(rows: Row<TData>[]) => {
    try {
      const data = rows.map((row) => row.original);
      const jsonString = JSON.stringify(data, null, 2);
      if (navigator.clipboard) {
        navigator.clipboard.writeText(jsonString).catch(() => {
          /* ignore clipboard errors */
        });
      } else {
        const textArea = document.createElement("textarea");
        textArea.value = jsonString;
        document.body.appendChild(textArea);
        textArea.select();
        document.execCommand("copy");
        document.body.removeChild(textArea);
      }
    } catch {
      /* ignore clipboard errors */
    }
  },
};

/**
 * Hook for managing bulk edit operations
 */
"use client";

import { useQueryClient } from "@tanstack/react-query";
import type { Row } from "@tanstack/react-table";
import { useAtom } from "jotai";
import { useCallback, useMemo } from "react";
import { toast } from "sonner";
import { z } from "zod";
import {
  type CatalogueFormState,
  catalogueFormAtom,
  openUpdateForm,
} from "../components/forms/atoms/catalogue-form-atoms";

/**
 * Configuration for bulk edit
 */
interface BulkEditConfig<TData> {
  /**
   * Table ID for form configuration
   */
  tableId: string;

  /**
   * Form type for bulk edit (defaults to tableId + '-bulk')
   */
  formType?: string;

  /**
   * Custom success handler
   */
  onSuccess?: (updatedData: Partial<TData>, selectedRows: Row<TData>[]) => void;

  /**
   * Custom API update function
   */
  onUpdate?: (ids: string[], data: Partial<TData>) => Promise<boolean>;
}

/**
 * Return type for the bulk edit hook
 */
interface BulkEditReturn<TData> {
  /**
   * Open bulk edit form for selected rows
   */
  openBulkEdit: (selectedRows: Row<TData>[]) => void;

  /**
   * Whether bulk edit form is currently open
   */
  isBulkEditOpen: boolean;

  /**
   * Close bulk edit form
   */
  closeBulkEdit: () => void;
}

/**
 * Hook to manage bulk edit operations
 *
 * Provides functionality to open a bulk edit form for multiple selected rows
 * and handle the update operation
 */
export function useBulkEdit<TData extends Record<string, unknown>>({
  tableId,
  formType,
  onSuccess,
  onUpdate,
}: BulkEditConfig<TData>): BulkEditReturn<TData> {
  const [formState, setFormState] = useAtom(catalogueFormAtom);
  const queryClient = useQueryClient();

  // Determine the form type for bulk edit
  const bulkFormType = formType || `${tableId}-bulk`;

  // Check if bulk edit form is open
  const isBulkEditOpen = useMemo(() => {
    return (
      formState.isOpen &&
      formState.formType === bulkFormType &&
      formState.mode === "update"
    );
  }, [formState, bulkFormType]);

  // Extract common values from selected rows for initial form data
  const extractCommonValues = useCallback(
    (selectedRows: Row<TData>[]): Record<string, unknown> => {
      if (selectedRows.length === 0) {
        return {};
      }

      const firstRow = selectedRows[0].original;
      const commonData: Record<string, unknown> = {};

      // Find fields that have the same value across all selected rows
      for (const key in firstRow) {
        if (Object.hasOwn(firstRow, key)) {
          const firstValue = firstRow[key];
          const allSameValue = selectedRows.every(
            (row) => row.original[key] === firstValue
          );

          if (allSameValue) {
            commonData[key] = firstValue;
          }
        }
      }

      return commonData as Partial<TData>;
    },
    []
  );

  // Helper function to extract IDs from rows
  const extractRowIds = useCallback((selectedRows: Row<TData>[]): string[] => {
    return selectedRows
      .map((row) => {
        // Try to get ID from different possible fields
        const rowData = row.original;
        return rowData.id || rowData._id || row.id;
      })
      .filter(Boolean) as string[];
  }, []);

  // Helper function to clean form data
  const cleanFormData = useCallback(
    (formData: Partial<TData>): Partial<TData> => {
      const cleanData: Record<string, unknown> = {};

      for (const [key, value] of Object.entries(formData)) {
        if (value !== undefined && value !== "") {
          cleanData[key] = value;
        }
      }

      return cleanData as Partial<TData>;
    },
    []
  );

  // Helper function to perform the update
  const performUpdate = useCallback(
    async (ids: string[], cleanData: Partial<TData>): Promise<boolean> => {
      if (onUpdate) {
        return await onUpdate(ids, cleanData);
      }
      await new Promise((resolve) => setTimeout(resolve, 1000));
      return true;
    },
    [onUpdate]
  );

  // Handle bulk update submission
  const handleBulkUpdate = useCallback(
    async (
      formData: Partial<TData>,
      selectedRows: Row<TData>[]
    ): Promise<boolean> => {
      try {
        const ids = extractRowIds(selectedRows);

        if (ids.length === 0) {
          toast.error("No valid IDs found for update");
          return false;
        }

        const cleanData = cleanFormData(formData);

        if (Object.keys(cleanData).length === 0) {
          toast.error("No changes to apply");
          return false;
        }

        const success = await performUpdate(ids, cleanData);

        if (success) {
          // Invalidate queries to refresh data
          await queryClient.invalidateQueries({
            queryKey: ["tableData", tableId],
          });

          // Call custom success handler
          if (onSuccess) {
            onSuccess(cleanData, selectedRows);
          }

          toast.success(
            `Successfully updated ${ids.length} item${ids.length > 1 ? "s" : ""}`
          );
          return true;
        }

        toast.error("Failed to update items");
        return false;
      } catch (_error) {
        toast.error("Failed to update items");
        return false;
      }
    },
    [
      extractRowIds,
      cleanFormData,
      performUpdate,
      queryClient,
      tableId,
      onSuccess,
    ]
  );

  // Open bulk edit form
  const openBulkEdit = useCallback(
    (selectedRows: Row<TData>[]) => {
      if (selectedRows.length === 0) {
        toast.error("No rows selected");
        return;
      }

      // Extract common values for initial form data
      const commonValues = extractCommonValues(selectedRows);

      // Create initial data with metadata about the bulk operation
      const initialData = {
        ...commonValues,
        _bulkEdit: {
          selectedCount: selectedRows.length,
          selectedIds: selectedRows.map((row) => row.id),
          selectedRows: selectedRows.map((row) => row.original),
        },
      } as Partial<TData> & {
        _bulkEdit: {
          selectedCount: number;
          selectedIds: string[];
          selectedRows: TData[];
        };
      };

      // Create success handler that includes the selected rows
      const handleSuccess = (data: Partial<TData>) => {
        return handleBulkUpdate(data, selectedRows);
      };

      // Create form state for bulk edit
      const newFormState = openUpdateForm(
        bulkFormType,
        tableId,
        initialData,
        handleSuccess
      );

      // Set the form state
      setFormState(
        newFormState as unknown as CatalogueFormState<Record<string, unknown>>
      );
    },
    [bulkFormType, tableId, extractCommonValues, handleBulkUpdate, setFormState]
  );

  // Close bulk edit form
  const closeBulkEdit = useCallback(() => {
    if (isBulkEditOpen) {
      setFormState((prev) => ({
        ...prev,
        isOpen: false,
      }));
    }
  }, [isBulkEditOpen, setFormState]);

  return {
    openBulkEdit,
    isBulkEditOpen,
    closeBulkEdit,
  };
}

/**
 * Helper function to create a permissive Zod schema for bulk edit
 */
function createBulkEditSchema(
  fields: Record<string, unknown>[]
): z.ZodObject<Record<string, z.ZodOptional<z.ZodAny>>> {
  const schemaShape: Record<string, z.ZodOptional<z.ZodAny>> = {};

  for (const field of fields) {
    const fieldName = field.name as string;
    const fieldType = field.type as string;

    // Create optional schema for each field type - all as ZodAny to simplify
    switch (fieldType) {
      case "number":
        schemaShape[fieldName] = z.any().optional();
        break;
      case "boolean":
      case "checkbox":
        schemaShape[fieldName] = z.any().optional();
        break;
      default:
        schemaShape[fieldName] = z.any().optional();
        break;
    }
  }

  return z.object(schemaShape);
}

/**
 * Helper function to create bulk edit form configuration
 */
export function createBulkEditFormConfig(
  baseConfig: Record<string, unknown>,
  options: {
    title?: string;
    description?: string;
    excludeFields?: string[];
    includeFields?: string[];
    uniqueFields?: string[]; // Fields that must remain unique and shouldn't be bulk edited
  } = {}
) {
  const {
    title = "Bulk Edit",
    description = "Edit multiple items at once. Only filled fields will be applied to all selected items. Leave fields empty to keep their current values.",
    excludeFields = ["id", "_id", "createdAt", "updatedAt"],
    includeFields,
    uniqueFields = ["email", "username", "sku", "slug", "code"], // Common unique fields
  } = options;

  // Filter fields for bulk edit
  let fields = (baseConfig.fields as Record<string, unknown>[]) || [];

  // Combine all fields to exclude (standard excludes + unique fields)
  const allExcludeFields = [...excludeFields, ...uniqueFields];

  if (includeFields) {
    fields = fields.filter((field: Record<string, unknown>) =>
      includeFields.includes(field.name as string)
    );
  } else {
    fields = fields.filter(
      (field: Record<string, unknown>) =>
        !allExcludeFields.includes(field.name as string)
    );
  }

  // Make all fields optional for bulk edit with clear placeholders
  fields = fields.map((field: Record<string, unknown>) => ({
    ...field,
    required: false, // Force all fields to be optional
    placeholder: field.placeholder || "Leave empty to keep current value",
    description: field.description || undefined, // Remove field-level description
    validation: undefined, // Remove field-level validation rules
  }));

  const baseTranslations = baseConfig.translations as
    | { keys?: Record<string, string> }
    | undefined;

  // Create a permissive schema for bulk edit
  const bulkEditSchema = createBulkEditSchema(fields);

  return {
    ...baseConfig,
    id: `${baseConfig.id}-bulk`,
    fields,
    schema: bulkEditSchema, // Use permissive schema that makes all fields optional
    defaultValues: {}, // Clear default values - bulk edit should start empty
    translations: {
      ...baseTranslations,
      keys: {
        ...(baseTranslations?.keys || {}),
        "updateForm.title": title,
        "updateForm.description": description,
        update: "Update Selected Items",
        updating: "Updating items...",
        success: "Items updated successfully",
        error: "Failed to update items",
      },
    },
  };
}

/**
 * Integration hook that combines existing useDataTable with advanced filters
 * Provides backward compatibility while adding advanced filtering capabilities
 */

import type { ColumnFiltersState } from "@tanstack/react-table";
import { useCallback, useMemo } from "react";
import type {
  AdvancedFilterModel,
  AdvancedFilterPreset,
  AdvancedFiltersState,
  ColumnDataType,
  ColumnOption,
  ColumnsFilterConfig,
  FilterActions,
  FilterOperators,
  FilterStrategy,
} from "../types/filter-types";
import { useDataTable } from "./use-data-table";
import { useTableUrlState } from "./use-table-url-state";

const DEBUG = false;

// Helper functions
function generateId(): string {
  return Math.random().toString(36).substr(2, 9);
}

// Filter helper functions
function applyTextFilter(value: unknown, filter: AdvancedFilterModel): boolean {
  const textValue = String(value || "").toLowerCase();
  const textFilter = String(filter.values || "").toLowerCase();

  switch (filter.operator) {
    case "contains":
      return textValue.includes(textFilter);
    case "equals":
      return textValue === textFilter;
    case "startsWith":
      return textValue.startsWith(textFilter);
    case "endsWith":
      return textValue.endsWith(textFilter);
    case "notContains":
      return !textValue.includes(textFilter);
    case "isEmpty":
      return !textValue || textValue.trim() === "";
    case "isNotEmpty":
      return Boolean(textValue && textValue.trim() !== "");
    default:
      return true;
  }
}

function applyNumberFilter(
  value: unknown,
  filter: AdvancedFilterModel
): boolean {
  const numValue = Number(value);
  const numFilter = Number(filter.values);

  switch (filter.operator) {
    case "equals":
      return numValue === numFilter;
    case "greaterThan":
      return numValue > numFilter;
    case "lessThan":
      return numValue < numFilter;
    case "greaterThanOrEqual":
      return numValue >= numFilter;
    case "lessThanOrEqual":
      return numValue <= numFilter;
    case "notEquals":
      return numValue !== numFilter;
    case "between":
      if (Array.isArray(filter.values) && filter.values.length === 2) {
        const min = Number(filter.values[0]);
        const max = Number(filter.values[1]);
        return numValue >= min && numValue <= max;
      }
      return true;
    case "isEmpty":
      return value == null || value === "";
    case "isNotEmpty":
      return value != null && value !== "";
    default:
      return true;
  }
}

function applyOptionFilter(
  value: unknown,
  filter: AdvancedFilterModel
): boolean {
  switch (filter.operator) {
    case "is":
      return value === filter.values;
    case "isAnyOf":
      return (
        Array.isArray(filter.values) &&
        (filter.values as unknown[]).includes(value)
      );
    case "isNot":
      return value !== filter.values;
    case "isNoneOf":
      return (
        Array.isArray(filter.values) &&
        !(filter.values as unknown[]).includes(value)
      );
    case "isEmpty":
      return value == null || value === "";
    case "isNotEmpty":
      return value != null && value !== "";
    default:
      return true;
  }
}

// Helper function for date filtering
const applyDateFilter = (
  value: unknown,
  filter: AdvancedFilterModel
): boolean => {
  const dateValue =
    value instanceof Date ? value : new Date(value as string | number);
  const dateFilter =
    filter.values instanceof Date
      ? filter.values
      : new Date(filter.values as string | number);

  switch (filter.operator) {
    case "equals":
      return dateValue.getTime() === dateFilter.getTime();
    case "greaterThan":
      return dateValue > dateFilter;
    case "lessThan":
      return dateValue < dateFilter;
    case "greaterThanOrEqual":
      return dateValue >= dateFilter;
    case "lessThanOrEqual":
      return dateValue <= dateFilter;
    case "between":
      if (Array.isArray(filter.values) && filter.values.length === 2) {
        const startDate = new Date(filter.values[0] as string | number);
        const endDate = new Date(filter.values[1] as string | number);
        return dateValue >= startDate && dateValue <= endDate;
      }
      return true;
    case "isEmpty":
      return value == null;
    case "isNotEmpty":
      return value != null;
    default:
      return true;
  }
};

// Helper function for fallback filtering (backward compatibility)
const applyFallbackFilter = (
  value: unknown,
  filter: AdvancedFilterModel
): boolean => {
  switch (filter.operator) {
    case "contains":
      return String(value)
        .toLowerCase()
        .includes(String(filter.values).toLowerCase());
    case "equals":
    case "is":
      return value === filter.values;
    default:
      return true;
  }
};

function applyFilters<TData>(
  data: TData[],
  filters: AdvancedFilterModel[],
  accessors: Record<string, (row: TData) => unknown>
): TData[] {
  if (!filters.length) {
    return data;
  }

  return data.filter((row) => {
    return filters.every((filter) => {
      if (!filter.isActive) {
        return true;
      }

      const accessor = accessors[filter.columnId];
      if (!accessor) {
        return true;
      }

      const value = accessor(row);

      // Enhanced filtering logic using helper functions
      switch (filter.type) {
        case "text":
          return applyTextFilter(value, filter);
        case "number":
          return applyNumberFilter(value, filter);
        case "option":
        case "multiOption":
          return applyOptionFilter(value, filter);
        case "date":
          return applyDateFilter(value, filter);
        default:
          return applyFallbackFilter(value, filter);
      }
    });
  });
}

function computeFacetedData(
  _data: unknown[],
  _columnsConfig: ColumnsFilterConfig,
  _accessors: Record<string, (row: unknown) => unknown>
): Record<string, unknown> {
  // Simple implementation - just return empty for now
  return {};
}

export interface UseDataTableAdvancedFiltersOptions<
  TData = Record<string, unknown>,
> {
  /** Table identifier */
  tableType: string;
  /** Filter strategy - client or server */
  strategy?: FilterStrategy;
  /** Data to filter (for client-side filtering) */
  data?: TData[];
  /** Advanced columns configuration */
  advancedColumnsConfig?: ColumnsFilterConfig;
  /** Column accessors for data extraction */
  accessors?: Record<string, (row: TData) => unknown>;
  /** Auto-compute faceted data */
  autoComputeFaceted?: boolean;
}

export interface UseDataTableAdvancedFiltersReturn<
  TData = Record<string, unknown>,
> {
  // Original useDataTable return values
  columnFilters: ColumnFiltersState;
  setColumnFilters: (state: ColumnFiltersState) => void;

  // Advanced filters values
  advancedFilters: AdvancedFiltersState;
  advancedActions: FilterActions;
  filteredData: TData[];
  hasAdvancedFilters: boolean;
  activeAdvancedFiltersCount: number;

  // Combined state
  hasAnyFilters: boolean;
  totalActiveFiltersCount: number;

  // Utility functions
  clearAllFilters: () => void;
  convertLegacyToAdvanced: (columnId: string, type: ColumnDataType) => void;
}

/**
 * Hook that integrates existing table filtering with advanced filters using URL state
 */
export function useDataTableAdvancedFilters<TData = Record<string, unknown>>(
  options: UseDataTableAdvancedFiltersOptions<TData>
): UseDataTableAdvancedFiltersReturn<TData> {
  const {
    tableType,
    strategy = "client",
    data = [],
    advancedColumnsConfig = {},
    accessors = {},
    autoComputeFaceted = true,
  } = options;

  // Use existing data table hook for backward compatibility
  const dataTableResult = useDataTable({ tableType });
  const { setColumnFilters } = dataTableResult;
  const columnFilters = dataTableResult.state.columnFilters;

  // Use URL state for advanced filters
  const {
    advancedFiltersParam,
    setAdvancedFiltersFromUI,
    resetAdvancedFilters,
  } = useTableUrlState({ tableId: tableType });

  // Advanced filters from URL state
  const advancedFilters = advancedFiltersParam || [];

  if (DEBUG) {
    // Debug log for advanced filters
  }

  // Apply client-side filtering
  const filteredData = useMemo(() => {
    if (strategy === "server" || !data.length || !advancedFilters.length) {
      return data;
    }

    return applyFilters(data, advancedFilters, accessors);
  }, [data, advancedFilters, accessors, strategy]);

  // Compute faceted data for options
  const _facetedData = useMemo(() => {
    if (!(autoComputeFaceted && data.length)) {
      return {};
    }

    return computeFacetedData(
      data,
      advancedColumnsConfig,
      accessors as Record<string, (row: unknown) => unknown>
    );
  }, [data, advancedColumnsConfig, accessors, autoComputeFaceted]);

  // Advanced filter actions using URL state
  const advancedActions: FilterActions = useMemo(
    () => ({
      addFilter: (
        filterData: Omit<AdvancedFilterModel, "id" | "createdAt" | "updatedAt">
      ) => {
        const now = new Date();
        const newFilter: AdvancedFilterModel = {
          ...filterData,
          id: generateId(),
          label: filterData.label || filterData.columnId,
          createdAt: now,
          updatedAt: now,
        };

        const newFilters = [...advancedFilters, newFilter];
        setAdvancedFiltersFromUI(newFilters);
      },

      updateFilter: (
        filterId: string,
        updates: Partial<AdvancedFilterModel>
      ) => {
        const newFilters = advancedFilters.map((filter) =>
          filter.id === filterId
            ? { ...filter, ...updates, updatedAt: new Date() }
            : filter
        );
        setAdvancedFiltersFromUI(newFilters);
      },

      removeFilter: (filterId: string) => {
        const newFilters = advancedFilters.filter(
          (filter) => filter.id !== filterId
        );
        setAdvancedFiltersFromUI(newFilters);
      },

      toggleFilter: (filterId: string) => {
        const newFilters = advancedFilters.map((filter) =>
          filter.id === filterId
            ? { ...filter, isActive: !filter.isActive, updatedAt: new Date() }
            : filter
        );
        setAdvancedFiltersFromUI(newFilters);
      },

      clearFilters: () => {
        resetAdvancedFilters();
      },

      applyPreset: (_preset: AdvancedFilterPreset) => {
        // TODO: Implement preset functionality
      },

      savePreset: (name: string, description?: string) => {
        // TODO: Implement preset functionality
        return {
          id: generateId(),
          name,
          description,
          filters: advancedFilters,
          createdAt: new Date(),
          updatedAt: new Date(),
          tags: [],
          isPublic: false,
        };
      },
    }),
    [advancedFilters, setAdvancedFiltersFromUI, resetAdvancedFilters]
  );

  // Convert legacy filter to advanced filter
  const convertLegacyToAdvanced = useCallback(
    (columnId: string, type: ColumnDataType) => {
      const existingLegacyFilter = columnFilters.find(
        (f: { id: string }) => f.id === columnId
      );
      if (!existingLegacyFilter) {
        return;
      }

      // Remove from legacy filters
      setColumnFilters(
        columnFilters.filter((f: { id: string }) => f.id !== columnId)
      );

      // Add to advanced filters
      let value:
        | string
        | number
        | Date
        | string[]
        | [number, number]
        | [Date, Date] = "";
      let operator: FilterOperators[ColumnDataType] = "contains";

      switch (type) {
        case "text":
          value = String(existingLegacyFilter.value || "");
          operator = "contains" as FilterOperators["text"];
          break;
        case "number":
          value = Number(existingLegacyFilter.value) || 0;
          operator = "equals" as FilterOperators["number"];
          break;
        case "date":
          value =
            existingLegacyFilter.value instanceof Date
              ? existingLegacyFilter.value
              : new Date();
          operator = "equals" as FilterOperators["date"];
          break;
        case "option":
          value = String(existingLegacyFilter.value || "");
          operator = "is" as FilterOperators["option"];
          break;
        case "multiOption":
          value = Array.isArray(existingLegacyFilter.value)
            ? (existingLegacyFilter.value as string[])
            : [];
          operator = "contains" as FilterOperators["multiOption"];
          break;
        default:
          // Handle unknown column types as text
          value = String(existingLegacyFilter.value || "");
          operator = "contains" as FilterOperators["text"];
          break;
      }

      advancedActions.addFilter({
        columnId,
        type,
        operator,
        values: value,
        isActive: true,
      });
    },
    [columnFilters, setColumnFilters, advancedActions]
  );

  // Clear all filters (both legacy and advanced)
  const clearAllFilters = useCallback(() => {
    setColumnFilters([]);
    advancedActions.clearFilters();
  }, [setColumnFilters, advancedActions]);

  // Calculate combined state
  const hasAdvancedFilters = advancedFilters.length > 0;
  const activeAdvancedFiltersCount = advancedFilters.filter(
    (f) => f.isActive
  ).length;
  const hasLegacyFilters = columnFilters.length > 0;
  const hasAnyFilters = hasAdvancedFilters || hasLegacyFilters;
  const totalActiveFiltersCount =
    activeAdvancedFiltersCount + columnFilters.length;

  return {
    // Legacy compatibility
    columnFilters,
    setColumnFilters,

    // Advanced filters
    advancedFilters,
    advancedActions,
    filteredData,
    hasAdvancedFilters,
    activeAdvancedFiltersCount,

    // Combined state
    hasAnyFilters,
    totalActiveFiltersCount,

    // Utilities
    clearAllFilters,
    convertLegacyToAdvanced,
  };
}

// Helper function to check if column is a system column
const isSystemColumn = (columnId: string): boolean => {
  return columnId === "select" || columnId === "actions";
};

// Helper function to get operators by column type
const getOperatorsByType = (
  type: ColumnDataType
): FilterOperators[ColumnDataType][] => {
  const operatorMap: Record<ColumnDataType, FilterOperators[ColumnDataType][]> =
    {
      option: [
        "is",
        "isAnyOf",
        "isNot",
        "isEmpty",
        "isNotEmpty",
      ] as FilterOperators["option"][],
      text: [
        "contains",
        "equals",
        "startsWith",
        "endsWith",
        "notContains",
        "isEmpty",
        "isNotEmpty",
      ] as FilterOperators["text"][],
      number: [
        "equals",
        "greaterThan",
        "lessThan",
        "greaterThanOrEqual",
        "lessThanOrEqual",
        "between",
        "notEquals",
        "isEmpty",
        "isNotEmpty",
      ] as FilterOperators["number"][],
      date: [
        "equals",
        "before",
        "after",
        "between",
        "notEquals",
        "isEmpty",
        "isNotEmpty",
      ] as FilterOperators["date"][],
      multiOption: [
        "contains",
        "containsAll",
        "containsNone",
        "isEmpty",
        "isNotEmpty",
      ] as FilterOperators["multiOption"][],
    };
  return operatorMap[type] || [];
};

// Helper function to create column configuration
const createColumnConfig = (
  column: {
    id: string;
    label: string;
    canFilter?: boolean;
    [key: string]: unknown;
  },
  type: ColumnDataType
) => {
  const baseConfig = {
    type,
    filterable: column.canFilter !== false,
    faceted: type === "option" || type === "multiOption",
    placeholder: String(column.placeholder) || `Filter by ${column.label}...`,
    ...(column.description ? { description: String(column.description) } : {}),
  };

  // Type-specific configurations
  const typeConfigs = {
    number: {
      min: Number(column.min) || 0,
      max: Number(column.max) || 10_000,
      operators: getOperatorsByType("number"),
    },
    option: {
      options: (Array.isArray(column.options)
        ? column.options
        : getOptionsForColumn(column.id, type)) as ColumnOption[],
      operators: getOperatorsByType("option"),
    },
    text: {
      operators: getOperatorsByType("text"),
    },
    date: {
      operators: getOperatorsByType("date"),
    },
    multiOption: {
      options: (Array.isArray(column.options)
        ? column.options
        : getOptionsForColumn(column.id, type)) as ColumnOption[],
      operators: getOperatorsByType("multiOption"),
    },
  };

  return {
    ...baseConfig,
    ...(typeConfigs[type] || {}),
  };
};

export function useColumnsFilterConfig(
  columns: Array<{
    id: string;
    label: string;
    canFilter?: boolean;
    [key: string]: unknown;
  }>,
  typeMapping: Record<string, ColumnDataType> = {}
): ColumnsFilterConfig {
  return useMemo(() => {
    const config: ColumnsFilterConfig = {};
    for (const column of columns) {
      // Skip system columns
      if (isSystemColumn(column.id)) {
        continue;
      }

      const type = typeMapping[column.id] || "text";
      config[column.id] = createColumnConfig(column, type);
    }
    return config;
  }, [columns, typeMapping]);
}

// Helper function to get options for option-type columns
function getOptionsForColumn(
  columnId: string,
  type: ColumnDataType
): ColumnOption[] | undefined {
  if (type !== "option") {
    return;
  }

  // Static options for our example - using consistent {value, label} format
  switch (columnId) {
    case "category":
      return [
        { value: "Laptops", label: "Laptops" },
        { value: "Phones", label: "Phones" },
        { value: "Tablets", label: "Tablets" },
        { value: "Accessories", label: "Accessories" },
      ];
    case "status":
      return [
        { value: "In Stock", label: "In Stock" },
        { value: "Low Stock", label: "Low Stock" },
        { value: "Out of Stock", label: "Out of Stock" },
      ];
    case "isActive":
      return [
        { value: "true", label: "Active" },
        { value: "false", label: "Inactive" },
      ];
    default:
      return;
  }
}

/**
 * Helper hook for creating accessors from table data
 */
export function useTableAccessors<TData = Record<string, unknown>>(
  _data: TData[],
  columnIds: string[]
): Record<string, (row: TData) => unknown> {
  return useMemo(() => {
    const accessors: Record<string, (row: TData) => unknown> = {};

    for (const columnId of columnIds) {
      accessors[columnId] = (row: TData) => {
        // Handle nested property access like "user.name"
        if (columnId.includes(".")) {
          return columnId
            .split(".")
            .reduce(
              (obj: unknown, key) => (obj as Record<string, unknown>)?.[key],
              row
            );
        }
        // Simple property access
        return (row as Record<string, unknown>)[columnId];
      };
    }

    return accessors;
  }, [columnIds]);
}

/**
 * Type guard to check if filters are advanced filters
 */
export function isAdvancedFiltersState(
  filters: ColumnFiltersState | AdvancedFiltersState
): filters is AdvancedFiltersState {
  return (
    Array.isArray(filters) &&
    filters.length > 0 &&
    typeof filters[0] === "object" &&
    "type" in filters[0] &&
    "operator" in filters[0]
  );
}

/**
 * Main hook for data tables - Orchestrates configuration, actions, and data fetching
 * Refactored to use extracted hooks for better maintainability
 */
"use client";

import { useQueryClient } from "@tanstack/react-query";
import {
  type ColumnDef,
  type ColumnFilter,
  type ColumnSort,
  getCoreRowModel,
  getFilteredRowModel,
  getPaginationRowModel,
  getSortedRowModel,
  type OnChangeFn,
  type PaginationState,
  useReactTable,
  type VisibilityState,
} from "@tanstack/react-table";
import type * as React from "react";
import { useCallback, useMemo } from "react";

import type { ActionsColumnProps } from "../components/columns/actions-column";
import { useColumns } from "../components/columns/hooks/use-columns";
import { useTranslations } from "../providers/table-provider";
import { useTableActions } from "./use-table-actions";
import { useTableConfig } from "./use-table-config";
import { useTableUrlData } from "./use-table-url-data";
import { useTableUrlState } from "./use-table-url-state";

const DEBUG = false;

/**
 * Options for the useDataTable hook
 */
export interface UseDataTableOptions<_TData = Record<string, unknown>> {
  /**
   * Whether to enable data fetching
   * Defaults to true
   */
  enabled?: boolean;

  /**
   * Initial page size
   * Defaults to 10
   */
  initialPageSize?: number;

  /**
   * Unique identifier for this table instance
   * Defaults to tableType if not provided
   */
  tableId?: string;

  /**
   * Type of table to use (corresponds to a key in the table catalogue)
   */
  tableType: string;
}

/**
 * Main hook for data tables
 * @param options Configuration options
 * @returns Everything needed to render a data table
 */
export function useDataTable<TData extends Record<string, unknown>>(
  options: UseDataTableOptions<TData>
) {
  const {
    enabled = true,
    initialPageSize: _initialPageSize = 10,
    tableType,
    tableId = tableType,
  } = options;

  // Get QueryClient instance
  const queryClient = useQueryClient();

  // Get table configuration using extracted hook
  const { config, translations } = useTableConfig(tableType);

  // Debug removed
  const { t } = useTranslations();

  // Set up URL state for the table
  const tableUrlState = useTableUrlState({ tableId });

  // Create a function to invalidate table data
  const invalidateTable = useCallback(async () => {
    await queryClient.invalidateQueries({
      queryKey: ["tableData", tableId],
    });
  }, [queryClient, tableId]);

  // Get table actions using extracted hook (before queryFn to avoid circular reference)
  const {
    actions,
    handleCreate,
    handleEdit,
    handleDelete,
    handleDuplicate,
    hasAction: _hasAction,
    isActionsAvailable: _isActionsAvailable,
  } = useTableActions<TData>({
    tableType,
    onSuccess: async () => {
      // This will be defined later
      tableUrlState.setPageParam("0");
      await invalidateTable();
    },
  });

  // Get table state from URL parameters with proper type assertions
  const columnFilters = (tableUrlState.filtersParam || []) as ColumnFilter[];
  const { pagination } = tableUrlState;

  // Helper function to build orderBy parameter
  const buildOrderByParam = useCallback((sortingParam: unknown) => {
    if (!Array.isArray(sortingParam) || sortingParam.length === 0) {
      return;
    }

    const sortItem = sortingParam[0] as { id: string; desc?: boolean };
    const sortField = sortItem.id;
    const sortDirection = sortItem.desc ? "desc" : "asc";
    const orderBy = { [sortField]: sortDirection };
    return orderBy;
  }, []);

  // Helper function to clean column filters
  const cleanColumnFilters = useCallback((columnFiltersParam: unknown) => {
    const columnFiltersTyped = (columnFiltersParam || []) as Array<{
      id: string;
      value: unknown;
    }>;

    return Object.fromEntries(
      columnFiltersTyped
        .filter(
          (filter: { id: string; value: unknown }) =>
            !["id", "key"].includes(filter.id)
        )
        .map((filter: { id: string; value: unknown }) => [
          filter.id,
          filter.value,
        ])
    );
  }, []);

  // Helper function to build request parameters
  const buildRequestParams = useCallback(
    (
      cleanedFilters: Record<string, unknown>,
      paginationTyped: { pageSize?: number; pageIndex?: number } | undefined,
      orderByParam: Record<string, string> | undefined,
      advancedFilters?: unknown
    ) => {
      const requestParams = {
        filters: cleanedFilters,
        advancedFilters: advancedFilters || [],
        limit: paginationTyped?.pageSize || 10,
        orderBy: orderByParam,
        page: (paginationTyped?.pageIndex || 0) + 1,
      };
      return requestParams;
    },
    []
  );

  // Create query function
  const queryFn = useCallback(
    async (params: Record<string, unknown>) => {
      const {
        columnFilters: _paramsColumnFilters,
        complexFilters: _complexFilters,
        advancedFilters: paramsAdvancedFilters,
        globalSearch: paramsGlobalSearch,
        pagination: _paramsPagination,
        sorting: paramsSorting,
      } = params;

      // Type the pagination object properly
      const paginationTyped = pagination as
        | { pageSize?: number; pageIndex?: number }
        | undefined;

      try {
        const orderBy = buildOrderByParam(paramsSorting);
        const cleanedFilters = cleanColumnFilters(columnFilters);
        const requestParams = buildRequestParams(
          cleanedFilters,
          paginationTyped,
          orderBy,
          paramsAdvancedFilters
        );

        // Attach global search if present (server-side global filter)
        if (paramsGlobalSearch && typeof paramsGlobalSearch === "string") {
          (requestParams as Record<string, unknown>).search =
            paramsGlobalSearch;
        }

        // Execute the request - safely handle the list action
        if (actions.list) {
          const response = await actions.list(requestParams);
          return {
            data: (response.data || []) as TData[],
            pageCount: response.meta?.pageCount || 1,
            rowCount: response.meta?.totalCount || response.data?.length || 0,
          };
        }
        return { data: [] as TData[], pageCount: 0, rowCount: 0 };
      } catch (_error) {
        return { data: [] as TData[], pageCount: 0, rowCount: 0 };
      }
    },
    [
      actions,
      columnFilters,
      pagination,
      buildOrderByParam,
      cleanColumnFilters,
      buildRequestParams,
    ]
  );

  // Use the tableUrlData hook for proper API data fetching
  const urlDataResult = useTableUrlData<TData>({
    enabled,
    queryFn,
    tableId,
  });

  // Extract data and state from API
  const data = urlDataResult?.data || [];
  const error = urlDataResult?.error;
  const isError = urlDataResult?.isError;
  const isLoading = urlDataResult?.isLoading;
  const baseRefetch = urlDataResult?.refetch || (() => Promise.resolve());
  const rowCount = urlDataResult?.rowCount || 0;
  const rowSelection = urlDataResult?.rowSelection || {};
  const setRowSelection =
    urlDataResult?.setRowSelection ||
    (() => {
      // No-op implementation
    });

  // Get table state from URL parameters with proper type assertions
  const columnOrder = (tableUrlState.orderParam || []) as string[];
  const sorting = (tableUrlState.sortParam || []) as ColumnSort[];

  // Compute column visibility: when URL has no visibility state, derive it
  // from config.columns.visible so columns in order/definitions but NOT in
  // visible are hidden by default.
  const columnVisibility = useMemo<VisibilityState>(() => {
    const urlVisibility = (tableUrlState.visibilityParam ||
      {}) as VisibilityState;

    // If URL already has explicit visibility state, use it as-is
    if (Object.keys(urlVisibility).length > 0) {
      return urlVisibility;
    }

    const visibleList = config.columns.visible;

    // If no visible list is configured, fall back to everything visible
    if (!visibleList || visibleList.length === 0) {
      return {};
    }

    const visibleSet = new Set(visibleList);
    const visibility: VisibilityState = {};

    // Walk every defined column and mark those absent from visible as hidden
    for (const colDef of config.columns.definitions) {
      const colId = colDef.id;
      // Special columns (select, actions) are always visible
      if (colId === "select" || colId === "actions") {
        visibility[colId] = true;
        continue;
      }
      visibility[colId] = visibleSet.has(colId);
    }

    // Select column is not in definitions; ensure it is visible when row selection is enabled
    if (config.table.enableRowSelection) {
      visibility.select = true;
    }

    return visibility;
  }, [
    tableUrlState.visibilityParam,
    config.columns.visible,
    config.columns.definitions,
    config.table.enableRowSelection,
  ]);

  // Enhanced refetch function that resets pagination and invalidates queries
  const enhancedRefetch = useCallback(async () => {
    tableUrlState.setPageParam("0");
    await invalidateTable();
    await baseRefetch();
  }, [tableUrlState, invalidateTable, baseRefetch]);

  // Use our columns hook to define columns in a modular way
  const { column, createColumns } = useColumns<TData>({
    enableSelection: config.table.enableRowSelection,
    tableId,
  });

  // Create a safe translation helper
  const getTranslationSafe = useCallback(
    (key: string): string => {
      // Try to use the t function first for any translation key
      try {
        return t(key);
      } catch {
        // If that fails, return the key itself as fallback
        return key;
      }
    },
    [t]
  );

  // Create columns based on configuration
  const columns = useMemo(() => {
    const columnDefs: ColumnDef<TData>[] = [];

    // Add selection column if enabled
    if (config.table.enableRowSelection) {
      // Use the selection column from the columns hook
      columnDefs.push(column.selection());
    }

    // Add columns from configuration
    for (const colDef of config.columns.definitions) {
      switch (colDef.type) {
        case "actions":
          columnDefs.push(
            column.actions({
              header: t("actions.title"),
              includeDelete: true,
              includeEdit: true,
              onDelete: async (row: TData) => {
                return await handleDelete(row as TData & { id: string });
              },
              onEdit: async (row: TData) => {
                return await handleEdit(row as TData & { id: string }, {});
              },
              onRefresh: async () => {
                await enhancedRefetch();
              },
              tableId,
            } as ActionsColumnProps<TData>)
          );
          break;
        case "boolean":
          columnDefs.push(
            column.boolean(colDef.id as keyof TData, {
              enableColumnFilter: colDef.enableColumnFilter,
              enableSorting: colDef.enableSorting,
              header: getTranslationSafe(colDef.header),
            })
          );
          break;
        case "code":
          columnDefs.push(
            column.code(colDef.id as keyof TData, {
              enableColumnFilter: colDef.enableColumnFilter,
              enableSorting: colDef.enableSorting,
              header: getTranslationSafe(colDef.header),
            })
          );
          break;
        case "date":
          columnDefs.push(
            column.date(colDef.id as keyof TData, {
              enableColumnFilter: colDef.enableColumnFilter,
              enableSorting: colDef.enableSorting,
              header: getTranslationSafe(colDef.header),
            })
          );
          break;
        case "dynamicType":
          // Use dynamic type column that renders based on the type in the specified typeKey
          columnDefs.push(
            column.dynamicType(
              colDef.id as keyof TData,
              colDef.typeKey as keyof TData,
              {
                // Pass any custom renderers if defined (with proper typing)
                customRenderers: colDef.customRenderers as
                  | Record<string, (value: unknown) => React.ReactNode>
                  | undefined,
                enableSorting: colDef.enableSorting,
                header: getTranslationSafe(colDef.header),
              }
            )
          );
          break;
        case "number":
          // Use number column for proper number formatting
          columnDefs.push(
            column.number(colDef.id as keyof TData, {
              enableColumnFilter: colDef.enableColumnFilter,
              enableSorting: colDef.enableSorting,
              header: getTranslationSafe(colDef.header),
            })
          );
          break;
        case "tag":
          columnDefs.push(
            column.tag(colDef.id as keyof TData, {
              enableColumnFilter: colDef.enableColumnFilter,
              enableSorting: colDef.enableSorting,
              header: getTranslationSafe(colDef.header),
            })
          );
          break;
        case "text":
          columnDefs.push(
            column.text(colDef.id as keyof TData, {
              enableColumnFilter: colDef.enableColumnFilter,
              enableSorting: colDef.enableSorting,
              header: getTranslationSafe(colDef.header),
            })
          );
          break;
        // Add more column types as needed
        default:
          // Default to text column
          columnDefs.push(
            column.text(colDef.id as keyof TData, {
              enableColumnFilter: colDef.enableColumnFilter,
              enableSorting: colDef.enableSorting,
              header: getTranslationSafe(colDef.header),
            })
          );
      }
    }

    // Add actions column if not already added
    if (!columnDefs.some((col) => "id" in col && col.id === "actions")) {
      columnDefs.push(
        column.actions({
          header: t("actions.title"),
          includeDelete: true,
          includeDuplicate: !!actions.duplicate,
          includeEdit: true,
          includeView: true,
          onDelete: async (row: TData) => {
            return await handleDelete(row as TData & { id: string });
          },
          onDuplicate: actions.duplicate
            ? async (row: TData) => {
                return await handleDuplicate(row as TData & { id: string });
              }
            : undefined,
          onEdit: async (row: TData) => {
            return await handleEdit(row as TData & { id: string }, {});
          },
          onRefresh: async () => {
            await enhancedRefetch();
          },
          onView: (_row: TData) => {
            // Placeholder for view action - to be implemented later
            if (DEBUG) {
              // Debug log for view action placeholder
            }
            // We'll return true to indicate success even though we're not doing anything yet
            return Promise.resolve(true);
          },
          tableId,
        } as ActionsColumnProps<TData>)
      );
    }

    return createColumns(columnDefs);
  }, [
    column,
    config.columns.definitions,
    config.table.enableRowSelection,
    createColumns,
    enhancedRefetch,
    t,
    getTranslationSafe,
    actions.duplicate,
    handleDelete,
    handleEdit,
    handleDuplicate,
    tableId,
  ]);

  // Helper function to determine column label
  const getColumnLabel = useCallback(
    (colDef: ColumnDef<TData>): string => {
      if (colDef.id === "select") {
        return t("common.selection");
      }
      if (colDef.id === "actions") {
        return t("actions.title");
      }
      if (typeof colDef.header === "string") {
        return getTranslationSafe(colDef.header);
      }
      // For function headers or fallback, use the column ID and try to translate it
      return getTranslationSafe(colDef.id || "Column");
    },
    [t, getTranslationSafe]
  );

  // Create formatted column metadata for the TableOptionsMenu
  const columnOptions = useMemo(() => {
    return columns.map((col) => {
      const colDef = col as ColumnDef<TData>;

      return {
        canFilter: colDef.enableColumnFilter !== false,
        canHide: colDef.enableHiding !== false,
        canSort: colDef.enableSorting !== false,
        id: colDef.id || "unknown",
        label: getColumnLabel(colDef),
      };
    });
  }, [columns, getColumnLabel]);

  // Create table instance with configuration
  const table = useReactTable({
    columns,
    data: data || [],
    enableColumnFilters: config.table.enableColumnFilters,
    enableMultiRowSelection: true,
    enableRowSelection: true,
    enableSorting: config.table.enableSorting,
    getCoreRowModel: getCoreRowModel(),
    getFilteredRowModel: getFilteredRowModel(),
    getPaginationRowModel: getPaginationRowModel(),
    getSortedRowModel: getSortedRowModel(),
    manualFiltering: config.table.manualFiltering,
    manualPagination: config.table.manualPagination,
    manualSorting: config.table.manualSorting,
    onColumnFiltersChange: tableUrlState.setColumnFiltersFromUI as OnChangeFn<
      typeof columnFilters
    >,
    onColumnOrderChange: tableUrlState.setOrderFromUI as OnChangeFn<
      typeof columnOrder
    >,
    onColumnVisibilityChange: tableUrlState.setVisibilityFromUI as OnChangeFn<
      typeof columnVisibility
    >,
    onPaginationChange:
      tableUrlState.setPaginationFromUI as OnChangeFn<PaginationState>,
    onRowSelectionChange: setRowSelection,
    onSortingChange: tableUrlState.setSorting as OnChangeFn<typeof sorting>,
    pageCount: Math.ceil(rowCount / pagination.pageSize),
    state: {
      columnFilters,
      columnOrder,
      columnVisibility,
      pagination,
      rowSelection,
      sorting,
    },
  });

  // Return everything needed to render a data table
  return {
    // Table actions
    actions: {
      create: handleCreate,
      delete: handleDelete,
      edit: handleEdit,
      invalidateTable,
      refresh: enhancedRefetch,
    },

    // Column configuration
    columnOptions,

    columns,
    // Table configuration
    config,

    // URL state utilities
    createShareableUrl: tableUrlState.createShareableUrl,

    // Table data
    data,
    error,
    // Data actions
    handleCreate,
    handleDelete,
    handleEdit,
    isError,
    isLoading,
    pageCount: Math.ceil(rowCount / pagination.pageSize),

    refetch: enhancedRefetch,
    resetFilters: tableUrlState.resetFilters,
    resetUrlState: tableUrlState.resetUrlState,
    rowCount,
    rowSelection,
    // Table state
    setColumnFilters: tableUrlState.setColumnFiltersFromUI as OnChangeFn<
      typeof columnFilters
    >,
    setColumnVisibility: tableUrlState.setVisibilityFromUI as OnChangeFn<
      typeof columnVisibility
    >,
    setGrouping: tableUrlState.setGroupingFromUI,

    setPageIndex: (pageIndex: number) =>
      tableUrlState.setPageParam(pageIndex.toString()),
    setPageSize: (pageSize: number) =>
      tableUrlState.setPageSizeParam(pageSize.toString()),
    setRowSelection,

    setSorting: tableUrlState.setSorting as OnChangeFn<typeof sorting>,
    state: {
      columnFilters,
      columnOrder,
      columnVisibility,
      grouping: tableUrlState.groupingParam || [],
      pagination,
      sorting,
    },
    // Table instance
    tableInstance: table,

    // Translations
    translations,

    // Force re-render key when column visibility changes (until atoms are fully synced with URL state)
    visibilityKey: JSON.stringify(columnVisibility),
  };
}

