  comparePresets: (presetA: string, presetB: string) => FilterComparison;

  // Settings
  settings: {
    autoSave: boolean;
    maxRecent: number;
    defaultTags: string[];
    notifications: boolean;
  };
  updateSettings: (
    newSettings: Partial<{
      autoSave: boolean;
      maxRecent: number;
      defaultTags: string[];
      notifications: boolean;
    }>
  ) => void;
}

