/**
 * Main hook for filter presets management
 */
export function useFilterPresets(
  options: UseFilterPresetsOptions
): UseFilterPresetsReturn {
  const {
    tableId,
    enableCloudSync: _enableCloudSync = false,
    maxPresets = 50,
    autoSaveDraft: _autoSaveDraft = true,
    currentUser = "anonymous",
  } = options;

  // State
  const [presets, setPresets] = useState<FilterPreset[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isSaving, setIsSaving] = useState(false);
  const [isDeleting, setIsDeleting] = useState(false);
  const [settings, setSettings] = useState({
    autoSave: true,
    maxRecent: 10,
    defaultTags: ["custom"],
    notifications: true,
  });

  // Storage functions - moved before usage
  const loadPresetsFromStorage = useCallback(() => {
    try {
      setIsLoading(true);
      const stored = localStorage.getItem(`${PRESETS_STORAGE_KEY}_${tableId}`);
      if (stored) {
        const parsed = JSON.parse(stored);
        // Convert date strings back to Date objects
        const presetsWithDates = parsed.map(
          (preset: Record<string, unknown>) => ({
            ...preset,
            metadata: {
              ...(preset.metadata && typeof preset.metadata === "object"
                ? (preset.metadata as Record<string, unknown>)
                : {}),
              createdAt: new Date(
                (preset.metadata as Record<string, unknown>)
                  ?.createdAt as string
              ),
              modifiedAt: new Date(
                (preset.metadata as Record<string, unknown>)
                  ?.modifiedAt as string
              ),
              lastUsed: (preset.metadata as Record<string, unknown>)?.lastUsed
                ? new Date(
                    (preset.metadata as Record<string, unknown>)
                      .lastUsed as string
                  )
                : undefined,
            },
          })
        );
        setPresets(presetsWithDates);
      }
    } catch {
      /* ignore load error */
    } finally {
      setIsLoading(false);
    }
  }, [tableId]);

  const loadSettings = useCallback(() => {
    try {
      const stored = localStorage.getItem(`${SETTINGS_STORAGE_KEY}_${tableId}`);
      if (stored) {
        setSettings({ ...settings, ...JSON.parse(stored) });
      }
    } catch {
      /* ignore parse error */
    }
  }, [tableId, settings]);

  // Load presets from storage on mount
  useEffect(() => {
    loadPresetsFromStorage();
    loadSettings();
  }, [loadPresetsFromStorage, loadSettings]);

  // Computed values
  const systemPresets = useMemo(
    () => [...DEFAULT_SYSTEM_PRESETS, ...presets.filter((p) => p.isSystem)],
    [presets]
  );

  const userPresets = useMemo(
    () => presets.filter((p) => !p.isSystem),
    [presets]
  );

  const recentPresets = useMemo(
    () =>
      [...presets]
        .sort(
          (a, b) =>
            (b.metadata.lastUsed?.getTime() || 0) -
            (a.metadata.lastUsed?.getTime() || 0)
        )
        .slice(0, settings.maxRecent),
    [presets, settings.maxRecent]
  );

  const popularPresets = useMemo(
    () =>
      [...presets]
        .sort((a, b) => b.metadata.usageCount - a.metadata.usageCount)
        .slice(0, 10),
    [presets]
  );

  const savePresetsToStorage = useCallback(
    (newPresets: FilterPreset[]) => {
      try {
        localStorage.setItem(
          `${PRESETS_STORAGE_KEY}_${tableId}`,
          JSON.stringify(newPresets)
        );
      } catch {
        /* ignore save error */
      }
    },
    [tableId]
  );

  // Track usage
  const trackUsage = useCallback((presetId: string) => {
    try {
      const usage = JSON.parse(localStorage.getItem(USAGE_STORAGE_KEY) || "{}");
      usage[presetId] = (usage[presetId] || 0) + 1;
      localStorage.setItem(USAGE_STORAGE_KEY, JSON.stringify(usage));
    } catch {
      /* ignore usage tracking error */
    }
  }, []);

  // Main actions
  const savePreset = useCallback(
    async (
      state: AdvancedFilterState,
      presetOptions: {
        name: string;
        description?: string;
        isPublic?: boolean;
        tags?: string[];
        icon?: string;
        color?: string;
      }
    ): Promise<FilterPreset> => {
      await Promise.resolve(); // Satisfy async linting requirement
      setIsSaving(true);
      try {
        const preset: FilterPreset = {
          id: generatePresetId(),
          name: presetOptions.name,
          description: presetOptions.description,
          icon: presetOptions.icon,
          color: presetOptions.color,
          state,
          isPublic: presetOptions.isPublic ?? false,
          isSystem: false,
          tags: presetOptions.tags || settings.defaultTags,
          metadata: {
            createdBy: currentUser,
            createdAt: new Date(),
            modifiedAt: new Date(),
            usageCount: 0,
            version: "1.0",
          },
        };

        const newPresets = [...presets, preset];

        // Limit number of presets
        if (newPresets.length > maxPresets) {
          // Remove oldest non-system presets
          const sortedPresets = newPresets
            .filter((p) => !p.isSystem)
            .sort(
              (a, b) =>
                a.metadata.createdAt.getTime() - b.metadata.createdAt.getTime()
            );

          const toRemove = sortedPresets.slice(
            0,
            newPresets.length - maxPresets
          );
          const filtered = newPresets.filter((p) => !toRemove.includes(p));
          setPresets(filtered);
          savePresetsToStorage(filtered);
        } else {
          setPresets(newPresets);
          savePresetsToStorage(newPresets);
        }

        return preset;
      } finally {
        setIsSaving(false);
      }
    },
    [
      presets,
      settings.defaultTags,
      currentUser,
      maxPresets,
      savePresetsToStorage,
    ]
  );

  const loadPreset = useCallback(
    async (presetId: string): Promise<AdvancedFilterState> => {
      await Promise.resolve(); // Satisfy async linting requirement
      const preset =
        presets.find((p) => p.id === presetId) ||
        systemPresets.find((p) => p.id === presetId);

      if (!preset) {
        throw new Error(`Preset ${presetId} not found`);
      }

      // Update usage tracking
      trackUsage(presetId);

      // Update last used timestamp
      const updatedPresets = presets.map((p) =>
        p.id === presetId
          ? {
              ...p,
              metadata: {
                ...p.metadata,
                lastUsed: new Date(),
                usageCount: p.metadata.usageCount + 1,
              },
            }
          : p
      );

      setPresets(updatedPresets);
      savePresetsToStorage(updatedPresets);

      return preset.state;
    },
    [presets, systemPresets, trackUsage, savePresetsToStorage]
  );

  const updatePreset = useCallback(
    async (presetId: string, updates: Partial<FilterPreset>): Promise<void> => {
      await Promise.resolve(); // Satisfy async linting requirement
      const updatedPresets = presets.map((preset) =>
        preset.id === presetId
          ? {
              ...preset,
              ...updates,
              metadata: {
                ...preset.metadata,
                ...updates.metadata,
                modifiedAt: new Date(),
              },
            }
          : preset
      );

      setPresets(updatedPresets);
      savePresetsToStorage(updatedPresets);
    },
    [presets, savePresetsToStorage]
  );

  const deletePreset = useCallback(
    async (presetId: string): Promise<void> => {
      await Promise.resolve(); // Satisfy async linting requirement
      setIsDeleting(true);
      try {
        const preset = presets.find((p) => p.id === presetId);
        if (preset?.isSystem) {
          throw new Error("Cannot delete system presets");
        }

        const updatedPresets = presets.filter((p) => p.id !== presetId);
        setPresets(updatedPresets);
        savePresetsToStorage(updatedPresets);
      } finally {
        setIsDeleting(false);
      }
    },
    [presets, savePresetsToStorage]
  );

  const duplicatePreset = useCallback(
    async (presetId: string, newName?: string): Promise<FilterPreset> => {
      const original = presets.find((p) => p.id === presetId);
      if (!original) {
        throw new Error(`Preset ${presetId} not found`);
      }

      return await savePreset(original.state, {
        name: newName || `${original.name} (Copy)`,
        description: original.description,
        tags: original.tags,
        icon: original.icon,
        color: original.color,
      });
    },
    [presets, savePreset]
  );

  // Export/Import functions
  const exportPreset = useCallback(
    async (
      presetId: string,
      format: "json" | "url" = "json"
    ): Promise<string> => {
      await Promise.resolve(); // Satisfy async linting requirement
      const preset = presets.find((p) => p.id === presetId);
      if (!preset) {
        throw new Error(`Preset ${presetId} not found`);
      }

      const exportData: FilterExport = {
        version: "1.0",
        type: "preset",
        name: preset.name,
        description: preset.description,
        data: preset,
        metadata: {
          exportedBy: currentUser,
          exportedAt: new Date(),
          sourceSystem: "data-table-filters",
          compatibility: ["1.0"],
        },
      };

      if (format === "json") {
        return JSON.stringify(exportData, null, 2);
      }
      // URL format - base64 encoded
      const compressed = btoa(JSON.stringify(exportData));
      return `${window.location.origin}${window.location.pathname}?preset=${compressed}`;
    },
    [presets, currentUser]
  );

  const importPreset = useCallback(
    async (
      data: string,
      format: "json" | "url" = "json"
    ): Promise<FilterPreset> => {
      try {
        let exportData: FilterExport;

        if (format === "url") {
          // Extract from URL parameter
          const compressed = data.includes("preset=")
            ? data.split("preset=")[1]
            : data;
          exportData = JSON.parse(atob(compressed));
        } else {
          exportData = JSON.parse(data);
        }

        if (exportData.type !== "preset") {
          throw new Error("Invalid export format");
        }

        const preset = exportData.data as FilterPreset;

        // Generate new ID and update metadata
        const newPreset: FilterPreset = {
          ...preset,
          id: generatePresetId(),
          isSystem: false,
          metadata: {
            ...preset.metadata,
            createdBy: currentUser,
            createdAt: new Date(),
            modifiedAt: new Date(),
            usageCount: 0,
          },
        };

        const updatedPresets = [...presets, newPreset];
        setPresets(updatedPresets);
        await savePresetsToStorage(updatedPresets);

        return newPreset;
      } catch (error) {
        throw new Error(`Failed to import preset: ${error}`);
      }
    },
    [presets, currentUser, savePresetsToStorage]
  );

  // Utility functions
  const searchPresets = useCallback(
    (query: string): FilterPreset[] => {
      if (!query.trim()) {
        return presets;
      }

      const searchTerm = query.toLowerCase();
      return presets.filter(
        (preset) =>
          preset.name.toLowerCase().includes(searchTerm) ||
          preset.description?.toLowerCase().includes(searchTerm) ||
          preset.tags.some((tag) => tag.toLowerCase().includes(searchTerm))
      );
    },
    [presets]
  );

  const validatePreset = useCallback((preset: Partial<FilterPreset>) => {
    const errors: string[] = [];

    if (!preset.name?.trim()) {
      errors.push("Name is required");
    }

    if (preset.name && preset.name.length > 100) {
      errors.push("Name must be less than 100 characters");
    }

    if (preset.description && preset.description.length > 500) {
      errors.push("Description must be less than 500 characters");
    }

    if (!preset.state) {
      errors.push("Filter state is required");
    }

    return {
      isValid: errors.length === 0,
      errors,
    };
  }, []);

  const updateSettings = useCallback(
    (newSettings: Partial<typeof settings>) => {
      const updated = { ...settings, ...newSettings };
      setSettings(updated);
      localStorage.setItem(
        `${SETTINGS_STORAGE_KEY}_${tableId}`,
        JSON.stringify(updated)
      );
    },
    [settings, tableId]
  );

  const getUsageStats = useCallback(() => {
    try {
      const usage = JSON.parse(localStorage.getItem(USAGE_STORAGE_KEY) || "{}");
      const mostUsed = Object.entries(usage)
        .map(([presetId, count]) => ({ presetId, count: count as number }))
        .sort((a, b) => b.count - a.count)
        .slice(0, 10);

      const recentlyUsed = presets
        .filter((p) => p.metadata.lastUsed)
        .map((p) => ({ presetId: p.id, lastUsed: p.metadata.lastUsed as Date }))
        .sort((a, b) => b.lastUsed.getTime() - a.lastUsed.getTime())
        .slice(0, 10);

      const totalUsage = Object.values(usage).reduce(
        (sum: number, count) => sum + (count as number),
        0
      );

      return { mostUsed, recentlyUsed, totalUsage };
    } catch {
      return { mostUsed: [], recentlyUsed: [], totalUsage: 0 };
    }
  }, [presets]);

  // Placeholder functions for advanced features
  const addTag = useCallback(
    async (presetId: string, tag: string): Promise<void> => {
      await updatePreset(presetId, {
        tags: [...(presets.find((p) => p.id === presetId)?.tags || []), tag],
      });
    },
    [updatePreset, presets]
  );

  const removeTag = useCallback(
    async (presetId: string, tag: string): Promise<void> => {
      await updatePreset(presetId, {
        tags:
          presets
            .find((p) => p.id === presetId)
            ?.tags.filter((t) => t !== tag) || [],
      });
    },
    [updatePreset, presets]
  );

  const setFavorite = useCallback(
    async (presetId: string, isFavorite: boolean): Promise<void> => {
      const preset = presets.find((p) => p.id === presetId);
      if (!preset) {
        return;
      }

      const tags = preset.tags.filter((tag) => tag !== "favorite");
      if (isFavorite) {
        tags.push("favorite");
      }

      await updatePreset(presetId, { tags });
    },
    [updatePreset, presets]
  );

  const sharePreset = useCallback(
    async (presetId: string): Promise<string> => {
      // For now, just return the export URL
      return await exportPreset(presetId, "url");
    },
    [exportPreset]
  );

  const exportAll = useCallback(async (): Promise<string> => {
    await Promise.resolve(); // Satisfy async linting requirement
    const exportData = {
      version: "1.0",
      presets: userPresets,
      exportedAt: new Date(),
      exportedBy: currentUser,
    };
    return JSON.stringify(exportData, null, 2);
  }, [userPresets, currentUser]);

  const importFromFile = useCallback(
    async (file: File): Promise<FilterPreset[]> => {
      const text = await file.text();
      const data = JSON.parse(text);

      if (data.presets && Array.isArray(data.presets)) {
        const importPromises = data.presets.map((preset: FilterPreset) =>
          importPreset(JSON.stringify({ type: "preset", data: preset }))
        );
        const imported = await Promise.all(importPromises);
        return imported;
      }

      throw new Error("Invalid file format");
    },
    [importPreset]
  );

  const comparePresets = useCallback(
    (presetA: string, presetB: string): FilterComparison => {
      const a = presets.find((p) => p.id === presetA);
      const b = presets.find((p) => p.id === presetB);

      if (!(a && b)) {
        throw new Error("Presets not found");
      }

      return {
        id: `compare_${Date.now()}`,
        name: `${a.name} vs ${b.name}`,
        stateA: a.state,
        stateB: b.state,
        metrics: {
          resultsA: 0, // Would be calculated
          resultsB: 0,
          performanceA: 0,
          performanceB: 0,
        },
        status: "draft",
        duration: {
          startDate: new Date(),
          plannedDuration: 7 * 24 * 60 * 60 * 1000, // 7 days
        },
      };
    },
    [presets]
  );

  return {
    // Data
    presets: [...systemPresets, ...userPresets],
    systemPresets,
    userPresets,
    recentPresets,
    popularPresets,

    // Loading states
    isLoading,
    isSaving,
    isDeleting,

    // Actions
    savePreset,
    loadPreset,
    updatePreset,
    deletePreset,
    duplicatePreset,

    // Organization
    addTag,
    removeTag,
    setFavorite,

    // Export/Import
    exportPreset,
    exportAll,
    importPreset,
    importFromFile,

    // Sharing
    sharePreset,

    // Analytics
    getUsageStats,

    // Utilities
    validatePreset,
    searchPresets,
    comparePresets,

    // Settings
    settings,
    updateSettings,
  };
}

import { type RefObject, useEffect } from "react";

export function useOnClickOutside(
  refs: RefObject<HTMLElement>[],
  handler: (event: MouseEvent | TouchEvent) => void
) {
  useEffect(() => {
    const listener = (event: MouseEvent | TouchEvent) => {
      // If any ref is undefined or null, return
      if (refs.some((ref) => !ref.current)) {
        return;
      }

      // Check if click was outside all refs
      const clickedOutside = refs.every((ref) => {
        const el = ref.current;
        if (!(el && event.target instanceof Node)) {
          return true;
        }
        return !el.contains(event.target);
      });

      if (clickedOutside) {
        handler(event);
      }
    };

    document.addEventListener("mousedown", listener);
    document.addEventListener("touchstart", listener);

    return () => {
      document.removeEventListener("mousedown", listener);
      document.removeEventListener("touchstart", listener);
    };
  }, [refs, handler]);
}

/**
 * Hook for handling row drag and drop functionality
 * Uses dnd-kit for drag and drop operations
 */
"use client";

import {
  closestCenter,
  DndContext,
  type DragEndEvent,
  type DragStartEvent,
  KeyboardSensor,
  PointerSensor,
  useSensor,
  useSensors,
} from "@dnd-kit/core";
import { restrictToVerticalAxis } from "@dnd-kit/modifiers";
import {
  arrayMove,
  SortableContext,
  sortableKeyboardCoordinates,
  verticalListSortingStrategy,
} from "@dnd-kit/sortable";
import { useAtom } from "jotai";
import { useCallback, useEffect, useMemo } from "react";

import {
  activeRowDragAtom,
  rowDragEnabledAtom,
  rowOrderAtom,
} from "../atoms/table-atoms";

import { useTableTranslations } from "./use-table-translations";

/**
 * Hook for managing row drag and drop
 * @param tableId - ID of the table
 * @param data - Array of data items
 * @param getRowId - Function to get row ID from data item
 * @returns Object with row drag and drop utilities
 */
export function useRowDnd<TData>(
  tableId: string,
  data: TData[],
  getRowId: (row: TData) => string
) {
  // Get translations
  const _translations = useTableTranslations();

  // Get atoms
  const [rowOrder, setRowOrder] = useAtom(rowOrderAtom(tableId));
  const [activeDragId, setActiveDragId] = useAtom(activeRowDragAtom(tableId));
  const [isDragEnabled, setIsDragEnabled] = useAtom(
    rowDragEnabledAtom(tableId)
  );

  // Initialize row order if not already set
  useEffect(() => {
    if (!rowOrder.length && data.length) {
      setRowOrder(data.map((row) => getRowId(row)));
    }
  }, [data, rowOrder.length, getRowId, setRowOrder]);

  // Configure sensors for mouse, touch, and keyboard interactions
  const sensors = useSensors(
    useSensor(PointerSensor, {
      activationConstraint: {
        distance: 8, // 8px of movement required before drag starts
      },
    }),
    useSensor(KeyboardSensor, {
      coordinateGetter: sortableKeyboardCoordinates,
    })
  );

  // Handle drag end event
  const handleDragEnd = useCallback(
    (event: DragEndEvent) => {
      const { active, over } = event;

      if (over && active.id !== over.id) {
        setRowOrder((items) => {
          const oldIndex = items.indexOf(active.id.toString());
          const newIndex = items.indexOf(over.id.toString());

          // Return early if indexes are invalid
          if (oldIndex === -1 || newIndex === -1) {
            return items;
          }

          // Create new order by moving the item
          return arrayMove(items, oldIndex, newIndex);
        });
      }

      // Reset active drag ID
      setActiveDragId(null);
    },
    [setRowOrder, setActiveDragId]
  );

  // Handle drag start event
  const handleDragStart = useCallback(
    (event: DragStartEvent) => {
      setActiveDragId(event.active.id.toString());
    },
    [setActiveDragId]
  );

  // Toggle drag enabled
  const toggleDragEnabled = useCallback(() => {
    setIsDragEnabled((prev) => !prev);
  }, [setIsDragEnabled]);

  // Get ordered data based on rowOrder
  const orderedData = useMemo(() => {
    if (!(rowOrder.length && isDragEnabled)) {
      return data;
    }

    // Create a map for faster lookups
    const dataMap = new Map(data.map((item) => [getRowId(item), item]));

    // Return data in the order specified by rowOrder, filtering out any IDs that don't exist in the data
    const result = rowOrder
      .map((id) => dataMap.get(id))
      .filter(Boolean) as TData[];

    // If we're missing any items that exist in data but not in rowOrder, add them at the end
    const existingIds = new Set(rowOrder);
    const missingItems = data.filter(
      (item) => !existingIds.has(getRowId(item))
    );

    return [...result, ...missingItems];
  }, [data, rowOrder, getRowId, isDragEnabled]);

  // Reset row order to match data order
  const resetRowOrder = useCallback(() => {
    setRowOrder(data.map((row) => getRowId(row)));
  }, [data, getRowId, setRowOrder]);

  return {
    activeDragId,
    closestCenter,
    DndContext,
    // Event handlers
    handleDragEnd,

    handleDragStart,
    isDragEnabled,
    orderedData,

    resetRowOrder,
    restrictToVerticalAxis,

    // State
    rowOrder,
    // dnd-kit utilities
    sensors,
    // Actions
    setRowOrder,
    SortableContext,
    toggleDragEnabled,
    verticalListSortingStrategy,
  };
}

/**
 * Hook for managing table CRUD actions
 * Provides unified error handling and success callbacks
 */
"use client";

import { useCallback, useMemo } from "react";
import { useTableActions as useProviderTableActions } from "../providers/table-provider";

/**
 * Generic action result type
 */
interface ActionResult {
  success: boolean;
  error?: string;
  data?: unknown;
}

/**
 * Generic table actions interface
 */
interface TableActions {
  list?: (params: unknown) => Promise<{
    data: unknown[];
    meta: { pageCount: number; totalCount: number };
  }>;
  create?: (data: unknown) => Promise<ActionResult>;
  update?: (id: string, data: unknown) => Promise<ActionResult>;
  delete?: (id: string) => Promise<ActionResult>;
  duplicate?: (id: string) => Promise<ActionResult>;
}

/**
 * Options for the table actions hook
 */
interface UseTableActionsOptions {
  tableType: string;
  onSuccess?: () => Promise<void>;
  onError?: (error: string, action: string) => void;
  enableLogging?: boolean;
}

/**
 * Hook for managing table CRUD actions with unified error handling
 */
export function useTableActions<
  TData extends Record<string, unknown> = Record<string, unknown>,
>(options: UseTableActionsOptions) {
  const {
    tableType,
    onSuccess,
    onError,
    enableLogging: _enableLogging = true,
  } = options;

  // Get actions from provider
  const getTableActions = useProviderTableActions();

  const actions = useMemo(() => {
    const tableActions = getTableActions?.(tableType) as
      | TableActions
      | undefined;

    if (!tableActions) {
      // Return empty actions if none found
      return {
        list: async () => ({ data: [], meta: { pageCount: 0, totalCount: 0 } }),
      } as TableActions;
    }

    return tableActions;
  }, [getTableActions, tableType]);

  // Helper function to handle action failure
  const handleActionFailure = useCallback(
    (actionName: string, error?: string) => {
      if (onError) {
        onError(error || "Unknown error", actionName);
      }
    },
    [onError]
  );

  // Helper function to handle action exception
  const handleActionException = useCallback(
    (actionName: string, error: unknown) => {
      if (onError) {
        onError(
          error instanceof Error ? error.message : String(error),
          actionName
        );
      }
    },
    [onError]
  );

  // Helper function to handle action success
  const handleActionSuccess = useCallback(async () => {
    if (onSuccess) {
      await onSuccess();
    }
  }, [onSuccess]);

  /**
   * Generic action executor with unified error handling
   */
  const executeAction = useCallback(
    async <T = boolean>(
      actionName: string,
      actionFn: () => Promise<ActionResult>,
      successReturnValue: T = true as T
    ): Promise<T | false> => {
      try {
        const result = await actionFn();

        if (!result.success) {
          handleActionFailure(actionName, result.error);
          return false;
        }

        await handleActionSuccess();
        return successReturnValue;
      } catch (error) {
        handleActionException(actionName, error);
        return false;
      }
    },
    [handleActionFailure, handleActionSuccess, handleActionException]
  );

  /**
   * Create handler
   */
  const handleCreate = useCallback(
    async (data: Partial<TData>): Promise<boolean> => {
      if (!actions.create) {
        const _errorMsg = `Create action not available for ${tableType}`;
        if (onError) {
          onError("Action not available", "create");
        }

        return false;
      }

      const createFn = actions.create;
      return createFn
        ? await executeAction("create", () => createFn(data))
        : false;
    },
    [actions.create, executeAction, tableType, onError]
  );

  /**
   * Update handler
   */
  const handleEdit = useCallback(
    async (
      row: TData & { id: string },
      data: Partial<TData>
    ): Promise<boolean> => {
      if (!actions.update) {
        const _errorMsg = `Update action not available for ${tableType}`;
        if (onError) {
          onError("Action not available", "update");
        }

        return false;
      }

      const updateFn = actions.update;
      return updateFn
        ? await executeAction("update", () => updateFn(row.id, data))
        : false;
    },
    [actions.update, executeAction, tableType, onError]
  );

  /**
   * Delete handler
   */
  const handleDelete = useCallback(
    async (row: TData & { id: string }): Promise<boolean> => {
      if (!actions.delete) {
        const _errorMsg = `Delete action not available for ${tableType}`;
        if (onError) {
          onError("Action not available", "delete");
        }

        return false;
      }

      const deleteFn = actions.delete;
      return deleteFn
        ? await executeAction("delete", () => deleteFn(row.id))
        : false;
    },
    [actions.delete, executeAction, tableType, onError]
  );

  /**
   * Duplicate handler
   */
  const handleDuplicate = useCallback(
    async (row: TData & { id: string }): Promise<boolean> => {
      if (!actions.duplicate) {
        const _errorMsg = `Duplicate action not available for ${tableType}`;
        if (onError) {
          onError("Action not available", "duplicate");
        }

        return false;
      }

      const duplicateFn = actions.duplicate;
      return duplicateFn
        ? await executeAction("duplicate", () => duplicateFn(row.id))
        : false;
    },
    [actions.duplicate, executeAction, tableType, onError]
  );

  return {
    // Raw actions from provider
    actions,

    // Enhanced handlers
    handleCreate,
    handleEdit,
    handleDelete,
    handleDuplicate,

    // Utility
    hasAction: (actionName: keyof TableActions) => !!actions[actionName],
    isActionsAvailable: Object.keys(actions).length > 1, // More than just 'list'
  };
}

/**
 * Hook for managing table configuration
 * Handles configuration retrieval, defaults, and translations
 */
"use client";

import type { ColumnSort } from "@tanstack/react-table";
import { useMemo } from "react";
import {
  useTableConfig as useProviderTableConfig,
  useTranslations,
} from "../providers/table-provider";
import { useTableTranslations } from "./use-table-translations";

/**
 * Configuration for table columns in the catalogue
 */
export interface TableCatalogueColumnConfig {
  id: string;
  type: string;
  header: string;
  enableSorting?: boolean;
  enableColumnFilter?: boolean;
  typeKey?: string;
  customRenderers?: Record<string, (value: unknown) => React.ReactNode>;
}

/**
 * Configuration for table behavior in the catalogue
 */
export interface TableCatalogueTableConfig {
  enableRowSelection: boolean;
  enableColumnFilters: boolean;
  enableSorting: boolean;
  enableGrouping?: boolean;
  manualFiltering: boolean;
  manualPagination: boolean;
  manualSorting: boolean;
  /** Gate for column DnD feature and UI */
  enableColumnDnd?: boolean;
  enableColumnDragDropByDefault?: boolean;
  enableMultiRowSelection?: boolean;
  enablePagination?: boolean;
  defaultPageSize?: number;
  pageSizeOptions?: number[];
}

/**
 * Shape returned by getTableConfig: table options plus optional columns.
 * Used when normalizing provider config to TableCatalogueConfig.
 */
type ProviderTableConfig = TableCatalogueTableConfig & {
  columns?: {
    definitions?: TableCatalogueColumnConfig[];
    order?: string[];
    visible?: string[];
    mandatory?: string[];
    sort?: ColumnSort[];
  };
};

/**
 * Full configuration for a table type in the catalogue
 */
export interface TableCatalogueConfig {
  table: TableCatalogueTableConfig;
  columns: {
    definitions: TableCatalogueColumnConfig[];
    order?: string[];
    sort?: ColumnSort[];
    visible?: string[];
    mandatory?: string[];
  };
  translations?: {
    namespace: string;
    keys: Record<string, string>;
  };
}

/**
 * Default table configuration
 */
const DEFAULT_TABLE_CONFIG: TableCatalogueConfig = {
  table: {
    enableRowSelection: true,
    enableColumnFilters: true,
    enableSorting: true,
    enableGrouping: true,
    manualFiltering: false,
    manualPagination: false,
    manualSorting: false,
    enableColumnDnd: true,
    enableColumnDragDropByDefault: false,
    enableMultiRowSelection: true,
    enablePagination: true,
    defaultPageSize: 10,
    pageSizeOptions: [5, 10, 20, 50],
  },
  columns: {
    definitions: [],
    order: [],
    sort: [],
    visible: [],
    mandatory: [],
  },
  translations: {
    namespace: "common",
    keys: {},
  },
};

/**
 * Hook for managing table configuration
 */
export function useTableConfig(tableType: string) {
  // Get configuration and translation providers
  const getTableConfig = useProviderTableConfig();
  // Removed useColumnsConfig since it's not exported
  const { t } = useTranslations();
  const baseTranslations = useTableTranslations();

  // Get table configuration with fallback to defaults
  const config = useMemo(() => {
    const providerConfig = getTableConfig?.(tableType) as
      | ProviderTableConfig
      | undefined;
    // columnsConfig removed since useColumnsConfig is not exported

    if (!providerConfig) {
      return DEFAULT_TABLE_CONFIG;
    }

    // Transform DataTableConfig to TableCatalogueConfig
    const tableConfig: TableCatalogueConfig = {
      table: {
        enableRowSelection: providerConfig.enableRowSelection,
        enableColumnFilters: providerConfig.enableColumnFilters,
        enableSorting: providerConfig.enableSorting,
        enableGrouping: providerConfig.enableGrouping,
        manualFiltering: providerConfig.manualFiltering,
        manualPagination: providerConfig.manualPagination,
        manualSorting: providerConfig.manualSorting,
        enableColumnDnd: providerConfig.enableColumnDnd ?? true,
        enableColumnDragDropByDefault:
          providerConfig.enableColumnDragDropByDefault,
        enableMultiRowSelection: providerConfig.enableMultiRowSelection,
        enablePagination: providerConfig.enablePagination,
        defaultPageSize: providerConfig.defaultPageSize,
        pageSizeOptions: providerConfig.pageSizeOptions,
      },
      columns: (() => {
        const definitions = providerConfig?.columns?.definitions || [];
        const order = providerConfig?.columns?.order || [];
        const visible = providerConfig?.columns?.visible || [];
        const mandatory = providerConfig?.columns?.mandatory || [];
        const enableRowSelection = providerConfig.enableRowSelection !== false;

        const orderWithSelect =
          enableRowSelection && !order.includes("select")
            ? ["select", ...order]
            : order;
        const visibleWithSelect =
          enableRowSelection && !visible.includes("select")
            ? ["select", ...visible]
            : visible;

        return {
          definitions,
          order: orderWithSelect,
          sort: [],
          visible: visibleWithSelect,
          mandatory,
        };
      })(),
      translations: {
        namespace: "common",
        keys: {},
      },
    };

    return tableConfig;
  }, [getTableConfig, tableType]);

  // Create enhanced translations object
  const translations = useMemo(() => {
    if (!config.translations?.keys) {
      return baseTranslations;
    }

    return {
      ...baseTranslations,
      ...Object.entries(config.translations.keys).reduce(
        (acc, [key, value]) => {
          // Use the main t function for translation keys
          acc[key] = t(value);
          return acc;
        },
        {} as Record<string, string>
      ),
    };
  }, [baseTranslations, config.translations?.keys, t]);

  return {
    config,
    translations,
    isConfigured: !!getTableConfig?.(tableType),
  };
}

/**
 * Hook for creating and managing a TanStack Table instance
 * Uses URL parameters as the source of truth
 */
"use client";

import {
  type ColumnDef,
  type ColumnFiltersState,
  type ColumnOrderState,
  type ColumnPinningState,
  type ExpandedState,
  type GroupingState,
  getCoreRowModel,
  getExpandedRowModel,
  getFilteredRowModel,
  getGroupedRowModel,
  getPaginationRowModel,
  getSortedRowModel,
  type OnChangeFn,
  type PaginationState,
  type RowSelectionState,
  type SortingState,
  type Table,
  useReactTable,
  type VisibilityState,
} from "@tanstack/react-table";
import { useCallback, useEffect, useMemo, useRef, useState } from "react";

import { useTableUrlState } from "./use-table-url-state";

const _DEBUG = false;
/**
 * Options for the useTableInstance hook
 */
export interface UseTableInstanceOptions<TData> {
  columns: ColumnDef<TData>[];
  data: TData[];
  /**
   * Column IDs that should be visible by default when no URL visibility state exists.
   * Columns present in column definitions but absent from this list will be hidden.
   * When empty or undefined, all columns default to visible (original behaviour).
   */
  defaultVisibleColumns?: string[];
  enableColumnFilters?: boolean;
  enableColumnPinning?: boolean;
  enableGrouping?: boolean;
  enableMultiRowSelection?: boolean;
  enablePagination?: boolean;
  enableRowSelection?: boolean;
  enableSorting?: boolean;
  getRowId?: (row: TData) => string;
  manualFiltering?: boolean;
  manualPagination?: boolean;
  manualSorting?: boolean;
  onRowSelectionChange?: (selection: Record<string, boolean>) => void;
  pageCount?: number;
  rowSelection?: Record<string, boolean>;
  tableId: string;
}

/**
 * Hook for creating and managing a TanStack Table instance using URL parameters
 * @param options - Configuration options for the table instance
 * @returns TanStack Table instance
 */
export function useTableInstance<TData>({
  columns,
  data,
  defaultVisibleColumns,
  enableColumnFilters = true,
  enableColumnPinning = true,
  enableGrouping = false,
  enableMultiRowSelection = true,
  enablePagination = true,
  enableRowSelection = true,
  enableSorting = true,
  getRowId,
  manualFiltering = false,
  manualPagination = false,
  manualSorting = false,
  onRowSelectionChange,
  pageCount = 0,
  rowSelection: externalRowSelection,
  tableId,
}: UseTableInstanceOptions<TData>) {
  // Memoize expensive computations
  const memoizedColumns = useMemo(() => columns, [columns]);
  const memoizedData = useMemo(() => data, [data]);

  // Cache the table options to prevent unnecessary re-renders
  const tableOptionsRef = useRef({
    enableColumnFilters,
    enableColumnPinning,
    enableGrouping,
    enableMultiRowSelection,
    enablePagination,
    enableRowSelection,
    enableSorting,
    manualFiltering,
    manualPagination,
    manualSorting,
  });

  // Update ref if options change
  useEffect(() => {
    tableOptionsRef.current = {
      enableColumnFilters,
      enableColumnPinning,
      enableGrouping,
      enableMultiRowSelection,
      enablePagination,
      enableRowSelection,
      enableSorting,
      manualFiltering,
      manualPagination,
      manualSorting,
    };
  }, [
    enableColumnFilters,
    enableColumnPinning,
    enableGrouping,
    enableMultiRowSelection,
    enablePagination,
    enableRowSelection,
    enableSorting,
    manualFiltering,
    manualPagination,
    manualSorting,
  ]);

  // Get table state from URL parameters
  const {
    filtersParam,
    groupingParam,
    orderParam,
    pagination,
    pinningParam,
    setColumnFiltersFromUI,
    setGroupingFromUI,
    setOrderFromUI,
    setPaginationFromUI,
    setPinningFromUI,
    setSorting,
    setVisibilityFromUI,
    sortParam,
    visibilityParam,
  } = useTableUrlState({ tableId });

  // Use React state for row selection (doesn't need to be in URL)
  const [internalRowSelection, setInternalRowSelection] =
    useState<RowSelectionState>({});

  // Create wrapper functions to adapt our URL state setters to TanStack's OnChangeFn pattern
  const handleColumnFiltersChange = useCallback<OnChangeFn<ColumnFiltersState>>(
    (updaterOrValue) => {
      const newValue =
        typeof updaterOrValue === "function"
          ? updaterOrValue((filtersParam as ColumnFiltersState) || [])
          : updaterOrValue;

      setColumnFiltersFromUI(newValue);
    },
    [filtersParam, setColumnFiltersFromUI]
  );

  const handleColumnOrderChange = useCallback<OnChangeFn<ColumnOrderState>>(
    (updaterOrValue) => {
      const newValue =
        typeof updaterOrValue === "function"
          ? updaterOrValue((orderParam as string[]) || [])
          : updaterOrValue;
      setOrderFromUI(newValue);
    },
    [orderParam, setOrderFromUI]
  );

  // Handler for column pinning changes
  const handleColumnPinningChange = useCallback<OnChangeFn<ColumnPinningState>>(
    (updaterOrValue) => {
      const newValue =
        typeof updaterOrValue === "function"
          ? updaterOrValue(pinningParam || { left: [], right: [] })
          : updaterOrValue;

      // Ensure we have the correct structure for pinning state
      const normalizedPinning = {
        left: newValue.left || [],
        right: newValue.right || [],
      };

      setPinningFromUI(normalizedPinning);
    },
    [pinningParam, setPinningFromUI]
  );

  const handleColumnVisibilityChange = useCallback<OnChangeFn<VisibilityState>>(
    (updaterOrValue) => {
      const newValue =
        typeof updaterOrValue === "function"
          ? updaterOrValue((visibilityParam as VisibilityState) || {})
          : updaterOrValue;

      setVisibilityFromUI(newValue);
    },
    [visibilityParam, setVisibilityFromUI]
  );

  // Expanded: disable handler to avoid loops
  const handleExpandedChange = useCallback<OnChangeFn<ExpandedState>>(
    (_updaterOrValue) => {
      // No-op to avoid infinite loops
    },
    []
  );

  const handleGroupingChange = useCallback<OnChangeFn<GroupingState>>(
    (updaterOrValue) => {
      const newValue =
        typeof updaterOrValue === "function"
          ? updaterOrValue((groupingParam as string[]) || [])
          : updaterOrValue;
      setGroupingFromUI(newValue);
    },
    [groupingParam, setGroupingFromUI]
  );

  const handlePaginationChange = useCallback<OnChangeFn<PaginationState>>(
    (updaterOrValue) => {
      const newValue =
        typeof updaterOrValue === "function"
          ? updaterOrValue(pagination)
          : updaterOrValue;
      setPaginationFromUI(newValue);
    },
    [pagination, setPaginationFromUI]
  );

  const handleSortingChange = useCallback<OnChangeFn<SortingState>>(
    (updaterOrValue) => {
      const newValue =
        typeof updaterOrValue === "function"
          ? updaterOrValue((sortParam as SortingState) || [])
          : updaterOrValue;

      const normalizedSort = Array.isArray(newValue)
        ? newValue.map((item) => ({
            desc: item.desc,
            id: item.id,
          }))
        : newValue;

      setSorting(normalizedSort);
    },
    [sortParam, setSorting]
  );

  // Create a wrapper for the row selection change handler
  const handleRowSelectionChange = useCallback<OnChangeFn<RowSelectionState>>(
    (updaterOrValue) => {
      // First update the internal state using React's state setter
      setInternalRowSelection((prev) =>
        typeof updaterOrValue === "function"
          ? updaterOrValue(prev)
          : updaterOrValue
      );

      // Then if we have an external handler, call it with the new value
      if (onRowSelectionChange) {
        // Convert the updater to a value if needed
        const newValue =
          typeof updaterOrValue === "function"
            ? updaterOrValue(internalRowSelection)
            : updaterOrValue;

        onRowSelectionChange(newValue as Record<string, boolean>);
      }
    },
    [onRowSelectionChange, internalRowSelection]
  );

  // Helper function to collect all valid column IDs
  const getColumnIds = useCallback((cols: ColumnDef<TData>[]) => {
    const columnIds = new Set<string>();

    for (const col of cols) {
      if (col.id) {
        columnIds.add(col.id);
      }

      if ("accessorKey" in col && col.accessorKey) {
        columnIds.add(String(col.accessorKey));
      }

      if (col.header && typeof col.header === "string") {
        columnIds.add(col.header.toLowerCase());
      }
    }

    return columnIds;
  }, []);

  // Helper function to check if a sort ID is valid
  const isValidSortId = useCallback(
    (sortId: string, columnIds: Set<string>) => {
      const normalizedId = sortId.toLowerCase();

      return (
        columnIds.has(sortId) ||
        Array.from(columnIds).some((id) => id.toLowerCase() === normalizedId) ||
        sortId === "key" ||
        sortId === "id" ||
        sortId === "name" ||
        sortId === "createdAt" ||
        sortId === "updatedAt"
      );
    },
    []
  );

  // Validate sorting to ensure all referenced columns exist
  const validatedSorting = useMemo(() => {
    if (!(sortParam && Array.isArray(sortParam))) {
      return [];
    }

    const columnIds = getColumnIds(columns);

    const validSorting = (sortParam as Array<{ desc: boolean; id: string }>)
      .filter((sort) => isValidSortId(sort.id, columnIds))
      .map((sort) => ({
        desc: sort.desc,
        id: sort.id,
      }));

    return validSorting.length ? validSorting : [];
  }, [columns, sortParam, getColumnIds, isValidSortId]);

  // Helper function to get a stable ID for a column
  const getColumnId = useCallback(
    (column: ColumnDef<TData>, index: number): string => {
      // Case 1: Column has an explicit ID
      if (typeof column.id === "string") {
        return column.id;
      }
      // Case 2: Column has an accessorKey
      if ("accessorKey" in column && column.accessorKey !== undefined) {
        return String(column.accessorKey);
      }
      // Case 3: Generate a fallback ID
      return `col-${index}`;
    },
    []
  );

  // Helper function to determine if a column should be visible by default
  const getDefaultColumnVisibility = useCallback(
    (column: ColumnDef<TData>, id: string): boolean => {
      // Special cases for selection and actions columns - always visible
      if (
        id === "select" ||
        (column.meta as Record<string, unknown>)?.isSelectionColumn ||
        id === "actions" ||
        (column.meta as Record<string, unknown>)?.isActionsColumn
      ) {
        return true;
      }

      // When a defaultVisibleColumns list is provided, only show listed columns
      if (defaultVisibleColumns && defaultVisibleColumns.length > 0) {
        return defaultVisibleColumns.includes(id);
      }

      return column.enableHiding !== false;
    },
    [defaultVisibleColumns]
  );

  // Initialize column visibility from columns
  const initialColumnVisibility = useMemo(() => {
    // If we have visibility in URL params, use those
    if (visibilityParam && Object.keys(visibilityParam).length > 0) {
      return visibilityParam;
    }

    // Otherwise, use the column definitions (+ defaultVisibleColumns if provided)
    const visibility: VisibilityState = {};
    for (const [index, column] of columns.entries()) {
      const id = getColumnId(column, index);
      if (id) {
        visibility[id] = getDefaultColumnVisibility(column, id);
      }
    }
    return visibility;
  }, [columns, visibilityParam, getColumnId, getDefaultColumnVisibility]);

  // Initialize column order from columns when URL order is empty
  const initialColumnOrder = useMemo(() => {
    // Get all column IDs using the same logic as the visibility function
    return columns.map((column, index) => getColumnId(column, index));
  }, [columns, getColumnId]);

  // Resolve the effective column order from URL params with a safe fallback
  const resolvedColumnOrder = useMemo(() => {
    const urlOrder = Array.isArray(orderParam) ? (orderParam as string[]) : [];

    // When no URL order, use initial order derived from current columns
    if (urlOrder.length === 0) {
      return initialColumnOrder;
    }

    // Filter URL order to only include current columns
    const currentIds = new Set(initialColumnOrder);
    const filtered = urlOrder.filter((id) => currentIds.has(id));

    // Append any new/missing columns at the end in their initial order
    const missing = initialColumnOrder.filter((id) => !filtered.includes(id));
    let combined = [...filtered, ...missing];

    // Enforce fixed positions for special columns if present
    const hasSelect = combined.includes("select");
    const hasActions = combined.includes("actions");
    combined = combined.filter((id) => id !== "select" && id !== "actions");
    if (hasSelect) {
      combined = ["select", ...combined];
    }
    if (hasActions) {
      combined = [...combined, "actions"];
    }

    return combined;
  }, [orderParam, initialColumnOrder]);

  // Create the table instance with memoized values
  const tableInstance = useReactTable({
    columns: memoizedColumns,
    data: memoizedData,
    ...tableOptionsRef.current,
    // Keep grouped columns and move them to the start so group headers render in their own column
    groupedColumnMode: "reorder",
    getCoreRowModel: useMemo(() => getCoreRowModel(), []),
    getFilteredRowModel: useMemo(() => getFilteredRowModel(), []),
    getGroupedRowModel: useMemo(
      () => (enableGrouping ? getGroupedRowModel() : undefined),
      [enableGrouping]
    ),
    getPaginationRowModel: useMemo(
      () => (enablePagination ? getPaginationRowModel() : undefined),
      [enablePagination]
    ),
    getRowId,
    // Explicitly allow expanding on rows that can expand (group headers)
    getRowCanExpand: (row) => {
      try {
        // TanStack groups create subRows, use that as the signal
        return (
          Array.isArray((row as unknown as { subRows?: unknown[] }).subRows) &&
          ((row as unknown as { subRows?: unknown[] }).subRows as unknown[])
            .length > 0
        );
      } catch {
        return false;
      }
    },
    getSortedRowModel: useMemo(() => getSortedRowModel(), []),
    // Needed so grouped rows can expand/collapse
    getExpandedRowModel: useMemo(() => getExpandedRowModel(), []),
    getSubRows: (row: TData) =>
      (row as unknown as { subRows?: TData[] }).subRows,
    manualFiltering,
    manualPagination,
    manualSorting,
    onColumnFiltersChange: handleColumnFiltersChange,
    onColumnOrderChange: handleColumnOrderChange,
    onColumnPinningChange: handleColumnPinningChange,
    onColumnVisibilityChange: handleColumnVisibilityChange,
    onExpandedChange: handleExpandedChange,
    onGroupingChange: handleGroupingChange,
    onPaginationChange: handlePaginationChange,
    onRowSelectionChange: handleRowSelectionChange,
    onSortingChange: handleSortingChange,
    pageCount: pageCount || Math.ceil(data.length / pagination.pageSize),
    state: {
      columnFilters: Array.isArray(filtersParam)
        ? (filtersParam as ColumnFiltersState)
        : [],
      columnOrder: resolvedColumnOrder,
      columnPinning: pinningParam || {
        left: ["select"],
        right: ["actions"],
      },
      columnVisibility: initialColumnVisibility as VisibilityState,
      expanded: {},
      grouping: Array.isArray(groupingParam) ? (groupingParam as string[]) : [],
      pagination,
      rowSelection:
        externalRowSelection || (internalRowSelection as RowSelectionState),
      sorting: Array.isArray(validatedSorting)
        ? (validatedSorting as SortingState)
        : [],
    },
  });

  // Helper function to check if column order should be updated
  const shouldUpdateColumnOrder = useCallback(
    (tableInst: Table<TData> | null, orderParamValue: unknown): boolean => {
      return !!(
        tableInst &&
        orderParamValue &&
        Array.isArray(orderParamValue) &&
        orderParamValue.length > 0
      );
    },
    []
  );

  // Helper function to perform column order update
  const updateColumnOrder = useCallback(
    (tableInst: Table<TData>, urlOrder: string[]) => {
      const currentOrder = tableInst.getState().columnOrder;
      // Only update if the order actually changed
      if (JSON.stringify(currentOrder) !== JSON.stringify(urlOrder)) {
        tableInst.setColumnOrder(urlOrder);
      }
    },
    []
  );

  // Sync table column order when URL state changes
  useEffect(() => {
    if (shouldUpdateColumnOrder(tableInstance, orderParam) && tableInstance) {
      const urlOrder = orderParam as string[];
      updateColumnOrder(tableInstance, urlOrder);
    }
  }, [tableInstance, orderParam, shouldUpdateColumnOrder, updateColumnOrder]);

  return tableInstance;
}

/**
 * Hook for accessing translations in the DataTable component
 * Provides both direct access to resolved translations and complex formatting capabilities
 */
import { useAtomValue } from "jotai";
import {
  type DataTableUiStrings,
  tableTranslationsAtom,
  translationKeysMap,
  translationsAtom,
  translationsInitializedAtom,
} from "../atoms/i18n-atoms";
import { useTranslations } from "../providers/table-provider";

/**
 * Extended return type for useTableTranslations that includes formatting function
 */
export interface UseTableTranslationsReturn extends DataTableUiStrings {
  /**
   * Format a translation with variables (plurals, dates, rich text, etc.)
   * Leverages next-intl's powerful formatting capabilities
   * @param key - The translation key name from DataTableTranslations
   * @param values - Values to interpolate, including pluralization variables
   */
  format: (
    key: keyof DataTableUiStrings,
    values?: Record<string, string | number | Date>
  ) => string;
}

/**
 * Enhanced hook that provides access to all available translations for DataTable components
 * Along with a format function that leverages next-intl for complex formatting
 * @returns Both direct translations and a format function for complex cases
 */
export function useTableTranslations(
  tableId?: string
): UseTableTranslationsReturn {
  // Get global translations from atom
  const globalTranslations = useAtomValue(translationsAtom);

  // Create a dummy tableId if none is provided to ensure hooks are called consistently
  const safeTableId = tableId || "global";

  // Always call the hook unconditionally
  const tableSpecificTranslations = useAtomValue(
    tableTranslationsAtom(safeTableId)
  );

  // Use table-specific translations if tableId was provided, otherwise use global
  const tableTranslations = tableId
    ? tableSpecificTranslations
    : globalTranslations;

  // Check if translations are initialized
  const isInitialized = useAtomValue(translationsInitializedAtom);

  // Get next-intl's translation function for advanced formatting
  // Specify the 'data-table' namespace to access translations from the correct file
  const { t } = useTranslations();

  // Create a mapping from property name to original translation key
  const keyToOriginalMap = Object.entries(translationKeysMap).reduce(
    (acc, [key, originalKey]) => {
      if (typeof originalKey === "string") {
        acc[key as keyof DataTableUiStrings] = originalKey;
      }
      return acc;
    },
    {} as Record<keyof DataTableUiStrings, string>
  );

  // Format function that leverages next-intl's capabilities for plurals and more
  const format = (
    key: keyof DataTableUiStrings,
    values?: Record<string, string | number | Date>
  ): string => {
    const originalKey = keyToOriginalMap[key];

    // If we can't find the original key, return the stored translation or the key itself
    if (!originalKey) {
      return (
        (
          tableTranslations as Partial<Record<keyof DataTableUiStrings, string>>
        )[key] || String(key)
      );
    }

    try {
      // Use the t function directly with the original translation key and provided values
      // Convert Date objects to strings to match TranslationParams type
      const safeValues = values
        ? Object.fromEntries(
            Object.entries(values).map(([paramKey, value]) => [
              paramKey,
              value instanceof Date ? value.toISOString() : value,
            ])
          )
        : {};

      return t(originalKey, safeValues);
    } catch (_error) {
      // Log a warning in development mode only
      if (process.env.NODE_ENV === "development") {
        /* optional dev warning */
      }
      // Return the stored translation or the key itself as a fallback
      return (
        (
          tableTranslations as Partial<Record<keyof DataTableUiStrings, string>>
        )[key] || String(key)
      );
    }
  };

  // If translations aren't initialized yet, return a proxy that uses format for all keys
  if (!isInitialized) {
    return new Proxy({ format } as UseTableTranslationsReturn, {
      get: (target, prop) => {
        if (prop === "format") {
          return target.format;
        }
        return format(prop as keyof DataTableUiStrings);
      },
    });
  }

  // Return all translations plus the format function
  return {
    ...(tableTranslations as Record<string, string>),
    format,
  } as UseTableTranslationsReturn;
}

/**
 * Hook for accessing DataTable UI configuration
 * Provides access to translations, table options, and column configurations
 */
"use client";

import { useAtomValue } from "jotai";

import {
  type DataTableColumnsConfig,
  type DataTableConfig,
  tableColumnsConfigFamilyAtom,
  tableConfigFamilyAtom,
} from "../atoms/config-atoms";
import {
  type DataTableUiStrings,
  resolvedTranslationsAtom,
} from "../atoms/i18n-atoms";

interface UseTableUIConfigResult {
  /**
   * Column configuration options
   */
  columnsConfig: DataTableColumnsConfig;

  /**
   * Table configuration options
   */
  tableConfig: DataTableConfig;

  /**
   * Fully resolved translations
   */
  translations: DataTableUiStrings;
}

/**
 * Hook to access all UI-related configurations for a specific table
 * @param tableId - The ID of the table to get configurations for
 * @returns Object containing translations, table config, and columns config
 */
export function useTableUIConfig(
  tableId = "default-table"
): UseTableUIConfigResult {
  // Get table-specific column configuration
  const columnsConfig = useAtomValue(tableColumnsConfigFamilyAtom(tableId));

  // Get table-specific configuration
  const tableConfig = useAtomValue(tableConfigFamilyAtom(tableId));

  // Get resolved translations
  const translations = useAtomValue(resolvedTranslationsAtom);

  return {
    columnsConfig,
    tableConfig,
    translations,
  };
}

/**
 * Hook for fetching and managing table data with URL state
 * Uses TanStack Query for data fetching and caching
 */
"use client";

import { useQuery, useQueryClient } from "@tanstack/react-query";
import { useCallback, useMemo, useState } from "react";

import { processServerFilters } from "../utils/server-filters";

import { useTableUrlState } from "./use-table-url-state";

const _DEBUG = false;

interface UseTableUrlDataOptions<TData> {
  enabled?: boolean;
  getRowId?: (row: TData) => string;
  initialData?: TData[];
  queryFn: (params: {
    columnFilters: Array<{ id: string; value: unknown }>;
    complexFilters: unknown[];
    advancedFilters: unknown[];
    pagination: {
      pageIndex: number;
      pageSize: number;
    };
    serverFilters: Record<string, unknown>;
    sorting: {
      desc: boolean;
      id: string;
    }[];
    tableId: string;
  }) => Promise<{
    data: TData[];
    pageCount: number;
    rowCount: number;
  }>;
  tableId: string;
}

/**
 * Hook for fetching and managing table data with URL state
 * @param options - Configuration options for data fetching
 * @returns Object with data and loading state
 */
export function useTableUrlData<TData>({
  enabled = true,
  getRowId = (row: TData) => (row as Record<string, unknown>).id as string,
  initialData = [],
  queryFn,
  tableId,
}: UseTableUrlDataOptions<TData>) {
  // Get URL state - include advanced filters!
  const {
    filtersParam,
    advancedFiltersParam,
    orderParam,
    pagination,
    sortParam,
    globalSearchParam,
  } = useTableUrlState({
    tableId,
  });

  // Use React state for row selection (client-side only)
  const [rowSelection, setRowSelection] = useState<Record<string, boolean>>({});

  // Get query client
  const queryClient = useQueryClient();

  // Process filters for server-side compatibility
  const processedFiltersQuery = useQuery({
    queryFn: () => {
      // Ensure filtersParam is always an array
      const filters = Array.isArray(filtersParam) ? filtersParam : [];
      // Ensure advancedFiltersParam is always an array
      const advancedFilters = Array.isArray(advancedFiltersParam)
        ? advancedFiltersParam
        : [];
      if (filters.length === 0 && advancedFilters.length === 0) {
        return { complexFilters: [], serverFilters: {}, advancedFilters: [] };
      }

      // Extract global filter if present
      const globalFilterEntry = filters.find(
        (f: unknown): f is { id: string; value: unknown } =>
          typeof f === "object" &&
          f !== null &&
          "id" in f &&
          (f as { id: string }).id === "global"
      );
      const globalFilter =
        globalFilterEntry &&
        typeof globalFilterEntry === "object" &&
        "value" in globalFilterEntry
          ? (globalFilterEntry.value as string)
          : "";

      // Process column filters for server-side compatibility
      const result = processServerFilters(
        (filters as Array<{ id: string; value: unknown }>)
          .filter((filter) => filter.id !== "global") // Remove global filter from regular filters
          .map((filter) => ({
            id: filter.id,
            value: filter.value,
          }))
      );

      // Add global filter if present
      if (globalFilter) {
        result.serverFilters.global = globalFilter;
      }

      // Add advanced filters to the result
      const finalResult = {
        ...result,
        advancedFilters: advancedFilters.filter(
          (filter: { isActive: boolean }) => filter.isActive
        ), // Only include active filters
      };
      return finalResult;
    },
    // Include advancedFiltersParam in query key
    queryKey: [
      "tableProcessedFilters",
      tableId,
      filtersParam,
      advancedFiltersParam,
    ],
    staleTime: 5000, // 5 seconds
  });

  // Extract complex filters, server filters, and advanced filters from the query result
  const { complexFilters, serverFilters, advancedFilters } =
    processedFiltersQuery.data || {
      complexFilters: [],
      serverFilters: {},
      advancedFilters: [],
    };

  // Modify the enabled condition to also run when processedFiltersQuery is pending but we have initial data
  // This prevents the infinite loading state when processedFiltersQuery is stuck in pending
  const shouldEnableQuery =
    Boolean(tableId) &&
    enabled &&
    (processedFiltersQuery.status === "success" ||
      (processedFiltersQuery.status === "pending" && initialData.length > 0));

  // Query for fetching data
  const {
    data: queryResult,
    error,
    isError,
    isLoading,
    refetch,
    status,
  } = useQuery({
    // Enable the query when processedFiltersQuery is complete or when we have initial data
    enabled: shouldEnableQuery,
    initialData: initialData.length
      ? {
          data: initialData,
          pageCount: 1,
          rowCount: initialData.length,
        }
      : undefined,
    queryFn: async () => {
      // Convert serverFilters to columnFilters format for compatibility
      const columnFilters = Object.entries(serverFilters).map(
        ([id, value]) => ({
          id,
          value,
        })
      );

      const params = {
        // Use columnFilters for TanStack Table compatibility
        columnFilters,
        // Use complexFilters for special filter types
        complexFilters,
        // Advanced filters for enhanced filtering
        advancedFilters,
        // Global search (server-side global filtering)
        globalSearch: globalSearchParam,
        // Pagination parameters from URL
        pagination,
        // Use serverFilters directly for server-side filtering (without key filters)
        serverFilters,
        // Sorting parameters
        sorting: (sortParam as { desc: boolean; id: string }[]) || [],
        // Table identifier
        tableId,
      };
      const result = await queryFn(params);
      return result;
    },
    queryKey: [
      "tableData",
      tableId,
      JSON.stringify(sortParam),
      JSON.stringify(filtersParam),
      JSON.stringify(advancedFiltersParam),
      globalSearchParam || "",
      JSON.stringify(pagination),
      JSON.stringify(serverFilters),
    ],
    // Prevent refetching on window focus to avoid duplicate requests
    refetchOnWindowFocus: false,
    // Improve cache options for better performance
    staleTime: 30_000, // 30 seconds
  });

  // Get data from query result or use initial data
  const data = queryResult?.data || [];

  // Apply row ordering if drag is enabled and we have a row order
  const orderedData = useMemo(() => {
    if (!Array.isArray(data) || data.length === 0) {
      return data;
    }

    // If we have a row order, apply it
    if (Array.isArray(orderParam) && orderParam.length > 0) {
      // Create a map of row IDs to their order index
      const orderMap = new Map<string, number>();
      (orderParam as string[]).forEach((id, index) => {
        orderMap.set(id, index);
      });

      // Sort the data based on the order map
      return [...data].sort((a, b) => {
        const aId = getRowId(a);
        const bId = getRowId(b);

        // If both rows are in the order map, sort by their order
        if (orderMap.has(aId) && orderMap.has(bId)) {
          return (orderMap.get(aId) || 0) - (orderMap.get(bId) || 0);
        }

        // If only one row is in the order map, it comes first
        if (orderMap.has(aId)) {
          return -1;
        }
        if (orderMap.has(bId)) {
          return 1;
        }

        // If neither row is in the order map, maintain original order
        return 0;
      });
    }

    return data;
  }, [data, orderParam, getRowId]);

  // Enhanced refetch that invalidates the cache
  const enhancedRefetch = useCallback(async () => {
    queryClient.invalidateQueries({ queryKey: ["tableData", tableId] });
    return await refetch();
  }, [queryClient, refetch, tableId]);

  return {
    data: orderedData,
    enhancedRefetch,
    error,
    isError,
    isLoading,
    pagination,
    refetch,
    rowCount: queryResult?.rowCount || initialData.length || 0,
    rowSelection,
    setRowSelection,
    status,
  };
}

/**
 * Hook for managing URL state with nuqs
 * Allows sharing links to specific table states
 */
"use client";

import type { ColumnFiltersState, SortingState } from "@tanstack/react-table";
import { createParser, useQueryState } from "nuqs";
import { useCallback, useEffect, useMemo, useRef } from "react";
import type { AdvancedFiltersState } from "../types/filter-types";

// Simple debounce implementation to avoid lodash dependency
function debounce<T extends (...args: unknown[]) => void>(
  func: T,
  wait: number
): T {
  let timeout: NodeJS.Timeout | null = null;
  return ((...args: unknown[]) => {
    if (timeout) {
      clearTimeout(timeout);
    }
    timeout = setTimeout(() => func(...args), wait);
  }) as T;
}

// Debug flag to help track sorting issues
const _DEBUG = false;

// Create parsers for different types of state
const arrayParser = createParser({
  parse: (value: string) => (value ? JSON.parse(value) : []),
  serialize: (value: unknown[]) => (value?.length ? JSON.stringify(value) : ""),
});

const objectParser = createParser({
  parse: (value: string) => (value ? JSON.parse(value) : {}),
  serialize: (value: object) =>
    Object.keys(value || {}).length ? JSON.stringify(value) : "",
});

// Parser for advanced filters
const advancedFiltersParser = createParser({
  parse: (value: string) => {
    try {
      return value ? JSON.parse(value) : [];
    } catch {
      return [];
    }
  },
  serialize: (value: AdvancedFiltersState) =>
    value?.length ? JSON.stringify(value) : "",
});

// Using URL state as the single source of truth - no Jotai atoms

/**
 * Interface for pagination parameters
 */
interface PaginationParams {
  /**
   * Current page index (0-based)
   */
  pageIndex?: number;

  /**
   * Number of items per page
   */
  pageSize?: number;
}

/**
 * Options for the useTableUrlState hook
 */
interface UseTableUrlStateOptions {
  /**
   * Whether URL state management is enabled
   * @default true
   */
  enabled?: boolean;

  /**
   * Unique identifier for the table
   */
  tableId: string;
}

/**
 * Hook for managing table state through URL parameters using nuqs
 * Enables shareable table configurations and server-side processing
 *
 * @param options - Configuration options
 * @returns Object with URL state utilities and parameters
 */
export function useTableUrlState({
  enabled: _enabled = true,
  tableId,
}: UseTableUrlStateOptions) {
  // Track if we're currently syncing to prevent loops
  const isSyncing = useRef(false);

  // Batch update queue
  const updateQueue = useRef<Array<() => void>>([]);
  const batchTimeout = useRef<ReturnType<typeof setTimeout> | null>(null);

  // Process batched updates
  const processBatchedUpdates = useCallback(() => {
    if (updateQueue.current.length === 0) {
      return;
    }

    isSyncing.current = true;
    try {
      // Execute all queued updates
      for (const update of updateQueue.current) {
        update();
      }
    } finally {
      updateQueue.current = [];
      isSyncing.current = false;
    }
  }, []);

  // Helper function to queue URL parameter updates
  const queueUrlUpdate = useCallback(
    <T>(setter: (value: T) => void, updateValue: T) => {
      if (isSyncing.current) {
        return;
      }

      updateQueue.current.push(() =>
        // Pass shallow replace options to avoid full navigation and keep focus
        (setter as unknown as (value: T, options?: unknown) => void)(
          updateValue,
          { shallow: true, history: "replace", scroll: false }
        )
      );

      // Clear existing timeout
      if (batchTimeout.current !== null) {
        clearTimeout(batchTimeout.current);
      }

      // Schedule batch update (SSR-safe)
      batchTimeout.current = setTimeout(processBatchedUpdates, 0);
    },
    [processBatchedUpdates]
  );

  // URL parameters using nuqs
  // View and history management
  const [viewParam, setViewParam] = useQueryState("view");
  const [historyIndexParam, setHistoryIndexParam] = useQueryState(
    "historyIndex",
    {
      defaultValue: "0",
    }
  );

  // Table state parameters
  const [sortParam, setSortParam] = useQueryState(
    `${tableId}-sort`,
    arrayParser
  );

  const [filtersParam, setFiltersParam] = useQueryState(
    `${tableId}-filters`,
    arrayParser
  );

  // Advanced filters parameter
  const [advancedFiltersParam, setAdvancedFiltersParam] = useQueryState(
    `${tableId}-advancedFilters`,
    advancedFiltersParser
  );

  const [pageParam, setPageParam] = useQueryState(`${tableId}-page`, {
    defaultValue: "0",
  });

  const [pageSizeParam, setPageSizeParam] = useQueryState(
    `${tableId}-pageSize`,
    {
      defaultValue: "10",
    }
  );

  const [visibilityParam, setVisibilityParam] = useQueryState(
    `${tableId}-visibility`,
    objectParser
  );

  const [orderParam, setOrderParam] = useQueryState(
    `${tableId}-order`,
    arrayParser
  );

  const [expandedParam, setExpandedParam] = useQueryState<object>(
    `${tableId}-expanded`,
    createParser({
      parse: (value: string) => {
        try {
          if (!value) {
            return {};
          }
          // Handle double-encoded values robustly
          const safeDecode = (input: string): string => {
            let out = input;
            for (let i = 0; i < 2; i++) {
              try {
                const dec = decodeURIComponent(out);
                if (dec === out) {
                  break;
                }
                out = dec;
              } catch {
                break;
              }
            }
            return out;
          };
          const decoded = safeDecode(value);
          const parsed = JSON.parse(decoded);
          if (typeof parsed === "object" && parsed !== null) {
            return parsed as object;
          }
          return {};
        } catch {
          return {};
        }
      },
      serialize: (value: object) => {
        const safe = value || {};
        return Object.keys(safe).length
          ? encodeURIComponent(JSON.stringify(safe))
          : "";
      },
    })
  );

  const [groupingParam, setGroupingParam] = useQueryState(
    `${tableId}-grouping`,
    arrayParser
  );

  // Global search parameter (server-side global filter)
  const [globalSearchParam, setGlobalSearchParam] = useQueryState(
    `${tableId}-q`
  );

  // Column pinning parameter
  const [pinningParam, setPinningParam] = useQueryState(`${tableId}-pinning`, {
    defaultValue: "",
    parse: (value) =>
      value ? JSON.parse(decodeURIComponent(value)) : { left: [], right: [] },
    serialize: (value) => {
      // Only serialize if we have pinned columns
      const hasLeft = value?.left?.length > 0;
      const hasRight = value?.right?.length > 0;
      return hasLeft || hasRight
        ? encodeURIComponent(JSON.stringify(value))
        : "";
    },
  });

  type TableParamValue =
    | ColumnFiltersState
    | SortingState
    | Record<string, boolean>
    | string[]
    | AdvancedFiltersState
    | string;

  const debouncedSetParamRef = useRef<
    ((key: string, value: TableParamValue) => void) | null
  >(null);

  // Create debounced setter on mount
  useEffect(() => {
    if (!debouncedSetParamRef.current) {
      debouncedSetParamRef.current = debounce((...args: unknown[]) => {
        const [key, value] = args as [string, TableParamValue];
        if (key.includes("filters") && !key.includes("advancedFilters")) {
          (
            setFiltersParam as unknown as (
              v: ColumnFiltersState,
              o?: unknown
            ) => void
          )(value as ColumnFiltersState, {
            shallow: true,
            history: "replace",
            scroll: false,
          });
        } else if (key.includes("advancedFilters")) {
          (
            setAdvancedFiltersParam as unknown as (
              v: AdvancedFiltersState,
              o?: unknown
            ) => void
          )(value as AdvancedFiltersState, {
            shallow: true,
            history: "replace",
            scroll: false,
          });
        } else if (key.includes("sort")) {
          (setSortParam as unknown as (v: SortingState, o?: unknown) => void)(
            value as SortingState,
            {
              shallow: true,
              history: "replace",
              scroll: false,
            }
          );
        } else if (key.endsWith("-q")) {
          (setGlobalSearchParam as unknown as (v: string, o?: unknown) => void)(
            value as unknown as string,
            {
              shallow: true,
              history: "replace",
              scroll: false,
            }
          );
        }
        // Add other param setters as needed
      }, 150);
    }
  }, [
    setFiltersParam,
    setAdvancedFiltersParam,
    setSortParam,
    setGlobalSearchParam,
  ]);

  const setColumnFiltersFromUI = useCallback(
    (filters: ColumnFiltersState) => {
      debouncedSetParamRef.current?.(`${tableId}-filters`, filters);
    },
    [tableId]
  );

  // Advanced filters setter
  const setAdvancedFiltersFromUI = useCallback(
    (filters: AdvancedFiltersState) => {
      // Write as-is; server/mock layer ignores inactive or empty filters
      debouncedSetParamRef.current?.(`${tableId}-advancedFilters`, filters);
    },
    [tableId]
  );

  const setSorting = useCallback(
    (sorting: SortingState) => {
      debouncedSetParamRef.current?.(`${tableId}-sort`, sorting);
    },
    [tableId]
  );

  // Global search setter
  const setGlobalSearchFromUI = useCallback(
    (value: string) => {
      debouncedSetParamRef.current?.(`${tableId}-q`, value || "");
    },
    [tableId]
  );

  // Method to reset all filters
  const resetFilters = useCallback(() => {
    queueUrlUpdate(setFiltersParam, []);
    queueUrlUpdate(setAdvancedFiltersParam, []);
  }, [queueUrlUpdate, setFiltersParam, setAdvancedFiltersParam]);

  // Method to reset only advanced filters
  const resetAdvancedFilters = useCallback(() => {
    queueUrlUpdate(setAdvancedFiltersParam, []);
  }, [queueUrlUpdate, setAdvancedFiltersParam]);

  // Methods for other URL parameters
  const setPaginationFromUI = useCallback(
    (paginationParams: PaginationParams) => {
      // Use default values if pageIndex or pageSize are undefined
      const pageIndex = paginationParams.pageIndex ?? 0;
      const pageSize = paginationParams.pageSize ?? 10;

      // Always update with valid values
      queueUrlUpdate(setPageParam, pageIndex.toString());
      queueUrlUpdate(setPageSizeParam, pageSize.toString());
    },
    [queueUrlUpdate, setPageParam, setPageSizeParam]
  );

  const setVisibilityFromUI = useCallback(
    (visibility: Record<string, boolean>) => {
      queueUrlUpdate(setVisibilityParam, visibility);
    },
    [queueUrlUpdate, setVisibilityParam]
  );

  const setOrderFromUI = useCallback(
    (order: string[]) => {
      queueUrlUpdate(setOrderParam, order);
    },
    [queueUrlUpdate, setOrderParam]
  );

  const setExpandedFromUI = useCallback(
    (expanded: Record<string, boolean>) => {
      // Apply immediately to avoid race conditions with grouping/expansion
      setExpandedParam(expanded);
    },
    [setExpandedParam]
  );

  const setGroupingFromUI = useCallback(
    (grouping: string[]) => {
      // Apply immediately to keep TanStack grouping in sync with UI without batching lag
      setGroupingParam(grouping);
    },
    [setGroupingParam]
  );

  // Handler for column pinning changes from UI
  const setPinningFromUI = useCallback(
    (pinning: { left: string[]; right: string[] }) => {
      queueUrlUpdate(setPinningParam, pinning);
    },
    [queueUrlUpdate, setPinningParam]
  );

  // Helper function to set URL parameter if value exists
  const setUrlParam = useCallback(
    (url: URL, paramName: string, value: unknown, condition?: boolean) => {
      if (condition === false) {
        return;
      }

      if (Array.isArray(value) && value.length > 0) {
        url.searchParams.set(
          paramName,
          encodeURIComponent(JSON.stringify(value))
        );
      } else if (
        typeof value === "object" &&
        value &&
        Object.keys(value).length > 0
      ) {
        url.searchParams.set(
          paramName,
          encodeURIComponent(JSON.stringify(value))
        );
      } else if (typeof value === "string" && value) {
        url.searchParams.set(paramName, value);
      }
    },
    []
  );

  // Helper function to set table-specific parameters
  const setTableParams = useCallback(
    (url: URL) => {
      setUrlParam(url, `${tableId}-sort`, sortParam);
      setUrlParam(url, `${tableId}-filters`, filtersParam);
      setUrlParam(url, `${tableId}-advancedFilters`, advancedFiltersParam);
      setUrlParam(url, `${tableId}-q`, globalSearchParam);
      setUrlParam(url, `${tableId}-page`, pageParam);
      setUrlParam(url, `${tableId}-pageSize`, pageSizeParam);
      setUrlParam(url, `${tableId}-visibility`, visibilityParam);
      setUrlParam(url, `${tableId}-order`, orderParam);
      setUrlParam(url, `${tableId}-expanded`, expandedParam);
      setUrlParam(url, `${tableId}-grouping`, groupingParam);

      // Special case for pinning
      if (
        pinningParam &&
        (pinningParam.left?.length || pinningParam.right?.length)
      ) {
        setUrlParam(url, `${tableId}-pinning`, pinningParam, true);
      }
    },
    [
      tableId,
      sortParam,
      filtersParam,
      advancedFiltersParam,
      pageParam,
      pageSizeParam,
      visibilityParam,
      orderParam,
      expandedParam,
      groupingParam,
      globalSearchParam,
      pinningParam,
      setUrlParam,
    ]
  );

  // Create shareable URL with all parameters
  const createShareableUrl = useCallback(() => {
    if (typeof window === "undefined") {
      return "";
    }
    const url = new URL(window.location.href);

    // Add view and history parameters
    setUrlParam(url, "view", viewParam);
    setUrlParam(url, "historyIndex", historyIndexParam);

    // Add all table-specific parameters
    setTableParams(url);

    return url.toString();
  }, [viewParam, historyIndexParam, setUrlParam, setTableParams]);

  // Reset all URL state parameters
  const resetUrlState = useCallback(() => {
    if (isSyncing.current) {
      return;
    }

    try {
      isSyncing.current = true;
      // Reset all URL parameters
      setViewParam(null);
      setHistoryIndexParam("0");
      setSortParam([]);
      setFiltersParam([]);
      setAdvancedFiltersParam([]);
      setPageParam("0");
      setPageSizeParam("10");
      setVisibilityParam({});
      setOrderParam([]);
      setExpandedParam({});
      setGroupingParam([]);
      setPinningParam({ left: [], right: [] });
    } finally {
      // Schedule after paint (SSR-safe)
      const schedule =
        typeof window !== "undefined" &&
        typeof window.requestAnimationFrame === "function"
          ? window.requestAnimationFrame
          : (cb: FrameRequestCallback) =>
              setTimeout(cb, 0) as unknown as number;
      schedule(() => {
        isSyncing.current = false;
      });
    }
  }, [
    setViewParam,
    setHistoryIndexParam,
    setSortParam,
    setFiltersParam,
    setAdvancedFiltersParam,
    setPageParam,
    setPageSizeParam,
    setVisibilityParam,
    setOrderParam,
    setExpandedParam,
    setGroupingParam,
    setPinningParam,
  ]);

  // Get pagination state from URL parameters
  const pagination = useMemo(
    () => ({
      pageIndex: Number.parseInt(pageParam || "0", 10),
      pageSize: Number.parseInt(pageSizeParam || "10", 10),
    }),
    [pageParam, pageSizeParam]
  );

  // Cleanup timeout on unmount
  useEffect(() => {
    return () => {
      if (batchTimeout.current !== null) {
        clearTimeout(batchTimeout.current);
      }
    };
  }, []);

  return {
    // Utility functions
    createShareableUrl,
    // Raw URL parameters
    advancedFiltersParam: advancedFiltersParam || [],
    expandedParam,
    filtersParam: filtersParam || [],
    groupingParam: groupingParam || [],
    historyIndexParam,
    orderParam: orderParam || [],
    pageParam: pageParam || "0",
    pageSizeParam: pageSizeParam || "10",
    // Processed state
    pagination,
    pinningParam,
    resetAdvancedFilters,
    resetFilters,

    resetUrlState,

    // Setter functions for UI components
    setAdvancedFiltersFromUI,
    setAdvancedFiltersParam,
    setColumnFiltersFromUI,
    setExpandedFromUI,
    setGlobalSearchFromUI,
    // Raw setters (should generally not be used directly)
    setExpandedParam,
    setFiltersParam,
    setGroupingFromUI,
    setGroupingParam,
    setHistoryIndexParam,
    setOrderFromUI,

    setOrderParam,
    setPageParam,
    setPageSizeParam,
    setPaginationFromUI,
    setPinningFromUI,
    setPinningParam,
    setSorting,
    setSortParam,
    setViewParam,
    setVisibilityFromUI,
    setVisibilityParam,

    sortParam: sortParam || [],
    globalSearchParam: globalSearchParam || "",
    viewParam,
    visibilityParam: visibilityParam || {},
  };
}

// Helper function to ensure consistent property order in sorting objects
function _normalizeSortingObject(sort: { desc: boolean; id: string }) {
  // TanStack Table requires sorting objects to have 'id' property first, then 'desc'
  // eslint-disable-next-line perfectionist/sort-objects
  return { id: sort.id, desc: sort.desc };
}

