/**
 * Utility functions for column pinning styles
 * Based on TanStack Table column pinning example
 */
"use client";

import type { Column } from "@tanstack/react-table";
import type { CSSProperties } from "react";

/**
 * Get common styles for pinned columns
 * @param column - The column to get styles for
 * @returns CSS properties for the column
 */
export function getColumnPinningStyles<TData>(
  column: Column<TData>
): CSSProperties {
  const isPinned = column.getIsPinned();
  const _isLastLeftPinnedColumn =
    isPinned === "left" && column.getIsLastColumn("left");
  const _isFirstRightPinnedColumn =
    isPinned === "right" && column.getIsFirstColumn("right");

  return {
    // Position the column based on its pinning
    left: isPinned === "left" ? `${column.getStart("left")}px` : undefined,
    // Slight opacity difference for pinned columns
    opacity: isPinned ? 0.95 : 1,
    // Make pinned columns sticky
    position: isPinned ? "sticky" : "relative",
    right: isPinned === "right" ? `${column.getAfter("right")}px` : undefined,
    // Set width based on column size
    width: column.getSize(),
    // Ensure pinned columns appear above other content
    zIndex: isPinned ? 1 : 0,
  };
}

/**
 * Utilities for handling server-side filtering in DataTable
 */
"use client";

/**
 * Interface for complex filter objects
 */
interface ComplexFilter {
  id: string;
  operator: string;
  value: string;
}

/**
 * Interface for filter objects
 */
interface Filter {
  id: string;
  value: unknown;
}

/**
 * Apply complex filters on the client side
 * @param data Array of data items
 * @param complexFilters Array of complex filters to apply
 * @returns Filtered data
 */
export function applyComplexFilters<T>(
  data: T[],
  complexFilters: ComplexFilter[]
) {
  // If no complex filters, return data as is
  if (complexFilters.length === 0) {
    return data;
  }

  // Apply each complex filter
  return data.filter((item) => {
    // Item must match all complex filters
    return complexFilters.every((filter) => {
      const fieldValue = String(
        (item as Record<string, unknown>)[filter.id] || ""
      ).toLowerCase();

      // Apply the appropriate operator (filter.value already lowercased where needed)
      const filterVal = filter.value.toLowerCase();
      switch (filter.operator) {
        case "contains":
          return fieldValue.includes(filterVal);
        case "equals":
          return fieldValue === filterVal;
        case "startsWith":
          return fieldValue.startsWith(filterVal);
        case "endsWith":
          return fieldValue.endsWith(filterVal);
        case "notContains":
          return !fieldValue.includes(filterVal);
        case "isEmpty":
          return !fieldValue || fieldValue.trim() === "";
        case "isNotEmpty":
          return Boolean(fieldValue && fieldValue.trim() !== "");
        default:
          return true; // Unknown operator, don't filter
      }
    });
  });
}

/**
 * Apply pagination to filtered data
 * @param data Array of filtered data
 * @param pageIndex Current page index (0-based)
 * @param pageSize Number of items per page
 * @returns Paginated data and pagination info
 */
export function applyPagination<T>(
  data: T[],
  pageIndex: number,
  pageSize: number
) {
  const startIndex = pageIndex * pageSize;
  const endIndex = startIndex + pageSize;
  const paginatedData = data.slice(startIndex, endIndex);

  return {
    data: paginatedData,
    pageCount: Math.ceil(data.length / pageSize),
    rowCount: data.length,
  };
}

// Helper function to process object-type filter values
function _processObjectFilter(
  filter: Filter,
  serverFilters: Record<string, unknown>,
  complexFilters: ComplexFilter[]
) {
  const valueObj = filter.value as Record<string, unknown>;

  if (valueObj.contains !== undefined) {
    // For 'contains' operator, store for client-side filtering
    complexFilters.push({
      id: filter.id,
      operator: "contains",
      value: String(valueObj.contains || "").toLowerCase(),
    });
    // Also add to serverFilters in a format the server can understand
    serverFilters[filter.id] = { contains: valueObj.contains };
  } else if (valueObj.value !== undefined) {
    // Use only the value part, not the operator
    serverFilters[filter.id] = valueObj.value;
  } else if (valueObj.equals !== undefined) {
    // For 'equals' operator, use the exact value
    complexFilters.push({
      id: filter.id,
      operator: "equals",
      value: String(valueObj.equals),
    });
    // Add to serverFilters in a format the server can understand
    serverFilters[filter.id] = valueObj.equals;
  } else if (valueObj.startsWith !== undefined) {
    // For 'startsWith' operator, use the exact value
    complexFilters.push({
      id: filter.id,
      operator: "startsWith",
      value: String(valueObj.startsWith),
    });
    // Add to serverFilters in a format the server can understand
    serverFilters[filter.id] = valueObj.startsWith;
  } else if (valueObj.endsWith !== undefined) {
    // For 'endsWith' operator, use the exact value
    complexFilters.push({
      id: filter.id,
      operator: "endsWith",
      value: String(valueObj.endsWith),
    });
    // Add to serverFilters in a format the server can understand
    serverFilters[filter.id] = valueObj.endsWith;
  }
}

/**
 * Process filters for server-side filtering
 * Handles complex filters like 'contains', 'startsWith', etc.
 * @param filters Array of filter objects from DataTable
 * @returns Object with processed filters and complex filters that need client-side processing
 */
export function processServerFilters(filters: Filter[]) {
  const serverFilters: Record<string, unknown> = {};
  const complexFilters: ComplexFilter[] = [];

  // Process each filter
  for (const filter of filters) {
    // Handle different filter types based on the value
    if (typeof filter.value === "object" && filter.value !== null) {
      _processObjectFilter(filter, serverFilters, complexFilters);
    } else if (filter.value !== undefined && filter.value !== "") {
      // For simple equality filters
      serverFilters[filter.id] = filter.value;
    }
  }

  return { complexFilters, serverFilters };
}

/**
 * Utilities for handling table configuration transformations
 * Manages conversions between in-memory TanStack Table state and database-storable format
 */

// Import TanStack Table types
import type {
  ColumnFiltersState,
  ColumnOrderState,
  SortingState,
} from "@tanstack/react-table";
// Import TableViewConfig type from types
import type { TableViewConfig } from "../types/view-types";

/**
 * Type definition for a serialized table configuration
 * Ensures all properties are JSON-serializable
 */
export interface SerializedTableViewConfig {
  columnFilters?: string; // JSON string of filter configurations
  columnOrder?: string; // JSON string of column order
  columnVisibility?: string; // JSON string of column visibility
  sorting?: string; // JSON string of sort configuration
}

// Define ColumnVisibilityState type if it's not exported from @tanstack/react-table
type ColumnVisibilityState = Record<string, boolean>;

/**
 * Utilities for table configuration
 * Handles conversion between in-memory state and database-storable format
 */
export const tableConfigUtils = {
  /**
   * Determines if two configurations are equivalent
   * Useful for detecting if changes have been made
   * @param config1 - First configuration to compare
   * @param config2 - Second configuration to compare
   * @returns True if configurations are equivalent
   */
  areEqual: (config1: TableViewConfig, config2: TableViewConfig): boolean => {
    return JSON.stringify(config1) === JSON.stringify(config2);
  },

  /**
   * Creates a deep clone of a configuration
   * @param config - Configuration to clone
   * @returns Deep copy of the configuration
   */
  clone: (config: TableViewConfig): TableViewConfig => {
    return JSON.parse(JSON.stringify(config)) as TableViewConfig;
  },

  /**
   * Converts a serialized configuration from storage to a usable TableViewConfig
   * @param serializedConfig - Configuration as stored in the database
   * @returns TableViewConfig object ready for use with TanStack Table
   */
  fromStorage: (
    serializedConfig: SerializedTableViewConfig | string
  ): TableViewConfig => {
    // If the input is a string, parse it as JSON
    let config: SerializedTableViewConfig;
    try {
      if (typeof serializedConfig === "string") {
        config = JSON.parse(serializedConfig) as SerializedTableViewConfig;
      } else {
        config = serializedConfig;
      }
    } catch (_error) {
      // Return empty config if parsing fails
      return {};
    }

    // Parse column filters and ensure they have the correct structure
    let columnFilters: ColumnFiltersState | undefined;
    if (config.columnFilters) {
      try {
        // Handle the case where columnFilters might already be an object
        const parsedFilters =
          typeof config.columnFilters === "string"
            ? JSON.parse(config.columnFilters)
            : config.columnFilters;

        // Ensure each filter has the correct structure
        if (Array.isArray(parsedFilters)) {
          columnFilters = parsedFilters.map((filter: unknown) => {
            const filterObj = filter as { id?: unknown; value?: unknown };
            // Make sure the ID is a string
            const id =
              typeof filterObj.id === "string"
                ? filterObj.id
                : String(filterObj.id || "");
            return {
              id,
              value: filterObj.value,
            };
          });
        } else {
          columnFilters = [];
        }
      } catch (_error) {
        columnFilters = [];
      }
    }

    // Helper function to safely parse JSON or handle already parsed objects
    const safelyParse = <T>(value: unknown, defaultValue: T): T => {
      if (!value) {
        return defaultValue;
      }

      try {
        if (typeof value === "string") {
          return JSON.parse(value) as T;
        }
        // If it's already an object, return it directly
        return value as T;
      } catch (_error) {
        return defaultValue;
      }
    };

    // Create TableViewConfig with parsed JSON properties
    return {
      columnFilters,
      columnOrder: safelyParse<ColumnOrderState>(config.columnOrder, []),
      columnVisibility: safelyParse<ColumnVisibilityState>(
        config.columnVisibility,
        {}
      ),
      sorting: safelyParse<SortingState>(config.sorting, []),
    };
  },

  /**
   * Converts a TableViewConfig to a format that can be stored in the database
   * @param config - In-memory TableViewConfig used by TanStack Table
   * @returns SerializedTableViewConfig ready for database storage
   */
  toStorage: (config: TableViewConfig): SerializedTableViewConfig => {
    // Normalize column filters to ensure only simple data is stored
    const normalizedColumnFilters = config.columnFilters?.map((filter) => {
      // Extract only the essential properties and normalize column IDs
      // This prevents complex objects like functions or module references from being serialized
      let columnId =
        typeof filter.id === "string" ? filter.id : String(filter.id);

      // Clean up Turbopack references if present
      if (columnId.includes("__TURBOPACK_")) {
        // Try to extract a simpler ID from the path
        const simplifiedId = columnId.split("/").pop()?.split("$").pop();
        if (simplifiedId) {
          columnId = simplifiedId;
        }
      }

      return {
        id: columnId,
        value: filter.value,
      };
    });

    // Convert each property to a JSON string for storage
    return {
      columnFilters: normalizedColumnFilters
        ? JSON.stringify(normalizedColumnFilters)
        : undefined,
      columnOrder: config.columnOrder
        ? JSON.stringify(config.columnOrder)
        : undefined,
      columnVisibility: config.columnVisibility
        ? JSON.stringify(config.columnVisibility)
        : undefined,
      sorting: config.sorting ? JSON.stringify(config.sorting) : undefined,
    };
  },
};
